window.__D("text/likkutei-sichot/c120",{"p":[[1300181234,"ה', דערפאַר ווערט דורך זיי ניט אַרויסגעזאָגט בשלימות, אַז אויך דברים גשמיים ווי זיי געפינען זיך אינגאַנצן אין זייער גדר וציור דלמטה, ווערן כלים לאלקות [וכמובן אויך פון דעם וואָס אמחז\"ל (אפילו בנוגע צו צדקה) — אַז נאָכן ציווי אויף מעשרות איז עס אַ חלק פון ממון ונכסים וואָס מלכתחילה געהערט עס ניט צו אים, ס'איז ביי אים בתורת פקדון 66]\nבשעת אָבער די הפרשה ונתינה פון מתנות כהונה ומעשר איז מדגיש, אַז כאָטש די איבערגעבליבענע געהערט צום מענטש, פאַר זיינע הצטרכות'ן, צו באַנוצן זיך מיט זיי איז עס דערפאַר ווייל דער אויבערשטער האָט זיי אים צוגעטיילט — און דערפאַר גופא ווערן זיי דורך איהם (מטה) אויסגענוצט אַזוי ווי דער אויבערשטער וויל —\nדורך דעם דוקא איז ער מגלה אַז אויך דברים גשמיים ממש ווי זיי בלייבן איינ־גאַנצן אַ רכוש פון מענטשן, אין דער בחי' פון תחתונים, ווערן בפנימיות איינ־גאַנצן פאַרבונדן מיט אלקות, אין אַן אופן פון „בכל דרכיך דעהו\" 67;\nאון דורך דעם פירט זיך אויס די שלימות פון „דירה לו ית' בתחתונים\" 68.\nוי\"ל בדרך אפשר — אַז דאָס גופא איז דער טעם וואָס סיי ביי מתנות כהונה סיי באַ מעשר איז דאָ אַ שיעור קצוב, און אַ מענטש טאָר ניט אַוועקגעבן זיינע גאַנצע נכסים — וואָרום די פאַרבונדנ־קייט מיט אלקות אין די נכסים איז אין אַן אַנדער אופן ווי אין די וואָס ער דאַרף אַוועקגעבן; און דעריבער איז חסה התורה על ממונם של ישראל 69 (כדי זיי זאָלן נתברר ווערן אויף זייער ריכטיקן אופן).\nח. אַ מעין ודוגמא צו די דריי ענינים הנ\"ל (קדשים ממש, רוב (ועיקר) מתנות כהונה ומעשר, און די נכסים וואָס בלייבן באַ דעם מענטשן) אין מדריגות אין אחדות ה' — י\"ל, אַז דאָס זיינען: דער ענין פון יחוד הוי' אחד מלמטה למעלה, הוי' אחד מלמעלה למטה 70, יחוד יחו\"ע ויחו\"ת 71.\nדער ענין פון הוי' אחד (בדרך עלי') מלמטה למעלה איז, אַז אויך נאָך התהוות העולמות זיינען די עולמות בטל במציאות בתכלית פונקט ווי קודם ההתהוות; ד. ה. אַז נבראים זיינען באמת קיין מציאות ניט און זייער אמת'ע מציאות איז ווי זיי זיינען למעלה (אין אצילות).\nוואָס דאָס רופט אַרויס די עבודה פון פרישות והפשטה פון עניני העולם — חיי (ועבודת) הצדיקים 72 וואָס זיינען מופשט פון ענינים גשמיים.",[["66","66","ראה ד\"ה א\"ר שמואל בר נחמני תר\"ץ פ\"ג (נדפס בסה\"מ קונטרסים ח\"א קיט, א)."],["67","67","עיין <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא ספ\"ג</a>."],["68","68","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051087\" data-slug=\"likkutei-sichot\" data-id=\"1300051087\">לקו\"ש ח\"ה ע' 75</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201348\" data-slug=\"likkutei-sichot\" data-id=\"1300201348\">ח\"כ ע' 335</a>."],["69","69","ראה רמב\"ם סוף הל' ערכין וחרמין (ר\"ה כז, א. וש\"נ). ולהעיר מכש\"ט סי' רי\"ח. צואת הריב\"ש סי' ק\"ט. או\"ת להה\"מ קא, ד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171229\" data-slug=\"likkutei-sichot\" data-id=\"1300171229\">לקו\"ש חי\"ז ע' 229</a> ואילך."],["70","70","להעיר מ<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830011\" data-slug=\"or-hatorah-hb\" data-id=\"8158830011\">אוה\"ת פרשתנו ע' תרצז</a> „אבל קרח רצה שישאר ההבדלה וזהו מחלוקת והבדל שאינה לש\"ש שלא יתייחדו זו\"נ כו' אבל שמאי והלל מחלוקת לש\"ש יחוד זו\"נ רק ביחוד זה יש מלמעלמ\"ט ומלמטלמ\"ע כו'\". וראה שם ד\"ה להבין בסופו (ע' תשד ואילך)."],["71","71","בהבא לקמן — ראה המשך תרס\"ו ס\"ע קנג ואילך. ע' רכח. רמב. תורת שלום ע' 51 ואילך. 184 ואילך (וראה שם ע' 196 ואילך ב' אופנים אלו בעצמות). וראה ד\"ה סמוכים לעד פר\"ת פ\"ב בהגה\"ה."],["72","72","ראה אגה\"ק סכ\"ז בהביאור."]]],[1300181235,"דער צווייטער אופן פון „הוי' אחד (בדרך המשכה) מלמעלה למטה\" 73 איז ווי אלקות איז מתפשט ומלובש אין יעדער זאַך, ד. ה. ס'איז פאַראַן אַ מציאות פון וועלט אָבער די מציאות גופא איז אלקות. און די דרגא פון יחוד רופט אַרויס אין עבודה (ניט אָפּצושיידן זיך פון וועלט, נאָר אדרבה): צו טאָן מיט דברים גשמיים — ער איז נהנה פון דער דבר גשמי, נאָר די הנאה איז אַ הנאה אלקית.\nאָבער אויך דער יחוד, כאָטש ער איז מיט'ן דבר גשמי, דערהערט ער עס אָבער ווי צוויי באַזונדערע זאַכן שנתאחדו — אלקות און דבר גשמי,\nמצד דעם יחוד פון יחו\"ע ויחו\"ת איז נרגש ווי די מציאות הגשמי און זיין עשי' (והנאה) ווערן אַן ענין פון אלקות.\nט. ע\"פ כהנ\"ל קען מען מבאר זיין די שייכות פון ג' תמוז דוקא — צו פ' קרח:\nבי\"ב וי\"ג תמוז, ווען מ'האָט דעם רבי'ן אינגאַנצן באַפרייט, אויך פון גלות קאָסטראָמאַ, דריקט זיך ניט אויס בשלימות ווי די אַרבעט פון הרבצת התורה והיהדות האָט געפועלט אויך אויף די „תחתונים\" וואָס האָבן אים אַרעסטירט, אַז אויך זיי זאָלן אויף דעם מסכים זיין; וואָרום דעמולט איז דאָך דער רבי בגלוי אַרויס פון זייערע ד' אמות (כאָטש אַז במדינה ההיא בכלל — האָבן זיי געטאָן קעגן אידן און אידיש־קייט).\nדוקא בג' תמוז ווען זיי האָבן אים פאַרשיקט אין גלות קאָסטראָמאַ, און פאָרנדיק אַהין האָט ער (נאָך פאַר'ן אָנקומען אַהין) איינגעאָרדענט אַז מ'זאָל דאָרטן צונויפקלייבן אינגלאַך און מאַכן אַ חדר, פאַרריכטן די מקוה 74 און געזאָגט חסידות דאָרטן וכו' 75 —\nדוקא אין דעם האָט זיך אויסגע־דריקט אַז תחתונים ממש, ווי זיי שטייען נאָך אין זייער נידעריקסטן ציור (זיי האַלטן נאָך דעם רבי'ן באַ זיך אין גלות) זיינען „מסכים\" אויף הרבצת התורה והיהדות פון רבי'ן —\nבדוגמא צו שלימות התיקון וואָס האָט אַראָפּגענומען און מבטל געווען מחלוקת קרח, אַז אויך די דברים גשמיים, ווי זיי זיינען אין זייער מציאות פון תחתונים ממש, זיינען זיי בפנימיותם — אלקות.\nיו\"ד. ע\"פ כהנ\"ל י\"ל, אַז די דריי ענינים הנ\"ל (וואָס האָבן מבטל געווען און מתקן געווען מחלוקת קרח) זיינען בכללות מרומז אויך אין דער תורה וואָס דער רבי האָט געזאָגט אַרויסגייענדיק פון תפיסה, פאַרן אָפּפאָרן אין קאָסט־ראָמאַ 76:\nמיר בעטן, באַ השי\"ת, יהי ה' אלקינו עמנו כאשר הי' עם אבותינו אל יעזבנו ואל יטשנו 77 השי\"ת זאָל זיין מיט אונז און וועט זיין מיט אונז כאשר הי' עם אבותינו, הגם מיר זיינען דאָך ניט גלייך צו אבותינו, וועלכע זיינען געווען בעלי מסירת נפש בפועל ממש צוליעב תורה און מצות וכו'.\nובהקדים — דלכאורה דאַרף מען פאַרשטיין: א) אין לשון הבקשה „יהי ה'",[["73","73","ואופן זה הוא במדרי' נעלית יותר מאופן הא' (המשך שם ע' רמב)."],["74","74","ראה לקו\"ש ח\"ד ע' 1063."],["75","75","ד\"ה גפן ממצרים — נדפס בסה\"מ קונטרסים ח\"א ע' 352."],["76","76","נדפס שם ע' 350."],["77","77","מ\"א ח, נז."]]],[1300181236,"אלקינו עמנו גו'\": בשלמא שם הוי' וואָס מיינט אַז דער אויבערשטער איז הי' הוה ויהי' (ברגע אחד) 78 — אלקות וואָס איז העכער פון האָבן אַ שייכות צו וועלט דאַרף מען נאָכדעם מוסיף זיין און מודיע זיין אַז ער איז „עמנו\"; משא\"כ שם אלקים וואָס זיין טייטש איז אַז ער איז „תקיף ואמיץ אשר לו היכולת בעליונים ובתחתונים\" 78, און „אלקינו\" איז דאָך דער פירוש אַז דער אויבערשטער איז כוחנו וחיותנו, ווייזט עס דאָך אַז דער אויבערשטער איז מיט אונז — איז לכאורה ניט נויטיק צו מוסיף זיין דעם וואָרט „עמנו\", אָדער עס האָט געדאַרפט שטיין „יהי ה' עמנו\" ?\nב) „יהי ה\"א עמנו\" — איז דאָך שלא בערך מער פון „אל יעזבנו ואל יטשנו\".\nג) דער רבי האָט געזאָגט „הגם מיר זיינען דאָך ניט גלייך צו אבותינו וועלכע זיינען געווען בעלי מסירת נפש בפועל ממש אויף תורה און מצות\" — דלכאורה: ביים רבי'ן איז דאָך אין יענע זמנים געווען דער ענין פון מסירת נפש בפועל (און אפילו זיצנדיק אין תפיסה ולאח\"ז); איז אפילו מ'זאָל זאָגן אַז מצד דער ענוה פון רבי'ן האָט ער געהאַלטן אַז זיין מסירת נפש איז ניט גלייך צו דער מסירת נפש פון „אבותינו\", האָט ער אָבער דאָך ניט געדאַרפט דאָס זאָגן אין אַ לשון („הגם מיר זיינען דאָך ניט גלייך צו אבותינו וועלכע זיינען געווען בעלי מסירת נפש בפועל ממש\") וואָס איז שולל אינגאַנצן די מסנ\"פ בפועל ממש.\nיא. איז דער ביאור אין דעם: דער רבי האָט געוואָלט פועל זיין דעם ענין הגאולה ביי אַלע אידן, ביז אויך ביי די וואָס זיינען נאָר „בשם ישראל יכונה\" 79, און דעריבער האָט ער געבראַכט דוקא דעם לשון הפסוק „יהי הוי' אלקינו עמנו\" מיט דער הוספה „הגם מיר זיינען דאָך ניט גלייך צו אבותינו כו'\" — ד. ה. אַז אויך אַזעלכע אידן וואָס זיינען ניט גלייך צו אבותינו (ביי זיי איז ניטאָ דער ענין המסנ\"פ בפועל אויף תומ\"צ) זאָל ביי זיי זיין „הוי' אלקינו עמנו כאשר הי' עם אבותינו\";\nולפי הנ\"ל — אַז דער רבי האָט גע־וואָלט אויפטאָן די גאולה אויך ביי די וואָס זיינען נאָר „בשם ישראל יכונה\", ניט קוקנדיק אויף זייער מצב אין שמירת התומ\"צ — קען מען זאָגן, אַז מיט דער הוספה „הגם מיר זיינען דאָך ניט גלייך צו אבותינו\" האָט דער רבי געמיינט מרמז צו זיין צום פירוש המדרש 80 „וכן שלמה אומר לפני הקב\"ה מלך שהוא שוכר פועלים והן עושין מלאכתן יפה ונותן להם שכרן מה שבח יש למלך, ואימתי הוא משובח כשישכור פועלים רעים שאין עושין מלאכתן ונותן להן שכרן וזו היא טובה גדולה וכה\"א יהי ה\"א עמנו כאשר הי' עם אבותינו\" — ד. ה. ער האָט געוואָלט אויפטאָן ענין הגאולה אויך ביי „פועלים רעים\".\nיב. ע\"פ זה קען מען מסביר זיין, אַז אין דעם ענין פון „יהי ה\"א עמנו גו'\" זיינען דאָ דריי מדריגות (וי\"ל שהן — ע\"ד ג' מדריגות הנ\"ל):\nא) „הוי' (ווערט) אלקינו\" — אַז דער אויבערשטער איז כוחנו וחיותנו, וואָס דאָס ווייזט אַז די גאַנצע מציאות פון",[["78","78","שו\"ע (ואדה\"ז) או\"ח סי' ה (ס\"ג) — שער היחוה\"א פ\"ז."],["79","79","מכתב הנ\"ל דט\"ו סיון. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081340\" data-slug=\"likkutei-sichot\" data-id=\"1300081340\">לקו\"ש ח\"ח ע' 329</a> ואילך, וש\"נ."],["80","80","מדרש תהלים כו."]]],[1300181237,"דעם מענטשן און זיין כח וחיות בגלוי — איז אלקות.\nב) „ה' אלקינו עמנו\" — דער מענטש איז ווי אַ זאַך פאַר זיך, נאָר דער אויבערשטער איז „מיט אים\": אָבער דאָס גופא וואָס „אלקינו\" איז „עמנו\" איז אַ ראי' אַז ער איז פאַרבונדן מיט אלקות.\nג) „אל יעזבנו ואל יטשנו\": כדי אויפצוטאָן אויך אין אַזעלכע אידן וואָס זיינען בבחי' „תחתונים\" ממש — בשם ישראל יכונה — וואָס עס זעט זיך ביי זיי כלל ניט אָן זייער שייכות צו אלקות 81, אַז אויך ביי זיי זאָל זיין דער ענין הגאולה, האָט דער רבי מוסיף געווען „כאשר הי' עם אבותינו הגם מיר זיינען ניט גלייך צו אבותינו כו'\" — מיינענדיק צו מרמז זיין אויפן פירוש המדרש כנ\"ל 82, און דערמיט האָט ער אויפגעטאָן אַז אויך ביי די „פועלים רעים\" זאָל זיין עכ\"פ דער הרגש פון „אל יעזבנו ואל יטשנו\" — אַז אויך ווי זיי זיינען אין דעם מצב זאָל זיך אָנזען אַז זיי זיינען ח\"ו ניט אָפּגעזונדערט און פאַרלאָזן פון אויבערשטן.\nאון אין דעם דוקא דריקט זיך אויס ווי אַזוי אויך אַזעלכע, וואָס זיינען תחתונים אין זייער מציאות הנראית והנגלית זיינען שייך צו אלקות: אַז אין וועלכער מדריגה אַ איד געפינט זיך נאָר, איז זיין אמת'ער און פנימיות'דיקע מציאות — אלקות. ובלשון פון רבי'ן 79: כל איש ישראל (מבלי התחשב עם מצבו הפרטי בשמירת וקיום המצות) לבו תמים עם ה' ותורתו.\nאון דאָס האָט געפועלט אויך אויף די „תחתונים\" פון וועלט, אפילו אויף די וואָס האָבן אים אַרעסטירט אַז אויך במעמדם ומצבם זאָלן זיי מסכים זיין צו דער הפצת התורה פון רבי'ן, ביז צו העלפן אין זיין באַפרייאונג וגאולה כפשוטה.\nיג. וויבאַלד אַז הימים האלו נזכרים (ביז אַז) ונעשים 83 האָט יעדערער און אַלע — עמנו — די הוראה ונתינת כח פון ג' תמוז אויף ניט נתפעל ווערן פון מניעות ועיכובים אויף הפצת התורה והיהדות, און מ'האָט אויך די הבטחה (ווי דער צווייטער אָפּטייטש אין „יהי\" „אל יעזבנו ואל יטשנו\") אַז עס וועט מקוים ווערן אַז „יהי ה' אלקינו עמנו כאשר הי' עם אבותינו אל יעזבנו ואל יטשנו ולכל בנ\"י יהי' אור ברוחניות ובגשמיות\" 84.\n(משיחות ש\"פ קרח, ג' תמוז תשכ\"ד. י\"ט כסלו, תשכ\"ה. יום ג' פ' קרח תשל\"ז)",[["81","81","ראה לקו\"ש שם."],["82","82","וי\"ל שלכן אמר מעלת אבותינו שהם היו „בעלי מסירת נפש בפועל ממש\" — אף שאבותינו בכלל מורה על עבודת המוחין (ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא רפ\"ג</a>. וראה ד\"ה יהי ה\"א תש\"י בסופו) — כי ענין המסנ\"פ הרי\"ז דבר השוה בכאו\"א מישראל (ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי\"ח</a>. ואדרבה מעלה יתירה בדור דעקבתא דמשיחא שמקיימים התומ\"צ במסנ\"פ — ראה סה\"מ קונטרסים ח\"א ע' 106 ואילך. סה\"מ תש\"י ע' 237. תשי\"ט ע' 122. ועוד) — וגם זה לא נראה בהם."],["83","83","כידוע פי' האריז\"ל אשר כשהם „נזכרים\" כדבעי הם „נעשים\" (ראה רמ\"ז בספר תיקון שובבים. הובא ונתבאר בספר לב דוד (להחיד\"א) פכ\"ט)."],["84","84","סיום לשון כ\"ק מו\"ח אדמו\"ר בשיחתו ג' תמוז הנ\"ל."]]],[1300181238,"<h3>חוקת</h3>\nא. עס שטייט אין מדרש 1 אויפן פסוק „זאת חוקת התורה“: „ארבעה דברים יצה“ר משיב עליהן דכתיב בהן חוקה אשת אח וכלאים ושעיר המשתלח ופרה אדומה“ 2, וואָס ביי די אַלע גע־פינט מען ענינים וואָס זיינען העכער פון שכל — דברים והיפוכם 3.\nפון דעם אָבער וואָס שלמה האָט גע־זאָגט 4 „על כל אלה עמדתי ופרשה של פרה אדומה חקרתי ושאלתי ופשפשתי אמרתי 4* אחכמה והיא רחוקה ממני“ — אַז נאָר די פרשה פון פרה אדומה האָט ער ניט געקענט משיג זיין, איז מוכח אַז דער עיקר ענין החוקה, וואָס איז ניט עפ“י שכל — „חוקה חקקתי גזירה גזרתי“, איז ביי פרה אדומה דוקא.\nלויט דעם, אַז „חוקת“ הפרה איז אויס־געטיילט פון די אַנדערע חוקים, איז פאַרשטאַנדיק וואָס ביי פרה אדומה שטייט „זאת חוקת התורה“, וואָס דער טייטש כפשוטו איז: „זאת“ דאָס (און ניט קיין אַנדערע) איז די „חוקה“ פון דער תורה 5, ד.ה. אַז אמיתית ענין החוקה פון תורה, וואָס איז (לגמרי) ניט בגדר השגה 6 איז ביי פרה אדומה 7.\nב. עפי“ז דאַרף מען פאַרשטיין וואָס ער זאָגט אין מדרש 8 „אמר לו הקב“ה למשה לך אני מגלה טעם פרה“, וואָס פון דעם איז דאָך מוכח אַז אויך חוקת הפרה האָט אַ טעם — און וויבאַלד אַזוי איז דאָך קשה: א) פאַרוואָס האָט שלמה, וואָס אויף אים שטייט 9 „ויחכם מכל האדם“, ניט געקענט דערגיין דעם טעם פון פרה אדומה ? ב) פאַרוואָס האָט משה רבינו ניט מגלה געווען דעם טעם צו אַלע אידן אַזוי ווי ער האָט עס גע־טאָן מיט „פלפולא“ דאורייתא 10, אַז דער אויבערשטער האָט דאָס געגעבן נאָר צו משה‘ן און פונדעסטוועגן „נהג בה טובת עין“ און ער האָט דאָס געגעבן „לישראל“?",[["1","1","במדב“ר פרשתנו פי“ט, ה. תנחומא כאן ז."],["2","2","וביומא סז, ב: את חוקותי תשמרו דברים שהשטן משיב עליהן ואלו הן אכילת חזיר ולבישת שעטנז וחליצת יבמה וטהרת מצורע ושעיר המשתלח כו‘. וראה השינויים בפרש“י תולדות כו, ה. בשלח טו, כו. אחרי יח, ד."],["3","3","וראה במדב“ר שם (רפי“ט. תנחומא ג) ג“כ ד‘ דוגמאות בעניני טומאה שנמצאו בהם דבר והיפוכו וא‘ מהם „העוסקין בפרה מתחלה ועד סוף מטמאין בגדים היא גופה מטהרת בגדים אמר הקב“ה חוקה חקקתי כו‘“."],["4","4","במדב“ר שם, ג (בסופו). תנחומא ו. 4*) קהלת ז, כג."],["5","5","ראה בארוכה לקו“ש ח“ח (ע‘ 125) שכ“ה גם ע“ד הפשט."],["6","6","ולא מצד הדבר והיפוכו ש„מטהרת את הטמאים ומטמאה את הטהורים“* שהרי בזה: א) שוה הוא לשאר החוקים שבמדרש שם, ב) ה„יצה“ר משיב“, אלא מצד עצם ענין טהרתו כמובן מהמדרש דלקמן הערה 13 וכדלקמן בפנים ס“ז-ח. וראה לקו“ש שם ע“ד הפשט. אבל ראה אוה“ח כאן ד“ה „אשר צוה“ בסופו."],["7","7","הפירוש ב„זאת חוקת התורה“ דפ‘ מטות (לא, כא) — ראה לקו“ש שם ע‘ 183 ואילך. ועפ“י המבואר לקמן בפנים (ס“ז-ח) דחוקה דטהרת פרה אדומה, יובן גם שם."],["8","8","במדב“ר שם, ו. תנחומא ח."],["9","9","מ“א ה, יא. וממשיך שם: „מאיתן האזרחי והימן גו‘“. ובפרש“י שם (מפסיקתא): הימן זה משה."],["10","10","נדרים לח, א. *) וראה לקו“ש שם הערה 17 שע“ד הפשט מובן הוא גם בשכל."]]],[1300181239,"דאַרף מען זאָגן, אַז מניעת הגילוי איז ניט געווען צוליב דעם וואָס משה האָט עס ניט געוואָלט מגלה זיין (אָדער ווייל דער אויבערשטער האָט עס אים ניט גע־הייסן) 11, נאָר צוליב דעם וואָס דער טעם פון פרה אדומה איז ניט בגדר השגה און שכל פון אַ נברא 12; ובמילא איז אויב משה רבינו וואָלט עס מגלה געווען צו אידן, וואָלטן זיי דעם טעם ניט געקענט פאַרשטיין (מקבל זיין), און ווי דער אויבערשטער האָט געזאָגט צו משה‘ן בנוגע צו טהרת פרה אדומה „חוקה היא וגזירה גזרתי ואין כל ברי‘ יכולה לעמוד על גזירתי“ 13.\nאון דעריבער האָט אויך שלמה בחכמ־תו ניט געקענט משיג זיין דעם טעם פון פרה אדומה — „היא רחוקה ממני“ 12. און אפילו משה רבינו, וואָס איז געווען „שלימות מין האנושי“ 14, האָט עס בכח עצמו ניט געקענט משיג זיין, וואָרום דאָס איז ניט בגדר שכל פון אַ נברא,\nנאָר דער אויבערשטער וועלכער איז כל יכול, פאַר אים זיינען ניטאָ קיין שום הגבלות, האָט דער אויבערשטער, מיט זיין כח ויכולת, מגלה געווען צו משה רבינו — „לך אני מגלה טעם פרה“, כאָטש אַז אַ נברא מצ“ע קען צו דעם ניט צוקומען 15.\nלפי זה שטעלט זיך די שאלה: ווי־באַלד אַז משה רבינו האָט משיג געווען דעם טעם פון פרה אדומה ניט בכח עצמו, נאָר דער אויבערשטער האָט עס אים מגלה געווען מיט זיין כח הבלתי מוגבל — האָט דאָך דער אויבערשטער (מיט‘ן זעלבן כח) געקענט מגלה זיין דעם טעם אויך צו אַנדערע.\nג. איז דער ביאור אין דעם:\nס‘איז ידוע 16 דער פירוש אין „זאת חוקת התורה“ (ניט „זאת חוקת הפרה“ וכיו“ב, ווי ער זאָגט 17 „זאת חוקת הפסח“), אַז די מצוה פון פרה אדומה איז „התורה“, כללות התורה; און ווי־באַלד אָט דער ענין איז אויסגעדריקט מיט‘ן וואָרט „חוקה“, איז מובן אַז דאָס וואָס פרה אדומה איז כללות התורה איז עס מצד דעם ענין החוקה וואָס אין איר; עס איז מדגיש אַז דער ענין החוקה (פון פרה אדומה) איז די נקודה כללית פון כל התורה כולה 18.\nדאָס איז סיי בנוגע צו מצוות התורה, סיי בשייכות צו תורה אַליין: מ‘האָט שוין פיל מאָל גערעט 19, אַז אַלע מצות, אויך פון סוג עדות ומשפטים וואָס האָבן אויף זיך אַ טעם שכלי, איז „מהותן“ — רצון העליון וואָס איז העכער פאַר חכמה ושכל; נאָר דער אויבערשטער האָט גע־וואָלט אַז דער רצון פון די מצות זאָל אַראָפקומען און נתלבש ווערן אין חכמה ושכל — אָבער אויך נאָך דער התלב־שות אין אַ טעם שכלי בלייבט דער רצון",[["11","11","אבל ראה אוה“ח שם."],["12","12","ראה ד“ה זאת חוקת תרע“ג בסופו. אבל ראה אוה“ת לקהלת ע‘ רנד. ד“ה יבחר לנו תש“ג פי“א. וראה כלי יקר כאן."],["13","13","קה“ר פ“ח, א (ה). וראה פסיקתא (ופסיקתא דר“כ) פרה."],["14","14","פיה“מ להרמב“ם פ‘ חלק היסוד השביעי. וראה ר“ה כא, ב."],["15","15","ועפ“ז מובן התיווך בין ב‘ פירושי המדרש (אם ידע משה טעם פרה), ומתורצת הערת המפרשים בזה."],["16","16","לקו“ת ריש פרשתנו."],["17","17","בא יב, מג. וראה שמו“ר (פי“ט, ב): שניהם דומים זל“ז בזה נאמר כו‘."],["18","18","ראה אוה“ח כאן."],["19","19","ראה (בהבא לקמן) בארוכה לקו“ש ח“ד ע‘ 1056 ואילך ובהנסמן שם. ח“ח ע‘ 129 ואילך. חי“ג ע‘ 67."]]],[1300181240,"העליון „במהותו ובפשיטותו“ 20 — העכער פון השגה.\nוי“ל אַז אַזוי איז אויך בנוגע צו תורה 21: אויך די ענינים שבתורה וואָס אַ מענטש פאַרשטייט זיי בשכלו, זיינען זיי אין דער אמת‘ן העכער פון גדר השגה. וואָרום תורה איז דאָך חכמתו של הקב“ה, איז דאָך מובן, אַז „כשם 22 שאין ביכולת שום שכל נברא להשיג בוראו 23 כך אינו יכול להשיג“ חכמתו; און ווי עס שטייט 23* „נעלמה מעיני כל חי“.\nד. אָט די ידיעה איז נוגע יעדן אידן אין זיין עבודה פון תורה ומצות: דער קיום פון אַלע מצות, אויך פון די וואָס האָבן אַ טעם, דאַרף זיין בדרך קבלת עול, ווייל אַזוי איז געווען דער ציווי פון אויבערשטן 24 — „גזירה גזרתי חוקה חקקתי“ 25 — און ווי ס‘איז דער נוסח פון אַלע ברכות המצות: „וצוונו“.\nאון אַזוי איז אויך ביי לימוד התורה, און נאָך מער: וויבאַלד אַז תורה איז אין סוף, איז ווי גרויס זיין הבנת התורה זאָל ניט זיין, פעלט אים נאָך אַלץ אין השגת התורה — ובמילא דאַרף ער נאָכמער האָרעווען, אַז דאָס וואָס ס‘איז ביי אים געווען ביז איצט למעלה מהשגה זאָל ער דאָס קענען באַנעמען מיט זיין פאַר־שטאַנד, און דער ענין החוקה שבתורה זאָל ביי אים זיין אין העכערע ענינים 26 — ביז ער זאָל צוקומען צו אמיתית החוקה פון תורה אַז זי איז למעלה מגדר השגה.\nאון דעריבער זאָגט דער פסוק „זאת חוקת התורה“: הגם אַז אין תורה זיינען דאָ ענינים און סוגים וואָס זיינען אַראָפ־געקומען אין טעם ודעת, כנ“ל, זיינען זיי אָבער אין זייער מהות אַלע העכער פון השגה: תורה (מיט אַלע אירע מצות) איז — „חוקה“.\nנאָכמער: זיי זיינען אַלע אַ חוקה באופן פון מצות פרה אדומה, „זאת חוקת התורה“, וואָס איז לגמרי העכער פון גדר חכמה והשגה.\nה. לפ“ז איז מובן, וואָס עכ“פ איין ענין אין תורה האָט געדאַרפט בלייבן אַ „חוקה“ (און דערמיט אָנווייזן אַז אויך אַלע אַנדערע ענינים זיינען אַזוי באמיתתם), למעלה מגדר השגה; און דערפאַר האָט עס דער אויבערשטער ניט מגלה געווען צו אידן 27:\nווען אַלע ענינים פון תורה וואָלטן נמשך און נתלבש געוואָרן אין השגה פון די נבראים, איז (נוסף אויף דעם וואָס דעמאָלט וואָלט געפעלט אינעם הרגש צו מקיים זיין מצות נאָר מצד דעם רצון העליון, איז) אויב דעמאָלט וואָלט געקומען צו אַ ענין אין תומ“צ וואָס פאָ־דערט מס“נ, וואָלט עס אַ איד ניט געקענט פועל זיין ביי זיך, וויבאַלד אַז אַלע עניני התורה זיינען עפ“י שכל, און אַזוי איז זיין הנהגה (ע“פ תורה) אַלע־מאָל, און דאָס וואָלט אָנגערירט כו“כ פרטים אין קיום התומ“צ, און ניט בלויז ווען ס‘האַנדלט זיך וועגן מס“נ בפו“מ,",[["20","20","כי הרצון, גם כשיש עליו טעם, נשאר במהותו ובפשיטותו (ראה ד“ה ואני תפלתי תרצ“ד. ועייג“כ אגה“ק סי“ט (קכח, א))."],["21","21","ראה לקו“ש חי“ז ע‘ 319 ואילך."],["22","22","ראה שער היחוד והאמונה פ“ד. שם פ“ח."],["23","23","ראה רמב“ם הל‘ יסוה“ת פ“א ה“י. פ“ב ה“ח. ובכ“מ. 23*) איוב כח, כא. וראה תניא קו“א סד“ה דוד זמירות."],["24","24","אולי יש ליישב עפ“ז הסתירה במו“נ ח“ג פי“ג לפכ“ה שם."],["25","25","לשון שהובא בכ“מ והוא במדרש תהלים (באבער) ט, ב."],["26","26","ראה לקו“ש ח“ג ע‘ 1014 ואילך."],["27","27","ראה גם ערבי נחל פרשתנו (לבעהמ“ס לבושי שרד שהובא במאמרי הצ“צ)."]]],[1300181241,"ווייל ווען אַ בר שכל דאַרף טאָן אַ זאַך ניט עפ“י שכל, איז עס ביי אים אַן ענין פון מס“נ,\nביז אַז ער קען צוקומען צו זיין (כל‘ הרמב“ן<sup data-n=\"28\">28</sup> אַ „נבל ברשות התורה“ ר“ל, וואָרום דערהערנדיק נאָר דעם טעם שכלי אין עניני התורה, אָן דעם למעלה מהשכל, וואָלט ער געקענט געפינען „תורה‘דיקע“ הסברות און טעמים אויף זיינע ניט־גוטע הנהגות.\nאון אַזוי איז בנוגע ללימוד והשגת התורה: בכדי צוקומען צו דעם „ומצאת“ אין תורה, „מציאה“ וואָס איז דאָך ניט אויסגערעכנט ע“פ שכל, העכער פון זיין השגה, דאַרף זיין „יגעת“ 29 — עמלים בתורה; כל זמן ער באַנוגנט זיך מיט זיין געוויינליכער העמקה און הבנה אין תורה, איז דאָס ניט קיין אמת‘ע „יגיעה“.\nדוקא בשעת ער האָרעוועט אין לימוד התורה מער ווי זיין רגילות, ביז אויך — היפך טבע שכלו, דעמאָלט קומט ער צו „ומצאת“, וואָס קומט „בהיסח הדעת“ 30, למעלה פון זיין שכל 31 (ע“ד די מעלה פון תלמוד בבלי אויף תלמוד ירושלמי, כמבואר בכ“מ<sup data-n=\"32\">32</sup>.\nדאָס אַלעס איז שייך נאָר ווען אין תורה איז דאָ בגלוי אַן ענין וואָס איז העכער לגמרי פון גדר השכל, וואָס דערפון ווייס אַ איד אַז בפנימיות איז אַזוי אין אַלע עניני התורה, און וויפל ער זאָל פאַרשטיין, איז פאַראַן אַלץ העכער און העכער אין גדר השגה — און דאָס רופט ביי אים אַרויס די תנועה פון „יגעת“, דעם אַוועקלייג און ביטול פון זיין שכל. ביז ער וועט צוקומען צו דער מדרי‘ פון תורה ווי זי איז בעצם למעלה מגדר השגה — „תכלית הידיעה שלא נדעך“ 33.\nו. לפי“ז שטעלט זיך די שאלה לאידך גיסא: וויבאַלד אַז צו משה רבינו האָט דער אויבערשטער מגלה געווען אויך דעם טעם החוקה פון פרה אדומה, איז, לפי הנ“ל, דאַרף דאָך אויסקומען אַז ביי משה רבינו האָט ח“ו געפעלט דער ענין המס“נ ביי קיום המצות און די שלימות היגיעה אין לימוד התורה ? —\nובכלל, ווי איז שייך צו זאָגן אַז דורך דעם וואָס דער אויבערשטער האָט עס מגלה געווען צו משה רבינו זאָל זיך ביי משה‘ן פעלן (אַזאַ ענין עיקרי) אין עבודת התומ“צ 34.\nוועט מען דאָס פאַרשטיין 35 בהקדים וואָס עס שטייט אין מדרש 36, אַז ווען משה רבינו האָט געהערט וועגן טומאת מת, האָט ער געפרעגט ביי דעם אוי־בערשטן „אם נטמא זה במה תהא טהרתו, לא השיבו, באותה שעה נתכר־כמו פניו של משה“; און אפילו ווען דער אויבערשטער האָט עם נאָכדעם גע־זאָגט אַז טהרתו איז ע“י „ולקחו לטמא מעפר שריפת החטאת“, האָט ער גע־פרעגט ביי דעם אויבערשטן „וכי טהרה היא“ 37.",[["28","28","ר“פ קדושים."],["29","29","מגילה ו, ב."],["30","30","סנהדרין צז, סע“א."],["31","31","ראה אגה“ק ס“ד."],["32","32","שערי אורה ד“ה בכ“ה בכסלו פנ“ד ואילך. המשך תרס“ו ד“ה ויתן לך. ד“ה אמר רבא תש“ח פי“א."],["33","33","ראה בחינות עולם ח“ז פ“ב. עיקרים מ“ב ספ“ל. של“ה קצא, ב."],["34","34","ועד“ז אי“מ בנוגע לכאו“א: שממדרש (במדב“ר יט, ו) „דברים המכוסין מכם בעולם הזה עתידים להיות צופים לעולם הבא כהדין סמיא דצפי“ משמע שלעת“ל יתגלה לכאו“א, ואיך יתכן שיחסר (ועי“ז) אז ענין עיקרי בישראל?"],["35","35","ראה לקו“ש ח“ג ע‘ 1015 באו“א קצת."],["36","36","במדב“ר שם, ד. תנחומא שם ו (בסופו). קה“ר שם."],["37","37","קה“ר שם."]]],[1300181242,"דאַרף מען פאַרשטיין:\nעס זיינען דאָך פאַראַן טומאות וואָס בכמה פרטים עקריים זיינען זיי האַר־בער פון טומאת מת, ווי טומאת זב און מצורע 38; טמא מת טאָר זיך ניט גע־פינען בלויז אין מחנה שכינה, אָבער אין מחנה לוי‘ מעג ער יע זיין 39, דאַקעגן אַ זב דאַרף מען אַרויסשיקן אויך פון מחנה לוי‘, און נאָך האַרבער איז אַ מצורע וואָס ווערט אַרויסגעשיקט מחוץ לשלש מחנות אויך פון מחנה ישראל; ביי זב און מצורע איז „טומאה יוצאה עליהן מגופן“ 40, משא“כ אַ טמא מת וואָס די טומאה קומט פון אָנרירן אַ מת ועוד — טאָ פאַרוואָס האָט משה רבינו דוקא ביי טומאת מת זיך געוואונדערט (ביז „נתכרכמו פניו“) ווי אַזוי ער קען טהור ווערן, און ניט ביי אַנדערע האַרבערע טומאות, ובפרט אַז זיי זיינען דאָך געווען פריער?\nז. דער ביאור בזה 41:\nאַלע אַנדערע טומאות ביי אידן זיי־נען פאַרבונדן מיט אַ לעבעדיקן גוף פון אַ אידן, אַ גוף וואָס האָט אין זיך אַ נשמה, און דערפאַר איז אפילו ווען דער גוף איז טמא געוואָרן, וויבאַלד אָבער עס געפינט זיך אין אים אַ נשמה וואָס איז „חלק אלוקה ממעל ממש“ 42 — און דער אויבערשטער איז אַ כל יכול — קען מען פאַרשטיין אַז דער כח אלקי פון דער נשמה האָט מלכתחילה דעם כח צו פועל זיין אויף דער טומאה, אַז דער גוף זאָל סוכ“ס (דורך טבילה וכו‘) טהור ווערן מטומאתו.\nמשא“כ ביי טומאת מת, וואָס די טומאה קומט מצד דעם גוף ווייל ער איז ניט חי 43, ער איז אָפּגעטיילט פון דער נשמה, און דער גוף אַליין איז דאָך ניט מער ווי עפר מן האדמה — דאָ איז גע־ווען די שאלה ביי משה‘ן: ווי קען קומען די טהרה פון אַזאַ טומאה, ובפרט אַז זי נעמט זיך פון דעם וואָס עס איז בטל געוואָרן דער קשר הגוף מיט‘ן כח פון אלקות — דער כח הנשמה?\nובפנימיות הענינים:\nדער ענין פון טומאה איז ניט קיין טיט וכיו“ב גשמי וואָס ער דאַרף עס אָפּ־וואַשן 44, דאָס איז אַ רוחניות‘דיקער לכלוך ופגם אין דער דביקות פון אידן צו אלקות (דורך תומ“צ), וואָס מצד אָט דער דביקות צום אויבערשטן ווערן אידן אָנגערופן חיים 45, ווי עס שטייט 46 „ואתם הדבקים בה‘ אלקיכם חיים גו‘“.\nאָבער ווען אַ איד פאַלט דורך ר“ל אין אַ חטא ועון 47, ווערט דורכדעם אָפּגע־שוואַכט די דביקות און „חיים“ פון אידן און ער ווערט טמא. און אין דעם זיינען דאָ כו“כ בחי‘ אינעם גודל הטומאה,",[["38","38","פסחים סז, א ואילך. רמב“ם הל‘ ביאת מקדש פ“ג ה“ב ואילך."],["39","39","וגם המת עצמו (פסחים שם. רמב“ם שם ה“ד)."],["40","40","בגמרא (שם) אי‘ זה ב„חומרי דזב מטמא מת“, ובחומרי‘ דמצורע מוב‘ „שכן טעון פריעה ופרימה ואסור בתשמיש“ (שם, ב), וברמב“ם חומרי‘ דזבין „מפני שהן מטמאין המשכב והמושב אפי‘ מתחת האבן“ (שם ה“ג. וראה תוד“ה מאי חומרא — שם סז, סע“א) וחומרי‘ דמצורע „מפני שהוא מטמא בביאה“ (שם ה“ב). אבל בפרש“י שם (סו, סע“ב) הוא כבפנים."],["41","41","ראה גם לקו“ש ח“ח ע‘ 326."],["42","42","תניא רפ“ב."],["43","43","וצע“ק מספרי זוטא הובא ביל“ש חוקת עה“פ הנוגע במת: נוגע במת טמא ואין מת עצמו טמא. וכבר דשו בו רבים. וראה בארוכה בשיחה שלאח“ז (ע‘ 239 ואילך)."],["44","44","ראה רמב“ם סוף הל‘ מקואות."],["45","45","אדר“נ ספל“ד."],["46","46","ואתחנן (ד, ד) הובא באדר“נ שם."],["47","47","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310025\" data-slug=\"tanya\" data-id=\"3401310025\">תניא ספכ</a>“ד. אגה“ת פ“ד-ו."]]],[1300181243,"וואָס זיינען לפי“ע דער חלישות אין זיין דביקות, אָבער אויך אין פאַל פון אַ האַרבערע טומאה וחלישות, אויב ס‘איז נאָר אין אַן אופן וואָס ער בלייבט נאָך פאַרבונדן מיט‘ן אויבערשטן און תומ“צ, איז מובן אַז ער האָט דעם כח צו ווערן טהור, צו פאַרשטאַרקן זיין דביקות מיט תומ“צ, ביז אין אַ שלימות.\nמשא“כ ווען אַ איד איז עובר ר“ל אויפן רצון העליון אין אַן אופן אַז ער ווערט אינגאַנצן אָפּגעריסן ח“ו פון דביקות באלקות, פון חיים ברוחניות — וואָס די מיתה רוחנית איז די סיבה צו מיתה גשמית ר“ל 48, און פון דעם ווערט דער ענין פון טומאת מת —\nאון דערפאַר איז „נתכרכמו פניו של משה“: ווי קען זיין די טהרה פון אַ טמא מת, פון אַ טומאה וואָס קומט דורך און פון אַ גוף מת (וואָרום די נשמה עצמה איז דאָך אפילו בשעת החטא היתה באמנה אתו<sup data-n=\"49\">49</sup> וועלכער איז געוואָרן אינגאַנצן אָפּגעריסן פון אלקות און תורה ומצות ?\nח. אויף דעם האָט דער אוי־בערשטער געענטפערט „זאת חוקת התורה“. אַז דאָס איז דער כח פון תורה:\nאפילו דעמאָלט ווען דער גוף איז אָפּ־געריסן פון דער נשמה און תומ“צ 50, וויבאַלד אָבער די נשמה האָט זייענדיק אין (און דורך) דעם גוף געלערנט תורה און מקיים געווען מצות 51, האָט די נשמה ביכולת (זייענדיק אַ נצחית 52: חלק אלוקה ממעל ממש) מיט‘ן כח התורה (וואָס איז אַ נצחית) צו פועל זיין אין דעם גוף* 52* אַ רושם נצחי 53 פון קדושת הנשמה והתורה, אויך אויף שפעטער ווען דער גוף איז אָפּגעזונ־דערט פון דער נשמה — ומהאי טעמא קען אויך די טומאה וואָס קומט פון אַ גוף מת, טהור ווערן 54.\n[וי“ל אַז דאָס איז איינער פון די טעמים (בפנימיות) דמחז“ל „צדיקים אינן מטמאין“ 55, וואָרום די מציאות",[["48","48","ראה אגה“ת שם. קונט‘ ומעין מאמר ז."],["49","49","תניא שם."],["50","50","ראה לקו“ש שם, שמטעם זה לא אמר הקב“ה למשה הטהרה מטומאת מת ביחד עם טומאתו כבשאר הטומאות, כי מכיון שיש כאן הפסק ודילוג בין הטומאה והטהרה, בא גם הפסק באמירת דיניהם."],["51","51","להעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310035\" data-slug=\"tanya\" data-id=\"3401310035\">תניא פל</a>“ד: שזכה להיות אושפיזין לגבורה."],["52","52","ראה סנהדרין ר“פ חלק, ובארוכה בהמובא בתשובות וביאורים (קה“ת, תשל“ד*) סי‘ ח‘. 52*) ועפ“ז י“ל דזה ש„לא ידח ממנו נדח“ (הל‘ ת“ת פ“ד ס“ג. <a class=\"ft-cite\" href=\"#/read/tanya/3401310035\" data-slug=\"tanya\" data-id=\"3401310035\">תניא ספל</a>“ט) — הוא (גם) מצד הגוף. וראה לקמן הערה 58."],["53","53","וראה תשובות וביאורים שם הערה 5, שמפשטות הסוגיא בירושלמי (כלאים פ“ט ה“ג) משמע, דאפילו ירבעם וחבריו גם גופם קם בתחה“מ."],["54","54","ובנוגע לטומאת מת עכו“ם י“ל, שמלכתחילה לא הי‘ קשה למשה, כיון שהטומאה בישראל באה דוקא מצד קדושתם (תורה, נשמתם) שנסתלקה כמו שהאריך באוה“ח ריש פרשתנו. שו“ע אדה“ז מהדו“ב סי‘ ד ס“ב. ומזה מובן במכ“ש בטומאה הבאה משרץ או נבילה שלא שאל משה איך אפ“ל טהרתו."],["55","55","ברמב“ן כאן „וטעם טומאת המת בעטיו של נחש כי הנפטרים בנשיקה לא יטמאו מן הדין והוא שאמרו צדיקים אינן מטמאין“ — ראה מדרש משלי פ“ט, ב. תוד“ה מה ב“מ קיד, ב. זח“א קכה, א. קסח, א (ובנצוצי זהר שם). חינוך שבהערה 59. וראה פנ“י ובכלי חמדה כאן. שדי חמד (כמסומן במפתח). שו“ת מנח“א ח“ג סי‘ סד. אלף המגן למטה אפרים סימן תקפ“א סקי“א (וש“נ). — וראה שו“ת שארית יהודא — לאחי אדה“ז — (הוספות סי“ד סל“ה) שפוסק לאיסור אפילו הוא צד“ג, ומורה ע“ד בנין ציון אדה“ז באופן שיוכלו הכהנים לעמוד בהרחקה וכו‘. — ואולי יש לקשר זה ולהסביר ע“פ סברת הספרי זוטא הנ“ל (הערה 43). ואכ“מ. *) אגרות קודש כ“ק אדמו“ר שליט“א ח“א ע‘ קמא ואילך. המו“ל."]]],[1300181244,"הגוף פון אַ צדיק איז די נשמה אלקית, ווייל „חיי הצדיק אינם חיים בשרים כ“א חיים רוחניים שהם אמונה ויראה ואהבה“ 56, און פון דעם באַשטייט דער חיות ומציאות הגוף 57, ובמילא איז מובן, אַז אפילו בשעת די נשמה גייט אַוועק פון גוף בלייבט אַ פעולה נצחית 58 אין גוף 59].\nדאָס איז אָבער אַן ענין פון „חוקה“ — העכער פון שכל וטעם 60, וואָרום לויטן שכל (און גדר) הנבראים, קען איין זאַך פועל זיין אויף דער צווייטער, נאָר דאַן ווען זיי האָבן אַ שייכות און אַ קשר צווישן זיך (אָבער ניט ווען עס ווערט נפסק די שייכות און זיי ווערן הפכיים 60*). און דאָס איז נאָר מצד כח הבורא 61 וואָס איז העכער פון אַלע הגדרות און הגבלות 62.\nט. עפי“ז איז מובן וואָס צו משה רבינו האָט דער אויבערשטער מגלה געווען דעם טעם פרה (און ניט נאָר האָט דורכדעם ביי אים ניט געפעלט ח“ו אין שלימות ביטול ומס“נ בתומ“צ, נאָר אדרבה): מדרי‘ משה איז בחי‘ „החכמה“ 63, וואָס מצד דעם ביטול פון חכמה איז אין איר שורה א“ס ב“ה, ווי דער אַלטער רבי זאָגט 64 אַז „א“ס ב“ה הוא אחד האמת שהוא לבדו הוא ואין זולתו וזו היא מדרי‘ החכמה“;\nנאָכמער, בל‘ הקבלה 65, „פנימיות אבא 66 הוא פנימיות עתיק ממש“, וואָס איינער פון די פירושים בזה איז 67: המשכות פון אַ העכערע מדרי‘ צו אַ נידעריקערע זיינען, בדרך כלל, אין אַן אופן פון משפיע ומקבל, און היות אַז עס קומט אין אַן אופן פון ירידה והמשכה איז פאַרשטאַנדיק אַז דאָס איז אַ הארה בלבד (ועד“מ השפעת השכל פון אַ רב צו אַ תלמיד) 68; משא“כ דער אופן ווי „פנימיות אבא“ האָט אין זיך „פנימיות עתיק“ — וואָס דאָס מיינט עצמות א“ס — איז ניט אין אַן אופן פון המשכה בדרך משפיע ומקבל, נאָר פנימיות אבא איז פנימיות עתיק, עצמות דערפון.",[["56","56","ביאור לאגה“ק סי‘ ז“ך."],["57","57","להעיר מחילוק אופן בירור וזיכוך הגוף דמשה ואלי‘ — המשך תרס“ו ע‘ קנח ואילך. שמח תשמח תרנ“ז ע‘ 102 (סה“מ תרנ“ז ע‘ רעח) ואילך. ובכ“מ."],["58","58","וראה גם לקו“ש ח“ז ע‘ 84 ובהנסמן שם, שמצד בחירת הקב“ה בהגוף (<a class=\"ft-cite\" href=\"#/read/tanya/3401310045\" data-slug=\"tanya\" data-id=\"3401310045\">תניא פמ</a>“ט. תורת שלום ע‘ 120) נעשה הגוף מצ“ע ענין נצחי. ודבר משנה הוא (סנה‘ ר“פ חלק): כל ישראל יש להם חלק לעוה“ב (נשמות בגופים). וראה לקמן ע‘ 409 הערה 71."],["59","59","ראה בהנ“ל בחינוך (מצוה רס“ג): לפי שגופם טהור ונקי כו‘. ולהעיר מרבינו בחיי (ויחי מט, לג) בזה שיעקב אבינו לא מת כי נפשו של יעקב הי‘ מרחפת על גופו תמיד כו‘, עיי“ש. וראה לקו“ש ח“ד ע‘ 1260 ואילך. חט“ו ע‘ 427 ואילך (ס“ו, ח)."],["60","60","ועפ“ז מובן שאין לזה סתירה ממ“ש החינוך (מצוה שצז) שאין החוקה „מהיותה מטהרת בהגיע אפרה על גוף המטהר כו‘“. 60*) משא“כ בהענינים דפעולה נמשכת."],["61","61","ועד“ז הוא בחוקה של פרה שהיא נעשית בחוץ, שמכפר על גקה“ט (אגה“ק סכ“ח) דגם ניצוצות שנפלו בגקה“ט, שנכרתו לגמרי מקדושה ונעשים כמו רע, מהפכים לטוב, הטמא נהפך לטהור, מי יתן טהור מטמא לא אחד — יחידו של עולם — ראה בכ“ז לקו“ת פרשתנו נט, ד ואילך."],["62","62","ועפ“ז יומתק הדיוק בזה שלעת“ל כאשר „ואת רוח הטומאה אעביר מן הארץ“ תשאר גם בחי‘ ארץ הלזו שהיתה בה טומאה (ויתרה מזו: מלאה הארץ דעה את ה‘) — דמכיון שכל העולם נברא בשביל ישראל ובשביל התורה, הרי עי“ז נמשך בה מהנצחיות דישראל ותורה, וראה לקו“ש ח“ו ע‘ 91, שהכוונה בשביל ישראל ובשביל התורה היא ענינה של הבריאה גופא."],["63","63","ראה לקו“ת מסעי פט, ד. צב, רע“א. ובכ“מ. וראה בארוכה לקו“ש ח“ז (ע‘ 244 ואילך) מכמה מקומות דמשה הוא בחי‘ יסו“א."],["64","64","<a class=\"ft-cite\" href=\"#/read/tanya/3401310035\" data-slug=\"tanya\" data-id=\"3401310035\">תניא פל</a>“ה בהגהה."],["65","65","ראה בהמובא בלקו“ת נצבים מט, ד. וראה סה“מ הש“ת ע‘ 49 בהערה."],["66","66","בתו“א בשלח סו, ב לגבי משה."],["67","67","ראה המשך תרס“ו ע‘ צה ואילך."],["68","68","ראה גם ד“ה תקעו תרצ“ד פ“ב (נדפס בסה“מ ה‘תש“א)."]]],[1300181245,"ובמילא איז פאַרשטאַנדיק וואָס דער אויבערשטער האָט געזאָגט צו משה רבינו „לך אני מגלה טעם פרה“ אַז ס‘איז צו אים נתגלה געוואָרן פנימיות אבא פנימיות רצון העליון — ענין החוקה 69 — ווייל דאָס איז געווען מדרי‘ משה, און דער אויבערשטער האָט אים מגלה געווען אמיתית מדריגתו 70.\nיו“ד. דאָס איז אויך אַ ביאור וואָס די „חוקה“ וואָס איז נתגלה געוואָרן צו משה‘ן איז דוקא בשייכות צו טהרה פון טומאת מת:\nבשעת די השפעה איז אין אַן אופן פון משפיע ומקבל, איז וויבאַלד עס קומט בדרך ירידה והמשכה, און ס‘ווערט נמשך בלויז אַ הארה, דעריבער איז די שייכות זייערע נאָר בעת ההשפעה, ניט שפעטער, וואָרום דער מקבל איז גע־בליבן אַ באַזונדער מציאות פון דעם משפיע;\nבשעת אָבער ס‘איז ניט בדרך ירידה והמשכת הארה, נאָר המשכת העצמות ממש, ווי ביי פנימיות אבא, איז ניט שייך צו זאָגן אַז דער אויפטו איז נאָר בעת ההמשכה און עס בלייבט דערנאָך אַ באַזונדער מציאות פון אַ „מקבל“, דאָרט וואו ס‘איז דאָ המשכת העצמות, ווערט עס מהות העצמות, פון אלקות.\nבמילא איז מובן, ווי אַזוי עס קען זיין די טהרה פון טומאת מת, הגם אַז בגלוי איז דער גוף ניט פאַרבונדן מיט‘ן כח פון אלקות פון דער נשמה און תומ“צ — ווייל בפנימיות איז דער גוף אַליין אַ מהות פון קדושת (הנשמה ו)האלקות.\nאָבער בזמן הזה איז דאָס ניט מאיר בגלוי, ווייל איצט איז די המשכת העצמות ניט אין אַן אופן גלוי, ובמילא איז דאָ אַן אָרט פאַרן ענין פון טומאת מת, און די טהרה זיינע איז אין אַן אופן פון „חוקה“.\nלעת“ל אָבער, וואָס דעמאָלט וועט זיין המשכת העצמות בגילוי, דער גילוי פון פנימיות עתיק 71, וועט זיך דאַן אָנזען בגלוי אַז די מציאות פון גוף איז דער ענין הנשמה האלקית שבו, ובמילא וועט ניט זיין דער גאַנצער ענין פון טומאת מת 72, און די חוקת טהרתה וועט דעמאָלט נתגלה ווערן צו יעדן איינעם 73.\nיא. עפי“ז איז פאַרשטאַנדיק אַז דאָס וואָס „לך אני מגלה טעם פרה“, איז ניט געווען קיין סיבה אַז דורכדעם זאָל ביי משה רבינו ח“ו פעלן אין שלימות הביטול והמס“נ:\nדער טעם פרה וואָס איז נתגלה גע־וואָרן צו משה‘ן איז ניט קיין טעם שכלי 12, וואָס איז נתלבש געוואָרן אין שכל, נאָר ס‘איז ביי אים נתגלה געוואָרן בשכלו דער רצון העליון פון עצמות א“ס, ביז אַז דאָס איז געוואָרן זיין (אויך דעם שכל‘ס) מציאות.",[["69","69","ראה המשך תרס“ו שם (ס“ע צו ואילך), דבחי‘ רצה“ע שלמעלה מהטעם הוא בחי‘ פנימיות אבא פנימיות עתיק."],["70","70","ועפ“ז מובן גם מ“ש לך אני מגלה, דפשוטו דמקודם לזה לא ידע (ובפרט ע“פ קה“ר שם), כי מתחילה לא הגיע לבחי‘ פנימיות אבא פנימיות עתיק (ראה ד“ה אלה הדברים תרע“ג (נעתק בלקו“ש שם ע‘ 248) שזהו שביקש הראני נא את כבודך), ורק בעת הסתלקותו זכה לשעה“נ (לקו“ת להאריז“ל וס‘ הליקוטים ואתחנן ג, כו). ראה סה“מ ה‘ש“ת שם. ובכ“מ."],["71","71","פע“ח שער הק“ש רפט“ו. לקו“ת שה“ש בסופו (נא, ג), וראה המשך תרס“ו שם."],["72","72","וכמ“ש (ישעי‘ כה, ח) בלע המות לנצח. ונא‘ ואת רוח הטומאה אעביר מן הארץ."],["73","73","ראה לעיל הערה 34."]]],[1300181246,"איז דאָך אדרבה: ביי וועמען איז שייך צו זאָגן אַז אים זאָל פעלן אינעם ענין המס“נ — ביי איינעם וואָס זיין מציאות איז אַ באַזונדער זאַך, און ער דאַרף זיך מוסר נפש זיין פאַר אלקות (און האָרע־ווען היפך שכלו אויף צו פאַרשטיין תורה<sup data-n=\"74\">74</sup>, משא“כ משה רבינו וואָס אלקות איז מציאותו 75, איז דאָך מהותו מס“נ 76.\nיב. וי“ל אַז דאָס איז אויך די שייכות 77 פון פ‘ חוקת צו י“ב י“ג תמוז, דער חג הגאולה פון כ“ק מו“ח אדמו“ר:\nדער בעל השמחה והגאולה איז גע־ווען דורכגענומען מיט דער עבודה פון מס“נ בפועל 78, ובפרט אין דער אַרבעט פון הרבצת התורה אין יענער מדינה (וואו ס‘איז געווען דער מאסר), וואו עס האָט זיך געפאָדערט מס“נ בפועל ביי יעדן ענין — פון ענינים כלליים ביז צו דעם קלענסטן פרט — פון תורה ומצות.\nאון דעריבער איז די גאולה פון דעם מאסר געווען אין אַן אופן, אַז צוזאַמען דערמיט וואָס ס‘איז געווען אַ נס גלוי שלמעלה מהטבע, איז דאָס געווען מלובש אין טבע.\nדער ביאור אין דעם: אין דעם אוי־בערשטנס הנהגה פון וועלט זיינען דאָ כמה אופנים 79:\nהנהגה טבעית, וואָס נעמט זיך פון שם אלקים 80 (בגימט‘ הטבע), די מדרי‘ אין אלקות וואָס איז מלובש אין עולם און מצד איר האָט וועלט אַ תפיסת מקום — בחי‘ ממכ“ע;\nהנהגה נסית, עס ווערט נתבטל הנהגת הטבע, וואָס דאָס קומט פון שם הוי‘ וואָס איז למעלה מהטבע, די מדרי‘ אין אלקות וואָס איז העכער פאַר וועלט — בחי‘ סוכ“ע, און דעריבער ווערט דאָס נתגלה אין אַן אופן פון ביטול הטבע;\nניסים וואָס זיינען מלובש אין טבע, וואָס קומט פון נאָך אַ העכערע מדרי‘ אין אלקות, וואָס איז העכער סיי פון שם אלקים סיי פון שם הוי‘ 81, און דעריבער ווערן פון דאָרטן נמשך ניסים וואָס בעצם זיינען זיי העכער פון טבע אָבער זיי זיינען אָנגעטאָן אין לבושי הטבע, ד.ה. אַז דער נס פועל‘ט אויך אויף מציאות הטבע, אַז טבע גופא איז מסכים אויפן נס.\nע“ד הנס דפורים וואָס ס‘זיינען געווען ניסים מלובשים בדרכי הטבע, ביז אַז הפה שאסר הוא הי‘ הפה שהתיר 82.\nוואָס עד“ז איז דאָך געווען די גאולה פון בעל השמחה והגאולה אַז די זעלבע",[["74","74","ראה המשך תרס“ו שם דע“י דדייק במילין דחוכמתא בבחי‘ יגיעה כו‘ מגיעים לבחי‘ העלם העצמי דחכמה דפנימיות אבא."],["75","75","וראה שרש מצות התפלה ספט“ו."],["76","76","ועד“ז ביגיעת התורה דטעמי תורה שיתגלה לעת“ל שלא יהיו בבחי‘ ענין שכלי כ“א מה שיתגלה בכל ענין בחי‘ התענוג העצמי הפשוט (המשך תרס“ו שם)."],["77","77","ראה של“ה חלק תושב“כ ר“פ וישב."],["78","78","ראה לקמן ע‘ 302 ואילך ע“ד הג‘ תקופות דימי נשיאותו (תר“פ-תש“י)."],["79","79","ראה אוה“ת אחרי ע‘ תקסד. ועוד. ובאוה“ת בראשית יח, ב ואילך. ד“ה החודש הזה תרס“ו בתחילתו וסופו (ב‘ אופנים דלקמן — טבע ונס)."],["80","80","ראה טושו“ע חאו“ח ס“ה בפ“י שם אלקים."],["81","81","תו“א צט, ד ואילך (ועוד) לענין הנס דפורים, אוה“ת שם (מג“א ב‘שלו) ובכ“מ. ובאוה“ת אחרי שם, דנסים המלובשים בטבע הם מבחי‘ שם שד“י."],["82","82","תו“א צד, ב. ושם, שזהו כענין אתהפכא חשוכא לנהורא שיהי‘ לעת“ל (שלמעלה מאתכפיא). וראה לקו“ש ח“ד (ע‘ 1065 ואילך) שהנסים לצדיקים שבדור האחרון לפני ביאת משיח הוא הקדמה והכנה להנסים דהגאולה. ולכן הגאולה די“ב-י“ג תמוז הי‘ ע“ד „אומר לצפון תני“, כבהגאולה העתידה."]]],[1300181247,"מענטשן 83 וואָס האָבן געהייסן אים אַרעסטירן, זיי אַליין האָבן געמוזט הייסן אים באַפרייען 84.\nוי“ל אַז דאָס איז ע“ד הענין פון „פנימיות אבא פנימיות עתיק“: בשעת אַז דאָס איז נמשך געוואָרן אין וועלט מצד דעם מס“נ בפועל 85 פון בעל השמחה והגאולה (וואָס דאָס איז געווען מציאותו), האָט דאָס ניט מבטל געווען טבע העולם, נאָר דאָס גופא איז געוואָרן די מציאות פון טבע, אַז זי האָט מסייע געווען צו קדושה.\n(משיחות ש“פ פרה, תשכ“ח. ש“פ חו“ב, י“ב תמוז, תשכ“ט)",[["83","83","ראה לקו“ש שם. ועד“ז בלקו“ש ח“ח ע‘ 120 ואילך."],["84","84","והיינו אף שהי‘ מלובש בטבע הי‘ נראה בחוש שכל הסיבות היו למעלה מהטבע וע“ד אופן הנס דפורים (תו“א צג, ג. ק, א. ועוד)."],["85","85","ראה תו“א (צט, ד ואילך) דבפורים ע“י המסנ“פ הגיעו לעצמות אוא“ס שלמעלה מבחי‘ שם הוי‘, ומזה נמשכו הנסים המלובשים בטבע. ובהמשך שמח תשמח שם (ע‘ 101. סה“מ שם ע‘ רעז). ועוד, שע“י מסנ“פ בפועל מגיעים לעצמות א“ס דפנימיות אבא כו‘."]]],[1300181248,"<h3>חוקת ב*</h3>\nא. וועגן די דינים פון טומאת מת בפרשתנו זאגט דער ילקוט 1 אויפן פסוק 2 „הנוגע במת לכל נפש אדם וטמא שבעת ימים\" — „נוגע במת טמא ואין 3 מת עצמו טמא, נוגע במת טמא ואין 3 בנה של שונמית טמא, אמרו בנה של שונמית כשמת כל שהי' עמו בבית טמא (הי'<sup data-n=\"4\">4</sup> טומאת שבעה וכשחי' הי' טהור לקודש חזרו ונגעו בו וטמאוהו 5 הם, הרי זה אומר מטמאיך לא טמאוני ואתה טימאתני\" 6.\nדאס וואס דער ילקוט פארבינדט דא בכללות דעם ענין פון „ואין בנה של שונמית טמא\" מיטן פריערדיקן פרט „ואין מת עצמו טמא\", קען מען מפרש זיין בפשטות: היות דער מת עצמו איז ניט טמא, דערפאר איז אויך דער בן השונמית ניט געווען טמא נאכדעם ווי ער איז צוריק לעבעדיק געווארן (כאטש ער איז פריער געווען א מת און האט מטמא געווען).\nעס פאדערט אבער ביאור דער המשך „נוגע במת טמא ואין בנה של שונמית טמא\": פון דעם דיוק הכתוב „הנוגע במת גו' יטמא\" לערנט מען אפ (ווי די ערשטע ילפותא אין ילקוט) אז נאר הנוגע איז טמא אבער „אין מת עצמו טמא\", דאקעגן ביי דער הוספה-חידוש „בן השונמית\" ויבאלד דא רעדט מען דאך לכאורה נאכדעם ווי ער איז געווארן א חי, האט דער לימוד בזה געדארפט זיין: „נוגע במת טמא ואין בנה של שונמית מטמא\", אז דער נוגע אין „בנה של שונמית\" איז ניט טמא, ויבאלד ער איז ניט קיין מת נאר א חי 7.\nאויף דעם וואס עס שטייט אין ילקוט „ואין מת עצמו טמא\" זאגט דער מג\"א 8: „ונ\"מ כשיחיו המתים אין צריכין הזאה\" 9. לפי\"ז (אז אויך אינעם ערשטן פאל פון „ואין מת עצמו טמא\" איז דער לימוד נוגע (בעיקר) ווען „יחיו המתים\"<sup data-n=\"10\">10</sup> קען מען לערנען אז אין ביידע פאלן, „אין מת עצמו טמא\" ו„אין בנה של שונמית טמא\", רעדט זיך דער זעלבער ענין: מת עצמו איז ניט טמא, דעריבער דארף ער ניט קיין הזאה נאכ־דעם ווי ער ווערט א חי, און אזוי איז אויך „אין בנה של שונמית טמא .. וכשחי' הי' טהור לקודש\".\nלפי\"ז ווערט אבער שווער: וואס איז דער ילקוט מחדש מיט דעם וואס ער איז מוסיף „אין בנה של שונמית טמא\" נאך דעם לימוד אז „אין מת עצמו טמא\".\nב. וועט מען דאס פארשטיין ע\"פ דעם ביאור בגמרא סוף מס' נדה. די גמרא 11 בריינגט דארט די ברייתא",[["","","*) וסיום מס' נדה."],["1","1","רמז תשסא. והוא מספרי זוטא עה\"פ."],["2","2","יט, יא."],["3","3","בספרי זוטא „אין\" (בלא ואו). ובמדרש הגדול „אין עצמו של מת טמא\"."],["4","4","כ\"ה בספרי זוטא."],["5","5","בספרי\"ז: טמאוהו (בלא ואו)."],["6","6","פי' אותן הנוגעים בבני אדם שנטמאו בו אומרים מטמאך היינו בן שונמית לא טמאוני וכו' — זית רענן לילק\"ש שם."],["7","7","וראה המשך הדרשות בספרי זוטא וילק\"ש שם."],["8","8","זית רענן שם."],["9","9","וממשיך „נדה דף ע' ע\"ש בתוספות (וע\"פ המבואר לקמן בפנים צ\"ע כוונתו) וכו'\"."],["10","10","אבל כ' עוד נפק\"מ „וגם המכניס מת למקדש פטור כו'\" ואכ\"מ."],["11","11","סט, ב."]]],[1300181249,"„שאלו אנשי אלכסנדריא את ר' יהושע בן חנניא\" וז\"ל: „ג' דברי בורות אשתו של לוט מהו שתטמא אמר להם מת מטמא ואין נציב מלח מטמא. בן שונמית מהו שיטמא אמר להן מת מטמא ואין חי מטמא. מתים לעתיד לבוא צריכין הזאה שלישי ושביעי או אין צריכין אמר להן לכשיחיו נחכם להן. איכא דאמרי לכשיבוא משה רבינו עמהם\".\nובהקדים: מ'האט שוין פיל מאל גערעדט, אז אלע קושיות ושאלות וואס זיינען דא אין גמרא, אויך די וויכוחים ושקו\"ט וואס די חכמי ישראל האבן געהאט מיט אנדערע — מיט צדוקים בייתוסים וכו' אדער (בנדו\"ד) מיט אנשי אלכסנדריא — האבן זייערע סברות א מקום בשכל, אויך אין שכל דתורה: און אפילו די טענות ומענות וואס די גמרא זאגט אז זיי זיינען דברי הבל ושטות 12 וכיו\"ב, איז ניט דער פשט אז זיי האבן ניט קיין אחיזה אין שכל הפשוט (און אוודאי ניט אין שכל שבתורה) — וואורום די חכמי ישראל האבן ניט געהאט צו טאן מיט טפשים ובורים און עאכו\"כ אז מען וואלט זייערע רייד ניט אריינגעשטעלט אין גמרא. ובמכש\"כ וק\"ו אז אפילו אן אמת'ע זאך, אויב זי איז זעלבסטפארשטענדליך — פרעגט מען: מאי קמ\"ל, פשיטא היא וכיו\"ב.\nפון דעם גופא וואס חכמי ישראל ווי ריב\"ז, ריב\"ח וכו', האבן מיט זיי געפירט ויכוחים און שקו\"ט און מען האט דאס אריינגעשטעלט אין גמרא אלס א חלק פון תושבע\"פ, איז מוכח אז ניט בלויז האט דאס א מקום בשכל, נאר דאס האט אויך אן ארט אין שכל התורה 13, און מען קען אויך פון דעם ארויסנעמען סברות און תוספת הבנה אין דער סוגיא אין וועלכע ס'איז פארגעקומען די שקו\"ט 14.\nדערמיט ווערט פארשטאנדיק, וואס אויך אין פאל ווען מען לערנט דעם חלק פון תושבע\"פ וואס אנטהאלט די שאלות און טענות פון די צדוקים וכיו\"ב, איז מען אויך אויף דעם מחויב בברכת התורה 15.\nאון כאטש די ברייתא רופט דאס אן „דברי בורות\" (וכיו\"ב) 16, איז דאס מצד א פרט בהם אדער די ניטצוגעפאסט־קייט לנדו\"ד וכו'; און אויך — זיי זיינען „דברי בורות\" לגבי תורה שלימה שלנו, לגבי תשובות ר\"י בן חנניא. און ווי דאס איז מוכח בענינינו גופא: א) די דריטע שאלה פון אנשי אלכסנדריא איז דאך אויך נאך דער תשובת ריב\"ח — בתקפה: ב) מען געפינט א שקו\"ט וחילוקי דעות בראשונים ואחרונים אין די שאלות פון די אנשי אלכסנדריא, ניט נאר אין תשובת ריב\"ח 17, ג) ס'איז נויטיק א לימוד מיוחד פון פסוק צו שולל זיין דעם ענין הטומאה ביי בן שונמית און מתים לעת\"ל כו' — און נאך אנדערע הוכחות.",[["12","12","פרש\"י שם ד\"ה דברי בורות."],["13","13","ובפרט שהגמ' כוללם ביחד עם „הג' דברי חכמה (הלכה) ג' דברי אגדה כו'\" וראה חדא\"ג שם."],["14","14","ועדמש\"כ הרגצובי (מכתבי תורה מכתב צט. ועוד): כל מה דכתיב בתורה הוא דין לא ח\"ו סיפור."],["15","15","ראה לקוטי\"צ אגרות (ע' רסו) עד היכן הדברים מגיעים."],["16","16","ראה לקוטי\"צ שם „שכל מה שנאמר בתושב\"כ ובתושבע\"פ הן בהלכה והן באגדה כו' וכן ההלכה שעלי' אמרו אח\"כ שבדותא היא .. כולם ממש אמר ה' ובאותו הלשון ממש שנאמרו כו'\"."],["17","17","ראה תוד\"ה מתים נדה שם: „וא\"ת אמאי לא בעי כו' וי\"ל כו'\". תוס' הרא\"ש שם. ובכמה מקומות בספרי אחרונים. חלק מהן צוינו בהערות דלקמן."]]],[1300181250,"ג. מהדיוקים וואס זיינען דא אין דער ברייתא הנ\"ל (בנוגע די „ג' דברי בורות\"):\nא) פארוואס פרעגן די אנשי אלכ־סנדריא (די שאלה ב') „בן שונמית (שהחי' אלישע) מהו שיטמא (לאחר שהחיהו<sup data-n=\"18\">18</sup>\", נאכדעם ווי ר\"י בן חנניא האט זיי שוין פריער געענטפערט אז דוקא „מת מטמא (ואין נציב מלח מטמא)\", וואס דערפון קען מען שוין אליין פארשטיין אויך ביי בן שונמית, וואס איז ניט קיין מת, אז ער איז ניט מטמא.\nב) קושיית המפרשים: פארוואס איז זייער שאלה געווען וועגן „בן שונמית\" און ניט וועגן „בן הצרפית\", וואס איז פון טויט לעבעדיק געווארן דורך אלי' הנביא 19 — פריער ווי בן שונמית דורך אלישע 20.\nג) אין דער תשובה אויף דער דריטער שאלה „לכשיחיו נחכם להן, איכא דאמרי לכשיבא משה רבינו עמהם\": אויב ער האט ניט געוואוסט דעם ענטפער — פארוואס האט ער ניט געענטפערט „איני יודע\" וכיו\"ב (כמדתו של חכם — „על מה שלא שמע אומר לא שמעתי ומודה על האמת וכו'\"<sup data-n=\"21\">21</sup>.\nד) וואס איז דער דיוק הלשון „לכשיבא משה רבינו\" — און ניט ווי דער לשון בכגון דא: כשיבא אלי' וכיו\"ב 22.\nה) „לכשיבא משה רבינו עמהם\" — און פירט ניט אויס, אז ער וועט פאר־ענטפערן (וכיו\"ב), ע\"ד ווי אין ערשטן לשון: „נחכם להן\".\nו) וואס איז דער דיוק הלשון „לכשיבוא משה רבינו עמהם\" 23?\nז) שינוי הסגנון: אין די ערשטע צווי שאלות „מהו שתטמא .. שיטמא\", און אין דער דריטער שאלה „צריכין הזאה .. או אין צריכים\" און ניט „מהו שיצרכו הזאה\" וכיו\"ב ?\nד. דער ביאור בכ\"ז: טומאת מת איז פארבונדן מיט צווי ענינים: א) דער",[["18","18","פרש\"י שם."],["19","19","מ\"א יז, יז ואילך."],["20","20","בשו\"ת הרדב\"ז ח\"ה (ב' אלפים רג) כתב, שמזה ששאלו בבן השונמית דוקא מוכח דס\"ל דבן הצרפית לא מת. וכן הביא הרד\"ק במ\"א שם פסוק יז (בשם „יש מי שאומר\") ובפסוק כ' (ויונתן תרגם כו'). ובמ\"ב (ד, לא) כתב בבן השונמית „והסברא אשר אמרנו בילד שהחי' אלי' הוא הסברא עצמה כו'\" (עיי\"ש שמביא מגמרא דילן „ומצאנו לו סמך בדברי רז\"ל כו'\"). ולכמה מפרשי המורה כן ס\"ל להרמב\"ם במו\"נ ח\"א פמ\"ב (ראה שם טוב. אפודי (ושם כתב *) בפשטות כוונתו „והסברא אשר אמרנו כו'\" שגם בן השונמית לא מת ממש כדברי רז\"ל ששאלו בן השונמית מהו שיטמא והיתה התשובה מת מטמא ואינו מטמא חי\" כוונתו שמכיון שהוי חי (מעולם לא מת) לכן אינו מטמא גם אז (וכ\"פ ברש\"ש נדה שם). אבל מזה שכתב בבן הצרפית במ\"א שם, יז „והנכון כי מת מיתה גמורה\" אולי גם בבן השונמית כוונתו שמת מיתה גמורה. וה„סמך בדברי חז\"ל\" היינו שאם לא מת ממש לא הי' מקום מעיקרא לשאלה מהו שיטמא. שכוונת הרמב\"ם גם לבן השונמית). וראה שו\"ת הריב\"ש סמ\"ה). אבל באברבנאל למורה שם מפרש שלדעת הרמב\"ם שניהם מתו ממש [ולהעיר ממש\"כ שם „ומה שאמרו חז\"ל שהביא בן כספי שאלו לר' יהושע בן הצרפית מהו שיטמא וכן לר\"א בן השונמית וכו' והשיב כל אחד מהם מת מטמא חי אינו מטמא\"]. וכן תפס בפשטות בתרומת הדשן פסקים סק\"ב. ועוד."],["21","21","אבות פ\"ה מ\"ז."],["22","22","ראה אגה\"ק סכ\"ו (קמג, ב) : ומפורסם הפכו בכל הש\"ס ומדרשים כו' ואליהו בא לפשוט כל הספיקות כו'."],["23","23","ראה תוד\"ה אחד (פסחים קיד, ב) דכשיבנה המקדש משה ואהרן יהא עמנו. ולהעיר מיומא (ה, ב): לכשיבואו אהרן ובניו ומשה עמהם."]]],[1300181251,"סילוק החיות, סילוק הנשמה מן הגוף. ב) דער גוף זאל זיין א גוף מת. און אין יעדערן איינעם פון די ענינים זיינען דא כמה פרטים ודינים:\nובכללות: בענין הא' — סילוק החיות מיינט, אז עס ווערט נסתלק כללות החיות 24, און נאר דעמאלט איז דא טומאת מת. משא\"כ „האבר 25 והבשר המדולדלים באדם ואע\"פ שאין יכולין לחזור ולחיות טהורים\" 26.\nגוף מת איז דוקא ווען מיט זיין צורה און געשטאלט איז ער עכ\"פ ענליך צו א גוף חי, „אבל אם נשרף עד שנתבלבלה צורת תבניתו טהור\" 27 — און עס זיינען דא כמה פרטים ודינים בהנ\"ל.\nאון אין דעם איז באשטאנען דער חילוק פון די ג' שאלות:\nה. בפשטות וואלט מען געקענט זאגן, אז די ערשטע שאלה „אשתו של לוט מהו שתטמא\" באשטייט אין דעם 28: אשתו של לוט איז געווארן א „נציב מלח\" ניט עפ\"י דרך הטבע, נאר דורך א־נס 29 — און אין ניסים זיינען פאראן צווי סוגים 30:\n(א) אז דער נס איז מחליף דעם טבע (מציאות) פון דער זאך אויף א צווייטע — ווי אינעם פאל פון „ידו (של משה) מצורעת כשלג\" 31, וואס נאכן נס איז די צרעת אויף דער האנט געווען באופן טבעי, און עס האט געמוזט קומען א צווייטער נס צו מבטל זיין די צרעת, אז ס'זאל זיין „שבה כבשרו\" 32.\n(ב) אז דאס וואס איז נתחדש געווארן דורכן נס איז ניט דורך חילוף טבע נאר בהוספה אויפ'ן טבע בכל רגע, ע\"ד ווי ס'איז געווען בא קרי\"ס 33. ועד\"ז אויך ביי מכת „דם\" וואס די וואסערן „נהפכו לדם\", איז אפילו נאכן נס זיינען זיי פארבליבן א מציאות פון מים, און דער נס האט אויפגעטאן בכל רגע — הפיכת",[["24","24","ואבר מן החי דמטמא (אהלות רפ\"ב) — הרי באבר זה שפרש מן החי — בטל לא רק חיות הפרטי אלא גם כללות החיות. ופשוט. וראה נזיר נג, ב דלמדוהו מבחלל חרב. ותוד\"ה כזית חולין קכט, ב. ולהעיר מצפע\"נ השלמה טו, רע\"ג „אם המיתה הוה בכל אבר בפרט או בכלל כו'\". מהד\"ת ע, ב (ושם: המיתה צריכה שתהי' בכל הפרטים עיי\"ש). רפ\"ה מהל' מאכלות אסורות. ואכ\"מ."],["25","25","חולין שם במשנה. רמב\"ם הל' טומאת מת פ\"ב ה\"ז."],["26","26","ובפרש\"י שם ד\"ה המדולדלין „דכי ימות כתיב\" (וראה שטמ\"ק שם אות ד'). וראה תוי\"ט שם."],["27","27","רמב\"ם שם פ\"ג ה\"ט. ובכס\"מ שם: ופסק כר\"ל כו' (נדה כז, סע\"ב). וראה ירושלמי שם פ\"ג ה\"ג (הובא בתוד\"ה מת שם)."],["28","28","ראה חדא\"ג כאן עד\"ז. אלא שלדעתו טעו בזה."],["29","29","וכן מוכח מזה שכולל אשתו של לוט עם שאר הנסים (ברכות נד, א) „על כולן צריך שיתן הודאה ושבח לפני המקום\". ומ\"ש שם (ע\"ב) „בשלמא כולהו ניסא אלא אשתו של לוט פורענותא הוא\" — אין הכוונה דלא הוי נס אלא שאין בזה נס דהצלה. וראה יל\"ש בשלח (רמז רנו בסופו. יל\"ש אסתר רמז תתרנו בסופו): ותבט אשתו מאחריו ועד עכשיו היא עומדת נציב מלח למה זכר עשה לנפלאותיו שיהיו הדורות מתנין שבחו של הקב\"ה (וראה ב\"י או\"ח סרי\"ח קרוב לסופו)."],["30","30","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151176\" data-slug=\"likkutei-sichot\" data-id=\"1300151176\">לקו\"ש חי\"ה ע' 176</a> ובהערות שם. ח\"י ע' 89."],["31","31","שמות ד, ו."],["32","32","שם, ז. ראה צפע\"נ עה\"ת שמות שם. וכדמוכח ממרז\"ל (שבת צו, א. פרש\"י שם. ובכ\"מ) מכאן שמדה טובה ממהרת לבוא ממדת פורעניות."],["33","33","שהו' עי\"ז ש„ויולך ה' את הים ברוח קדים עזה כל הלילה\" (בשלח יד, כא) „ואילו הפסיק ה' את הרוח כרגע היו המים חוזרים וניגרים במורד כדרכם וטבעם\" (שער היחוד והאמונה פ\"ב). וראה בארוכה לקו\"ש ח\"ו שם."]]],[1300181252,"המים לדם 34 — און דעריבער, ווען דער נס איז נפסק געווארן, איז ממילא נתבטל געווארן די הפיכת המים לדם 35.\nאון דאס איז געווען דער תוכן פון זייער שאלה: „אשתו של לוט מהו שתטמא\": דאס וואס איר גוף איז געווארן א נציב מלח און האט אנגע־וואָרן צורה ותבנית פון א גוף, איז עס געווארן דורך א נס אינעם אופן הא' — דעמאלט דארף עס ניט מטמא זיין, היות אז דאס איז כלל ניט קיין תבנית פון א גוף; אדער דער נס איז געווען כאופן הב', וואס דאס מיינט אז אויך לאחר דעם וואס זי איז געווארן א נציב מלח איז זי געבליבן א מציאות פון בשר וכו' — א גוף מת — דעמאלט דארף אויף איר חל זיין טומאת מת 36.\nו. דאס איז אבער ניט מספיק. וואָרום לפ\"ז איז זייער שאלה ניט אין דעם ענין פון טומאת מת, נאר אין דעם אופן הנס וואס האט איר געמאכט א נציב מלח, און עפ\"ז איז יעדער שאלה אין אן אנדער ענין, וואס דאס איז ניט מסתבר.\nוי\"ל אז דער תוכן פון זייער שאלה „אשתו של לוט מהו שתטמא\" איז אויך בנוגע דעם גדר פון טומאת מת וואס ווערט מצד סילוק הנשמה: צי טומאת מת שאפט זיך פון עצם סילוק הנשמה 37, (און ווי מען קען (לכאורה) אפלערנען פון דעם וואס אבר המדולדל איז טהור כנ\"ל ויבאלד אז בא אים איז ניט געווען סילוק החיות, כאטש אז ער איז אזוי ווי אן אבר מת<sup data-n=\"38\">38</sup>, אדער סילוק הנשמה איז נאר א סיבה אויף דער חלות פון טומאת מת אויפן גוף; די טומאה קומט מצד הגוף: ד.ה. טומאת מת ווערט מצד דעם (און איז חל אויף א) גוף וואס פון אים איז נסתלק געווארן די נשמה. און ע\"ד ווי מען געפינט דוגמת שאלה וחקירה זו (אינעם צד החיוב) אין כמה מצות ודיני התורה:\nביי מצות מילה 39: צי דער עיקר המצוה איז פעולת המילה 40, אדער דער מכוון עיקרי איז די תוצאה וואס קומט פון פעולת המילה — דאס וואס ער איז ניט קיין ערל (און ווי ס'איז באוואוסט די אריכות השקו\"ט והנפק\"מ שבזה).\nועד\"ז ביי מצות כיסוי הדם 41: צי עיקר המצוה באשטייט אין פעולת הכיסוי און ניט נוגע וואס עס טוט זיך שפעטער, אדער די מצוה איז די תוצאה ותכלית הכיסוי — אז דער דם זאל זיין פארדעקט. און אויך אין דעם זיינען דא כמה נפק\"מ להלכה 42.",[["34","34","כדמוכח גם מזה שגיגית מלאה מים „ישראל שותה מים והמצרי דם וכשהי' לוקח מישראל בדמים הי' שותה מים\" (שמו\"ר פ\"ט, י). ולהעיר מגבורת ה' למהר\"ל הקדמה שני'."],["35","35","ולא מצינו שהיו צריכים להריק האגמים כו' לאחר המכה."],["36","36","להעיר מתרגום ירושלמי (וירא יט, כו) : עד זמן דתיתי תחיי דייחון מתיא."],["37","37","להעיר מלשון הספרי (פרשתנו יט, יג) „אשר ימות מגיד הכתוב שאין מטמא עד שעה שימות\". משא\"כ כשהוא מפרפר. וראה לשון הרמב\"ם ספ\"א מהל' טומאת מת. טושו\"ע יו\"ד סי' שע. ולהעיר מאוה\"ח ריש פרשתנו. ילקוט ראובני פרשתנו ד\"ה במדרש רות."],["38","38","אבל אינו מוכרח כי י\"ל דכל זמן שהוא מחובר לגוף עדיין אי\"ז אבר מת (לגמרי)."],["39","39","ראה צפע\"נ הל' מילה בתחילתו. צפע\"נ כלאים ע' 28. ובכ\"מ. לקו\"ש ח\"ג ע' 759 ואילך. ועוד."],["40","40","ועד שפועל שלא נק' ערל אח\"כ, דמשוך מותר לאכול בתרומה אע\"פ שנראה ערל וערל אסור לאכול בתרומה (יבמות עב, א. רמב\"ם הל' תרומות פ\"ז ה\"י)."],["41","41","ראה צפע\"נ הל' שחיטה פי\"ד ה\"א. מהד\"ת (ב, ב. לה, רע\"ג [ושם השמטה לדף לג, ד לענין מצות מילה]. מט, א. נה, סע\"ד)."],["42","42","ע' צפע\"נ שם מחולין פז, א גבי דם כיסוי"]]],[1300181253,"און בדוגמא לזה איז אויך דער תוכן פון זייער שאלה „אשתו של לוט מהו שתטמא\" 43.\nאויב דער גדר פון טומאת מת איז מצד דעם וואס דאס איז א גוף מת, און דער סילוק הנשמה איז נאר א גורם וסיבה וואס בריינגט אים צו זיין א גוף מת, דעמאלט איז פארשטאנדיק בפשטות אז „אשתו של לוט\" איז ניט מטמא, ויבאלד ס'איז ניט געבליבן קיין חומר וציור פון א גוף מת; אויב אבער די חלות הטומאה איז מצד סילוק הנשמה קען מען דאן זאגן אז אשתו של לוט דארף מטמא זיין, היות אז אויך ביי איר איז געווען סילוק הנשמה 44.\nז. „אמר להם מת מטמא ואין נציב מלח מטמא\". פון דעם וואס ער זאגט ניט קיין הסברה והכרעה אין די טעמי השאלה הנ\"ל, איז מוכח אז עס איז קיין נפק\"מ ניט צי דער נס איז געווען באופן אז עס איז אינגאנצן נשתנה געווארן צורת הגוף, אדער ער איז בעצם געבליבן א גוף ובשר אדם: און ס'איז אויך קיין חילוק ניט צי סילוק הנשמה איז נאר א סיבה פון דער טומאה אדער דער סילוק איז פועל די טומאה — בין כך ובין כך איז „אשתו של לוט\" ניט מטמא, ווייל „מת מטמא ואין נציב מלח מטמא\":\nמיט'ן ווארט „מת\" מיינט ער ניט צו באוואוענען אז דער גוף זאל זיין א מת — וואורום מאי קמ\"ל ? — נאר צו מדגיש זיין אז נאר אויף אים לייגט זיך די הגדרה פון מיתה, א גוף וואס איז בגדר מיתה קען אויף אים חל זיין טומאת מת; משא\"כ „נציב מלח\", ויבאלד אז ס'איז ניט קיין מציאות וואס איז בגדר פון מת, איז ביי אים ניט שייך טומאת מת [אפילו אננעמענדיק אז די טומאה קומט מצד סילוק הנשמה און ניט מצד גוף המת].\nעפ\"ז איז מובן וואס די גמרא רופט אן די שאלות „דברי בורות\" 45, הגם אז די סברות האבן אן ארט אין שכל שבתורה, וויל צו דער תשובה בנוגע דעם דין איז ניט נוגע די הכרעה אין די טעמי השאלה, ובכל אופן איז די מסקנה והתשובה די זעלבע.\nח. „בן שונמית מהו שיטמא\" — דא איז די שאלה נאר מצד דעם ענין פון סילוק הנשמה: מצד הגוף איז דאך דא שייך טומאה, ווייל ס'איז ניט „נתבלבלה",[["","","ממעטינן כסהו ונתגלה פטור מלכסות. ובכריתות (ד, סע\"ב) צריך קרא לרבות דם כיסוי לכרת. עיי\"ש (במהד\"ת) מה שכתב שנשאר שם דם כללי ולא דם פרטי כו'. אבל י\"ל דמזה שצריך קרא יתירה מוכח (לא רק שנתקיים מצותו בפעולת הכיסוי אלא גם) שע\"י עצם פעולת הכיסוי נתבטל ממנו תורת דם בכלל ולכן צריך קרא מיוחד שדם כיסוי בכרת. וראה צפע\"נ הל' שחיטה שם."],["43","43","ראה צפע\"נ (מהד\"ת שבהערה 24. ובכ\"מ. הובאו במפענצ\"פ פ\"ו ס\"ד) „אם המיתה גורמת הטומאה או מה שאין בה במה לטהר וכו'\", „אי המיתה עושה הטומאה או חיים עושין הטהרה\". אבל צ\"ע אם יש לפרש עפ\"ז השאלה באשתו של לוט. ואכ\"מ."],["44","44","לכאורה זהו רק לאופן הב' בנסים (דלעיל סעיף ה'), ולא לאופן הא' שם דנעשה טבע אחר, דלפי\"ז לכאורה אינו שייך בזה טומאה. אבל י\"ל גם לאופן הא', דכיון שבחומר זה הי' פעולת סילוק הנשמה (ראה זח\"א קח, ב. ראב\"ע וירא יט, כו. ולהעיר מתרומת הדשן שם) נשאר בזה גדר טומאה. משא\"כ בהנ\"ל דנשרף ונתבלבל צורתו שפקעה הטומאה שהרי אי\"ז הגוף שהי' בעת סילוק הנשמה. וראה תוד\"ה מישאל (סוכה כה, רע\"ב). אבל ראה שו\"ת צפע\"נ (ירושלים תשכ\"ה) סי' נה. ולהעיר מאיסור שנשתנה שפקע איסורו (רא\"ש ברכות פ\"ו סל\"ה) — ראה מי נדה לנדה כאן. ועוד."],["45","45","בחדא\"ג כאן „בחכמת היצירה וטבעית וקראום דברי בורות לפי שהם נטו לטעות בהם כדעת הפילוסופים\"."]]],[1300181254,"צורתו\" און ער איז אויך בגדר מיתה (ווי ער האט זיי פריער געענטפערט): די שאלה איז אבער, מצד סילוק החיות — צי די טומאה מצד דעם פריערדיקן סילוק איז בטל געווארן, ויבאלד אז ער האט שוין צוריק דעם חיות און ער לעבט: אדער די טומאה איז פארבליבן אויך שפעטער טראָץ דעם וואס ער איז ווידער א חי.\nוביאור הדבר: אינעם אופן ווי אזוי אלישע האט מחי' געווען דעם בן השונמית, זאגט דער פסוק 46: „ויעל וישכב על הילד וישם פיו על פיו ועיניו על עיניו וכפיו על כפיו ויגהר עליו ויחם בשר הילד .. ויזורר הנער עד שבע פעמים ויפקח הנער את עיניו\", וואס פון דעם איז מוכח אז ניט זיין אייגענע חיות האט זיך אומגעקערט צום „ילד\", נאר אלישע האט אים אריינגעגעבן א נייעם חיות 47 — פונעם חיות פון אלישע 48.\nאון דערמיט איז פארשטאנדיק פאר־וואס זיי האבן ניט געפרעגט וועגן בן הצרפית וואס אלי' הנביא האט מחי' געווען — וואורום דארטן האט דאך אלי' געבעטן 49 „תשב נא נפש הילד הזה על קרבו\" וישמע ה' בקול אלי' ותשב נפש הילד על קרבו ויחי\"; און ויבאלד עס האט זיך אומגעקערט „נפש הילד\" איז דערמיט בטל געווארן דער פריער־דיקער סילוק הנשמה ובמילא איז מובן אז ער איז ניט מטמא 50.\nביי בנה של שונמית אבער, ויבאלד אז זיין נשמה האט זיך צו אים ניט אומגעקערט, און זי איז געבליבן בהסתלקות פון גוף — ווערט דא די שאלה „מהו שיטמא\" 51: צי דער גדר פון סילוק הנשמה איז חל אויף א גוף מיט א נייעם חיות 52, אדער ער ווערט דורך דעם בטל 53.\n„אמר להם מת מטמא ואין חי מטמא\" — כאטש אז זיין נשמה האט זיך צו אים ניט אומגעקערט: די אלע גדרים והסברות אין טומאת מת — סילוק הנשמה, גוף מת כו' — זיינען שייך נאר בשעת דער גוף איז „מת\" בפועל; אויב אבער ער איז חי, כאטש אז פריער איז ער געווען א מת, איז ער ניט מטמא, ווייל חיות איז מבטל און מטהר 54 פון טומאת מת.\nאון מהאי טעמא איז אויך די צווייטע שאלה אן ענין פון „דברי בורות\": די צדדי הספק האבן דא קיין ארט ניט, ווייל ס'איז ניט תלוי אין דעם צי דער סילוק הנשמה ווערט נמשך אדער בטל",[["46","46","מ\"ב ד, לד־לה."],["47","47","ראה זח\"ב מד, סע\"ב."],["48","48","ראה רלב\"ג ומצו\"ד מ\"ב שם, לד: כאילו רצה שישפע חיות לנער מאברי אלישע כו'. אבל הם פירשו עד\"ז גם בבן הצרפית."],["49","49","מ\"א יז, כא־כב."],["50","50","ע\"ד אתי דבור ומבטל דבור מעשה מבטל מעשה אף שהוא לאחר כדי דבור ולאחר עשיית המעשה (ראה קידושין נט, א ואילך). ואכ\"מ."],["51","51","להעיר מזח\"ג ריז, א (בנוגע לפנחס). ואכ\"מ."],["52","52","ראה לשון רש\"י נדה שם „חי חשוב כמת\"."],["53","53","ואי\"ז תלוי בשאלה הא' (ס\"ו) אם סילוק הנשמה פועל הטומאה או זה שהוא גוף מת, כי גם לאופן הא' י\"ל שביטול הפעולה שע\"י סילוק הנשמה הוא לא רק ע\"י החזרת נשמתו בפועל, ולאידך גם אם נאמר דגוף מת הוא המטמא, י\"ל דגם לאחר שהחי' „חשוב כמת\", ע\"ד משנ\"ת לעיל בכיסוי דם דלאחר שנתכסה חל עליו הגדר דם כיסוי ולא בטלה ממנו אף לאחר שנתגלה (ראה צפע\"נ דלעיל הערה 41). ויתירה מזו י\"ל (כנ\"ל הערה 42) דבטלה ממנו תורת דם. ויומתק עפ\"י צד הב' בצפע\"נ (הנ\"ל הערה 43) דעיקר הטומאה הוא מחמת זה שאינו חי. וראה אוה\"ח ריש פרשתנו."],["54","54","להעיר מתוד\"ה פרה הא' (ב\"ק עז, א) — בסופו. ד\"ה הואיל (חולין פא, סע\"ב) — בסופו: חיותן מטהרתן. וראה צפע\"נ תרומות ע' 72. ועוד (נעתק במפענצ\"פ שם ס\"ג)."]]],[1300181255,"— דא איז נאר נוגע מצב הגוף בהווה, דער כלל אז „אין חי מטמא\" — ויבאלד ער איז בפועל א חי איז ניט שייך ער זאל זיין טמא ומטמא בטומאת מת.\nט. אויף דעם קען מען אבער פרעגן: זייענדיק א מת איז דאך דער זעלבער גוף געווען טמא — און נאך אלס אבי אבות הטומאה — טא ווי אזוי ווערט איצט פארשוואונדן די טומאה פון דעם גוף, ובל' הש\"ס 55 „טומאה שבהן להיכן הלכה\" ?\nנאר דאס ווערט פארשטאנדיק ע\"פ המבואר אין ילקוט שם לעיל: „נוגע במת טמא ואין מת עצמו טמא\", וואס דערפאר איז אויך בנה של שונמית טהור — ולא מצינו פלוגתא בזה (דריב\"ח (וסברת אנשי אלכסנדריא)). און ס'איז ניטא קיין תמי' אין דעם, ווייל טומאה פון א מת איז א גזירת הכתוב. ווי ער זאגט אין פסיקתא 56 „לא המת מטמא ולא המים מטהרים אלא גזירתו של מלך מלכי המלכים הוא\".\nועפ\"ז איז מובן וואס די שאלה ביי בן השונמית איז געווען „מהו שיטמא\" (א צווייטן), און ניט צי ער אליין איז טמא, און אזוי איז אויך דער לשון אין דער תשובה פון ריב\"ח „מת מטמא ואין חי מטמא\", היות אז די שקו\"ט איז געווען צי עס לייגט זיך אויף בן השונמית דער דין פון טומאת מת צו מטמא זיין א צווייטן מצד גזירת הכתוב.\nי. „מתים לעת\"ל צריכין הזאה שלישי ושביעי או אין צריכין\": דא איז ניט געווען די שאלה צי זיי זיינען מטמא א צווייטן בטומאת מת, היות ער האט זיי שוין געענטפערט „מת מטמא ואין חי מטמא\"; נאכמער אפילו לויט די סברה אין זייער צווייטער שאלה (מצד א נשמה חדשה ביים בן השונמית) זיינען די מתים לעת\"ל ניט טמא, וואורום דער אויב־ערשטער קערט דאך אום די זעלבע נשמה צום גוף (ווי די גמרא זאגט 57 „מביא נשמה וזורקה בגוף ודן אותם כאחד וכו'\"), ובמילא איז בטל סילוק הנשמה הקודמת. די שאלה דא איז נאר געווען (ווי מפרשים זאגן<sup data-n=\"58\">58</sup> צי זיי אליין זיינען טמא מצד טומאת מגע — אין זייער אייגענעם גוף, דהיינו די נגיעה פון גוף החי אין גוף המת בשעת התחי'.\nאון די שאלה איז צי „צריכין הזאה שלישי ושביעי או אין צריכין\": צי טומאת מגע מת איז נאר ווען א צווי־טער האט אנגערירט א מת, משא\"כ ווען נגע בעצמו; אדער טומאת מגע איז שייך אויך דאן ווען נגעו בעצמם 59?",[["55","55","פסחים לג, ב."],["56","56","דר\"כ פיסקא ד' (פרה). פסיקתא רבתי פי\"ד, יד. וראה רמב\"ם סוף הל' מקואות."],["57","57","סנהדרין צא, ב. (וראה שם סע\"א „גוף ונשמה יכולין לפטור עצמן מן הדין\"). פדר\"א פל\"ד (קרוב לסופו). זח\"א קכו, א (מהנ\"ע). קל, סע\"ב. ובכ\"מ."],["58","58","אהבת ציון דרוש ח' (מהנוב\"י). שו\"ת חת\"ס יו\"ד סי' שלו. רד\"ל נדה שם. וראה חדא\"ג שם באופן אחר."],["59","59","באהבת ציון שם „ואף אם תמצא לומר שזה מיחשב כנגיעת בית הסתרים\" (וראה גם חת\"ס שם שמציין לחולין עב, סע\"ב. בתוס' כו' והיינו הך דביה\"ס). וי\"ל: א) דכאן חשיב כשלש על שלש הבאות מבגד גדול דחולין שם עיי\"ש. ב) תלוי מתי נק' הנגיעה אם בשעת התחי' או לפנ\"ז. ג) אפילו אתי\"ל דהוי בשעת התחי' דכל הגוף בפועל, י\"ל שתלוי אם האדם נחשב כגוף אחד או שהוא מורכב מחלקים (האריך בזה בצפע\"נ (מהדו\"ת לח, א. נו, סע\"ג ואילך. שו\"ת דווינסק ח\"א סי' קי, קיא. ובכ\"מ (נעתקו (בחלקם) במפענצ\"פ ספ\"ב)). ושם דהוי פלוגתא דב\"ש וב\"ה באהלות פי\"א מ\"ג (ראה משנה אחרונה שם)), ולב\"ה דהוי כמורכב מחלקים הוי כמו בגדים הרבה מקופלים זע\"ג זה (דמשנה שם. ולהעיר ממהדו\"ת שם סע\"ד). ובזה גם ר\"י מודה דטמא מגע מדרס (מנחות כד, ב). וראה בשו\"ת"]]],[1300181256,"וי\"ל אז דער ספק איז תלוי בהסברא ווי אזוי וועט זיין דער אופן התחי' 60: א) צי עס וועט עפעס בלייבן אין גוף פון זיין ערשטער מציאות, נאר צו דעם וועט צוקומען הוספה והתחדשות אין בנין הגוף — וואס באופן זה איז פאראן די נגיעה אין א (חלק פון א) גוף מת און דערפאר וועלן די מתים לעת\"ל דארפן האבן „הזאה\"; ב) אדער תחיית המתים וועט זיין אין אן אופן פון התחדשות הגוף בכל הפרטים, עס וועט גארניט בלייבן פון גוף, ממציאותו הראשונה — און דעמאלט איז „אין צריכין הזאה\", ווייל ס'איז ניטא קיין נגיעה אין א מציאות פון א מת וואס איז מטמא.\nאון דעריבער האבן זיי געפרעגט בלשון „צריכין הזאה .. או אין צריכין\" (אן דער הקדמה פון „מהו\"), צו מרמז זיין אז דאס איז ניט קיין ספק אין דין פון מגע בעצמו, נאר די שאלה איז אין א מציאות: צי די תחי' וועט זיין באופן וואס וועט מחייב זיין זיי הזאה אדער ניט.\nיא. בפרטיות יותר, וועט דער ענין ווערן מבואר לויט דער משנה אין כלים 61: „מטה שהיתה טמאה מדרס נשברה ארוכה ותקנה טמאה מדרס (ויבאלד אז די צווייטע „ארוכה\" איז דאך דא) נשברה שני' ותקנה טהורה מן המדרס (דפנים חדשות באו לכאן) אבל טמאה מגע מדרס (ווייל די ערשטע נייע „ארוכה\" האט אנגערירט די מטה ווען זי איז געווען טמאה מדרס), לא הספיק לתקן את הראשונה עד שנשברה שני' טהורה (אפילו פון מגע מדרס)\" 62.\nד.ה. אויב דער תיקון הכלי איז געווען בשעת דער אנדער חלק פון כלי איז קיים, איז דא טומאת מגע; אבער אויב דער תיקון קומט נאכדעם ווי די גאנצע כלי איז צעבראכן געווארן, איז ניטא קיין טומאת מגע.\nאין סנהדרין 63 זאגט די גמרא: א\"ל קיסר לר\"ג אמריתו דשכבי חיי הא הוו עפרא ועפרא מי קא חיי, אמרה לי' ברתי' שבקי' ואנא מהדרנא לי', שני יוצרים יש בעירנו אחד יוצר מן המים ואחד יוצר מן הטיט איזה מהן משובח, א\"ל זה שיוצר מן המים א\"ל מן המים צר מן הטיט לא כש\"כ. דבי ר' ישמעאל תנא ק\"ו מכלי זכוכית, מה כלי זכוכית שעמלן ברוח בשר ודם שנשברו יש להן תקנה בשר ודם שברוחו של הקב\"ה על אחת כמה וכמה\".\nוי\"ל אז די צווי דוגמאות וביאורים דריקן אויס די צווי אופנים אין דרך התחי': אויב די תחי' איז בדרך „צר מן המים .. הטיט\", איז כאטש אז דער דין",[["","","צפע\"נ שם סק\"י „וזה הוי מחלוקת חולין דף ע\"ג, א. ופסחים פה, א כו' והיינו גמרא הנ\"ל לענין מגע בין הסתרים (ולהעיר מתוד\"ה חבורי חולין שם סע\"א). וראה (בב' וג' הנ\"ל) גם ערוך לנר נדה כאן ד\"ה צריכין. ד) ראה פיה\"מ להרמב\"ם ורע\"ב כלים פכ\"ז מ\"ט יו\"ד דאין הלכה כר\"י. וכ\"כ ברמב\"ם הלכות כלים פכ\"ג ה\"ז דהוי מגע מדרס גם בבגד אחד. וראה מל\"מ שם. ה) אפילו לדעת הרמב\"ם שם ה\"ט (ועוד) דהלכה כר\"י דהוי מגע בית הסתרים ואין טמא מגע הרי אין מוכרח ששאלתם (ותשובת ריב\"ח) תהי' כפי ההלכה דוקא ויתכן שזה שאלתם ובזה השקו\"ט דהרי סר\"ס הרי זה דעת תוס' ור\"מ דמגע ביה\"ס טמא. וראה לקמן הערה 86 ובהנסמן שם."],["60","60","פרטי ענין תחה\"מ ואופנה (בהבא לקמן) ראה תשובות וביאורים (קה\"ת, תשל\"ד) סי' ח' וי\"א*. וש\"נ. *) אגרות קודש כ\"ק אדמו\"ר שליט\"א ח\"א ע' קמא ואילך. ח\"ב ע' סה ואילך. המו\"ל."],["61","61","פי\"ח מ\"ז. ובר\"ש ורע\"ב שם."],["62","62","וראה שבת קיב, ב. ובתוד\"ה אבל שם."],["63","63","צ, סע\"ב ואילך."]]],[1300181257,"טומאת מת (פון קודם התחי') איז דא ניטא, וואורום לגבי דעם זאגט מען „פנים חדשות באו לכאן\", ס'איז אבער דא דער דין פון טומאת מגע, ויבאלד ס'איז געבליבן א געוויסע מציאות פון פריער, וואס פון דעם איז ער „צר\" דעם גוף (ע\"ד ווי דער צווייטער פאל פון דער משנה אין כלים).\nמיט דעם וואס דבי ר' ישמעאל פאר־גלייכן עס צו „כלי זכוכית .. שנשברו\", איז די כוונה אז עס האט כלל ניט קיין שייכות צו דער פריערדיקער מציאות 64, וואורום ביי כלי זכוכית, איז דער דין 65 אז דורך „נשברו\" ווערן זיי אויס כלי און אויב זיי זיינען געווען טמא ווערן זיי טהור לגמרי. עד\"ז בתחיית המתים, אז די תחי' איז באופן ווי מ'מאכט א נייע כלי פון כלי זכוכית שנשברו, וואס האבן קיין שייכות ניט צו זייער ערשטער מציאות, ובמילא איז אויף דער נייער מציאות פון גוף ניט שייך קיין טומאה מצד מגע במת (ווי דער לעצטער פאל אין דער משנה ביי טומאת מדרס) און דעמאלט איז „אין צריכין\" הזאה.\nאון עפ\"ז יובן וואס ריב\"ח האט זיי געענטפערט: „לכשיחיו נחכם להן\" — בשעת עס וועט זיין תחיית המתים דעמאלט וועט מען וויסן ווי דער אופן התחי' וועט זיין ובמילא וועט קלאר ווערן דער דין.\nיב. „איכא דאמרי לכשיבוא משה רבינו עמהם\", לויטן „איכא דאמרי\" איז די שאלה ניט געווען אויף כללות תחיית המתים דלעתיד — ווייל ריב\"ח האלט דאך אז זייער תחי' וועט זיין דורך בונה זיין דעם גוף פונעם „לוז של שדרה\" 66, ובמילא איז ברור אז ביי זיי איז דא טומאת מגע במת (כדלקמן) — נאר זייער ספק איז בשייכות דער תחי' דלעתיד פון די מתי מדבר בפרט.\nדער ביאור בזה: וועגן דור המדבר איז דא א מחלוקת 67: ר\"ע זאגט „אין להם חלק לעוה\"ב\", און ר\"א האלט, אז יש להם חלק לעוה\"ב. און פון דעם וואס רבה האט זיי געזען שוכבין ונראים כשתויי יין 68 איז משמע ווי דעת ר\"א.\nוהנה אין דעם אופן התחי' (בכלל) געפינט מען צווי דיעות: א) אז די תחי' וועט זיין פון עצם לוז וואס ווערט קיינ־מאל ניט נפסד 69, און אויף דעם שטייט „יחיו מתיך\" 70 און ניט יברא 71, ווייל דער אופן התחי' וועט זיין ניט דורך באשאפן אינגאנצן א נייעם גוף, נאר דער גוף 72 וועט נבנה ווערן פון „עצם לוז\". ב) ווי עס שטייט אין פדר\"א 73: „איני משתייר מן הגוף אלא כמלא תרווד רקב והוא מתערב בעפר הארץ כשאור שהוא מתערב בעיסה כו'\".",[["64","64","ראה פרש\"י ד\"ה יש להם תקנה. צפע\"נ סנהדרין שם."],["65","65","כלים פ\"ב מ\"א. שבת טז, א."],["66","66","ב\"ר פכ\"ח, ג. וש\"נ. ולכן דוחק לפרש כבחת\"ס שם ששאלתם היתה אם תשאר עצם נסכוי כו'."],["67","67","סנהדרין קח, א במשנה. שם קי, ב."],["68","68","ב\"ב עג, סע\"ב. תוד\"ה ודמו שם."],["69","69","ב\"ר הנ\"ל. ויק\"ר רפי\"ח. תוד\"ה והוא (ב\"ק טז, ב). זח\"א סט, א. קכו, סע\"א (מהנ\"ע). קלז, א (מהנ\"ע). זח\"ב כח, ב."],["70","70","ישעי' כו, יט."],["71","71","זח\"ב שם."],["72","72","וראה ב\"ר רפצ\"ה. זח\"א קטו, א (מהנ\"ע). קכו, א (מהנ\"ע). קל, סע\"ב. רג, ב. זח\"ג צא, א. רטז, רע\"ב (רע\"מ)."],["73","73","פל\"ד. וראה זח\"ג קסט, סע\"א ואילך. אבל להעיר שבאבקת רוכל ובעבוה\"ק (נסמן בתשובות וביאורים (קה\"ת, תשל\"ד) סי\"א* (בהערה 22) פי' דהיינו הך עצם לוז. וראה זח\"א קיג, א (מהנ\"ע). *) אגרות קודש כ\"ק אדמו\"ר שליט\"א ח\"ב ע' עו. המו\"ל."]]],[1300181258,"ועפ\"ז י\"ל, אז דאס וואס ר\"ע זאגט, אז דער דור המדבר „אין להם חלק לעוה\"ב\", איז דער מכוון אז פון זיי (זייערע גופים) וועט ניט בלייבן קיין מציאות וואס וועט אויפגעלעבט ווערן לעולם הבא, ווייל אויך זייער „עצם לוז\" ווערט נפסד 74; אבער נאכדעם ווי זיי וועלן ווערן „תרווד רקב\" 75 וועלן אויך זיי אויפשטיין צו תחיית המתים.\nאון אין דעם גופא איז באשטאנען די דריטע שאלה: ווי וועט זיין דער אופן התחי' פון די מתי מדבר — צי אין אן אופן אז פון מציאות הגוף וועט בלייבן עכ\"פ דער עצם לוז, און דערפאר „צריכין הזאה\", ווארום עצם כשעורה איז מטמא במגע 76 און זיי זיינען טמא מחמת נגיעה בגופם עצמם; אויב אבער עס וועט בלייבן נאר „תרווד רקב\" — דעמאלט איז „אין צריכין\" הזאה, ווייל תרווד רקב איז ניט מטמא במגע, נאר באהל 77; און אפילו באהל זיינען דא כמה תנאים ווען ער איז מטמא: „שיקבר 78 ערום בארון של שיש או של זכוכית וכיוצא בהן ויהי' כולו שלם\".\nיג. און אויף דעם האט ער זיי געענטפערט „לכשיבוא משה רבינו עמהם\" — און די הסברה בזה: עס שטייט אין תנחומא בפרשתנו 79 „מלה\"ד לרועה אחד שיצא צאנו של מלך ונשבית הצאן בקש הרועה ליכנס לפלטרין של מלך א\"ל המלך יאמרו שאתה השבית הצאן אף כך א\"ל הקב\"ה למשה שבחך הוא שהוצאת ששים רבוא וקברתם במדבר ואתה מכניס דור אחר עכשיו יאמרו אין למתי המדבר חלק לעוה\"ב אלא תהי' בצרן ותבא עמהם\" 80.\nפון דעם איז פארשטאנדיק אז היות משה רבינו איז געווען רועה של ישראל, ווי זיי (דער דור המדבר) זיינען נשמות בגופים [וואס דעריבער איז דורך משה רבינו געווען ניט נאר די השפעות רוחניות, ווי נתינת התורה (וואס אויך דאס איז געגעבן געווארן צו נשמות בגופים דוקא), נאר אויך די השפעות גשמיות — ווי מן, און אויך בארה של מרים וענני הכבוד חזרו בזכותו של משה 81], וועט ער אויך לעת\"ל זיך דארפן אומקערן מיטן דור המדבר, נשמות ווי זיי זיינען בגופים דוקא.\nאון דאס האט ריב\"ח געענטפערט „לכשיבוא משה רבינו עמהם\": אז משה רבינו יבוא „עמהם\", וואס דערפון וועט זיין מוכח אז יש להם חלק לעוה\"ב ווי משה, הייסט עס אז די תחי' וועט זיין פון מציאות גוף הראשון (עצם לוז), ובמילא וועלן זיי דאך דארפן האבן הזאה [און אויב משה רבינו וועט מיט זיי ניט קומען, איז דאך דאס דערפאר וואס",[["74","74","וע\"ד דור המבול בב\"ר הנ\"ל הערה 66."],["75","75","ועפ\"ז (דמשנ\"א בפרדר\"א „תרווד רקב\" ס\"ל דנעשה מציאות חדשה ופליג על הנ\"ל דנשאר עצם לוז) יומתק מה שממשיך בפרדר\"א שם „ומעלה את כל הגוף בלא מום\" ולא כבסנהדרין צא, ב. מקומות שבהערה 72."],["76","76","אהלות פ\"ב מ\"ג. רמב\"ם פ\"ג מהלכות טומאת מת ה\"ב. ופשיטא את\"ל שנשאר יותר מזה."],["77","77","אהלות שם מ\"א (וראה חולין קכה, ב). רמב\"ם שם ה\"ג. וראה תוס' רעק\"א אהלות שם. ואף שזה שאינו מטמא במגע הוא לפי שא\"א ליגע בכולו שהרי אינו גוף אחד (כבחולין שם ופרש\"י, רמב\"ם שם פ\"ב ה\"י\"א) משא\"כ בנדו\"ד דהוי כולו מחובר ביחד בגוף האדם, הרי (נוסף על המבואר לקמן שיש בזה תנאים) זה מפוזר בכל הגוף, ופשיטא דא\"א לומר דהוי מגע בכולו, וראה אהלות שם מ\"ב וברמב\"ם שם „ואפילו גבלו במים אינו חבור\"."],["78","78","רמב\"ם שם פ\"ג ה\"ד (מנדה כז, ב. וש\"נ)."],["79","79","יוד."],["80","80","ראה זח\"א קיג, ב (מהנ\"ע). זח\"ב קנז, סע\"א. וראה זח\"ג קסח, ב. ועוד."],["81","81","תענית ט, א."]]],[1300181259,"אין להם חלק לעוה\"ב און די תחי' וועט זיין פון תרווד רקב — דעמאלט איז „אין צריכין\" הזאה].\nיד. עפ\"ז יש לבאר אויך דעם חידוש אין דברי הילקוט בפשטות: דער ערשטער לימוד „נוגע במת טמא ואין מת עצמו טמא\" איז (בעיקר) מחדש דעם עצם ענין, אז מת עצמו איז ניט טמא, און ער איז מטמא אנדערע נאר מגזה\"כ, כנ\"ל. און פון דעם איז במילא מובן אז ביי א חי איז ניטא קיין ארט ער זאל מטמא זיין מצד גזה\"כ.\nדערנאך קומט דער לימוד וחידוש אז „נוגע במת טמא ואין בנה של שונמית טמא\", וואס דא איז ניט דער אויפטו אז ער איז ניט מטמא אנדערע לאחר שחי', אזוי ווי א מת (דאס ווייס מען פון פריער, כנ\"ל), נאר אז ער אליין איז ניט טמא געווארן מחמת דער נגיעה אין זיין גוף 82 בשעת התחי' 83.\nוואס לויט דעם איז מובן בפשטות וואס מען לערנט דאס אפ פון „נוגע במת\": אויך דא איז די הדגשה „נוגע במת\" (ע\"ד ווי אין דעם פריערדיקן לימוד „נוגע במת טמא ואין מת עצמו טמא\") ניט אין דעם לשון „מת\" מצ\"ע, וכנ\"ל.\nטו. דאס איז אויך די הסברה אין דעם וואס אין דער דריטער שאלה האבן זיי געפרעגט „מתים לעת\"ל צריכין הזאה שלישי ושביעי או אין צריכין\", און זיי האבן ניט געפרעגט אט די שאלה וועגן „בן שונמית\" גופא „דאיירו בי'\" 84 — וואורום די שאלה בנוגע להזאה איז דאך געווען מחמת דעם וואס נוגע בעצמם ניט אלס טומאת מת (כנ\"ל בארוכה), און דער חשש מצד נגיעה בעצמו איז שייך נאר ביי „מתים לע\"ל\" מצד דער נגיעה פונעם חי בעצמו (אינעם חלק הנשאר פון גוף המת): משא\"כ בא בן השונמית איז „פשיטא לי' דלא בעי הזאה\" (כלשון התוספות) 85, וואורום דער גוף פון בן שונמית איז ניט נשתנה געווארן 86 און",[["82","82","ראה עד\"ז גם בסדרי טהרות כלים (רנ, ב. ד\"ה אבל). אלא שכ' הפי' בספ\"ז דהנפק\"מ מזה ש„אין מת עצמו טמא\" הוא בזה ש„אין בנה של שונמית טמא\", וגם מטעם אחר כדלקמן בפנים."],["83","83","וכן מוכח מהמשך הלשון בספ\"ז וילקוט „וכשחי' הי' טהור לקודש\" דלכאורה למאי נפק\"מ (הרי בא לומר דאף „כשמת כל שהי' עמו בבית טמא הי' טומאת שבעה\" הרי „כשחי'\" אינו טמא ו„חזרו ונגעו בו טמאוהו הם\")? אלא שבא להדגיש ד„כשחי' הי' טהור (לגמרי) לקודש\", היינו שאין עליו טומאה של נוגע במת דטמא לקודש. ועי\"ע בסדרי טהרות שם דמפרש ההמשך בספ\"ז „הרי זה אומר כו'\" (לא כבית רענן שם): הרי זה אומר לאלו הכלים מטמאך דהיינו הוא עצמו לא טמאוני שלא נטמא ממגע עצמו כו'. ולכאורה משמע כן מזה ש„הרי זה אומר מטמאך כו'\" אי' אחר שכתב „חזרו ונגעו בו טמאוהו הם\" דלפי פשטו אינו שייך לזה."],["84","84","כתוד\"ה מתים נדה ע, סע\"ב."],["85","85","אבל באהבת ציון וחת\"ס שם דבבן השונמית פשיטא להו דבעי הזאה מחמת נוגע בעצמו (וכ\"כ בחדא\"ג כאן לפירושו שבעי הזאה אם כבר נטמא בחיים במת), והרי\"ז דלא כמ\"ש בספ\"ז וילקוט הנ\"ל דהי' טהור. ובמאירי לנדה כ' דשאלתם אם בעי הזאה הי' על כל המתים הן בבן השונמית כו'."],["86","86","אבל אין לומר שכיון שעומד לחיות הו\"ל כחי גם בשעת מיתתו, וכמ\"ש בפי' נרבוני שם (הובא באברבנאל שם) ולא הי' טמא מעולם, וכ\"כ בדברי שאול (יוסף דעת) יו\"ד (סי' שעג, ס\"ה), ומוסיף „וגם בן השונמית אם הי' יודע אדם בבירור שיחי' לא הי' מטמא וד\"ב כשמש\"י, דהרי מפורש בספרי זוטא ד„חזרו ונגעו בו טמאוהו הם\", ולא אמרינן דאף את\"ל שכשנגעו בו *) וראה מאירי נדה כאן דיש מפרשים דהשאלה בבן השונמית היא אם טימא במיתתו. ודוחה הפי'. ועד\"ז באברבנאל שם. וראה לעיל שוה\"ג להערה 20."]]],[1300181260,"איז געבליבן אין דעם זעלבן אופן וציור כל הזמן 87.\nוי\"ל בסגנון אחר: ביי בן שונמית איז די תחי' געווען (ניט אין אן אופן ווי די מתים לעת\"ל, וואו מ'קען זאגן אז דער (חלק ה)גוף איז נתתקן ונבנה געווארן, נאר) אין אן אופן פון התהפכות און א מציאות חדשה — א מציאות חי אנשטאט מציאות מת 88 (ובפרט מטעם הנ\"ל, אז ביי בן שונמית איז נפשו לא שבה אליו, און היות ס'איז א נייער חיות איז עס דאך במילא א נייע מציאות). ובמילא איז, דא ניט שייך קיין טומאת מגע במת מצד נוגע בעצמו 89.\nטז. עוד י\"ל (עכ\"פ בקיצור) — ועפ\"ז יומתק וואס פאר אנשי אלכסנ־דריא דוקא 90 איז געווען נוגע דעם פתרון פון די דריי שאלות. ובהקדים:\nאלכסנדריא איז דאך א שטאט במצרים אויף וועלכע עס שטייט לא תוסיפון לשוב 91 כו' „ואלכסנדריאה בכלל האיסור\" 92.\nוי\"ל אז זייער סברא איז געווען: לכתחילה איז מען אהין געקומען אויף צייטוויילעג שלא ע\"מ „להשתקע שם\", און כאטש דערנאך נשתקעו ולא יצאו משם — אין אזלינן בתר המצב אין אנהייבס 93. און לבירור הדבר האבן זיי געפרעגט די דריי שאלות: אשת לוט — כאטש אפילו סופה „נציב מלח\", אבער תחלתה איז דאך אדם ומהי שתטמא: עכ\"פ בן שונמית — וואס ס'איז דער זעלבער גוף; עכ\"פ בתחה\"מ — וואס איז אויך די זעלבע נשמה, כנ\"ל — יצרכו הזאה — ויבאלד נולדו מיט דעם ציווי אז: אדם כי ימות",[["","","במיתתו נחשבו טמאים הרי לאחר שהחי' מוכח דלא נחשב כמת ואיגלאי מילתא למפרע דלא היו טמאים. וראה הגהות הרד\"ל לפרדר\"א פל\"ג אות ד."],["87","87","בשו\"ת חת\"ס שם דבן שונמית ד„בשעה שהחייהו נגע בעצמו במותו. ועי' כיוצא בזה משנה א' פ\"ג דטהרות קרשו הרי אלו שנים דבשעת שנקרשו ויצאו מטומאת משקה מ\"מ הו\"ל כאוכל שנגעו במשקה\". אבל שם הפי' דהוי נגיעה כפשוטה דכל משהו שנקרש איטמא מן המשקה שבצדו (משנה אחרונה טהרות שם), וכבסיום המשנה „יותר מכביצה טמא שכיון שיצא טפה ראשונה נטמאת\" ע\"י נגיעתה (ראה מפרשים שם). וראה עד\"ז (ועי\"ד הנ\"ל בפנים) ערוך לנר בנדה כאן [ולהעיר מדין סדין שהוא טמא מדרס ועשו וילון (כלים פכ\"ז מ\"ט) דלדעת ר\"י כיון שנשתנתה טהור לגמרי (ראה פיה\"מ להרמב\"ם. רע\"ב שם. רמב\"ם הל' כלים פכ\"ג ה\"י'). וראה רע\"ב טהרות שם בחזרו ונמוחו כביצה מכוון טהור „ופרחה טומאתו כשנשתנו\" פי' הרא\"ש שם). גם לדעת התק' שנשאר טמא מגע מדרס, יש לחלק בנדו\"ד דשם הוי הסדין טמא בעצמו. משא\"כ כאן בבן שונמית כיון דאין מת עצמו טמא, ורק שמטמא אחרים א\"כ כשחי' פקע זה. וראה סדרי טהרות שם]. ולהעיר מלקח טוב להרי\"ו ענגיל כלל יד."],["88","88","ההסברה בזה י\"ל: במתים לעת\"ל מוכרח הדבר שיחיו אז (והרי תחה\"מ הוא עיקר באמונה) והיינו דמצד הגוף יש בו תכונה וכו' שיחי', וזהו סדר שכלול בהגוף (ולהעיר מאבות ספ\"ד „הילודים למות והמתים לחיות\" וראה סנהדרין (צא, א): „דלא הוה חייא דהוה חייא לא כ\"ש\"), וא\"כ נמצא דגוף החי יש לו שייכות והמשך לגוף המת, משא\"כ בבן הצרפית ובן שונמית שהתחי' הי' שלא ע\"פ סדר המוכרח בגוף זה, כ\"א בדרך חידוש ונס, דמצד עצמן היו מתים, הרי נמצא דגוף החי אין לו שייכות והמשך לגוף המת. ואין כאן נגיעה בעצמו."],["89","89","לכאו' עדיין צ\"ע מדוע „כשחי' הי' טהור\" ודוקא „חזרו ונגעו בו טמאוהו\", ולא נטמא מצד אהל המת כמו „כל שהי' עמו בבית\". ומזה מוכח דמת עצמו לא שייך שיטמא עוד גם לדעת הספ\"ז דאין מת עצמו טמא. ראה סדרי טהרות שם."],["90","90","בס' חלק יעקב (להרב אביגדור. נ. י. תש\"י) עמד ע\"ז. — ותירץ — בנוגע לכל השאלות — באופן אחר."],["91","91","שופטים יז, טז."],["92","92","רמב\"ם הל' מלכים פ\"ה ה\"ז (מסוכה נא, ב)."],["93","93","ראה רדב\"ז (שם ה\"ג) — די\"ל דגם למסקנא רק איסורא בעלמא הוא באופן זה."]]],[1300181261,"— הנוגע בו דארף זיין והזה ביום השלישי וביום השביעי.\nיז. והנה „כל ישראל יש להם חלק לעוה\"ב\" 94 — אלע וועלן אויפשטיין נשמות בגופים, אעפ\"כ י\"ל אז דורך עסק התורה בזמן הזה וועט מען דארפן אנקומען צו הזאה לעת\"ל, הגם אז ביי יעדן איינעם בלייבט דער עצם לוז — ווייל, ווי רז\"ל זאגן 95, „כל המשתמש באור תורה אור תורה מחייהו\" (אדער ווי דער לשון „טל תורה מחייהו\"<sup data-n=\"96\">96</sup>, וואס בשעת די תחי' איז ע\"י אור תורה וטל תורה 97, איז דאס גופא מטהר בשעת התחי' 98.\n(משיחת כ\"ד טבת תשי\"א)",[["94","94","סנה' צ, א."],["95","95","כתובות קיא, ב."],["96","96","יל\"ש ישעי' כו, יט. <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא ספל\"ו</a>. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111200\" data-slug=\"likkutei-sichot\" data-id=\"1300111200\">לקו\"ש חי\"א ע' 193</a> בהערה."],["97","97","ולהעיר מזח\"א קעה, ב. קפב, רע\"א. ובכ\"מ."],["98","98","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381017\" data-slug=\"likkutei-torah\" data-id=\"4001381017\">ראה זח\"ג מט, א</a>. ובלקו\"ת האזינו עג, ג. שהטל דתחיית המתים הוא למעלה מ„שיורי טלא דבדולחא\" שמטהר טומאת מת דזהר שם. וראה המשך וככה תרל\"ז פס\"ח. ועוד. ולהעיר גם ממרז\"ל (סנהדרין לט, א) עיקר טבילתא בנורא, ועל תורה נאמר (ירמי' כג, כט) „הלא כה דברי כאש\", ואינו מקבל טומאה (ברכות כב, א). וראה חגיגה בסופה „ת\"ח שכל גופן אש\". ובארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161447\" data-slug=\"likkutei-sichot\" data-id=\"1300161447\">לקו\"ש חט\"ז ע' 434</a> ואילך."]]],[1300181262,"<h3>חוקת ג</h3>\nא. חז\"ל זאָגן1, אַז דער באר וואָס האָט באַזאָרגט די אידן אין מדבר מיט וואַסער איז געווען בזכות מרים, און דערפאַר, איז גלייך נאָך דער פטירה פון מרים — „ולא הי' מים לעדה\"2; און די ענני כבוד זיינען געווען בזכות אהרן, און ווען „מת אהרן נסתלקו ענני כבוד\".\nפונדעסטוועגן איז דער באר געווען אויך נאָך פטירת מרים און די ענני כבוד נאָך פטירת אהרן, ווייל דערנאָך, ווי חז\"ל זאָגן1, „חזרו שניהם בזכות משה\".\nבהשקפה ראשונה זעט אויס, אַז אויך רש\"י בפירושו על התורה — לימוד פשוטו של מקרא — נעמט אָן ווי דברי חז\"ל הנ\"ל:\nאויפן פסוק2 „ולא הי' מים לעדה\" איז רש\"י מפרש „מכאן שכל מ' שנה הי' להם הבאר בזכות מרים\", און אויפן פסוק3 „וישמע הכנעני\" ברענגט ער4 „שמע שמת אהרן ונסתלקו ענני כבוד\"; לאידך אָבער געפינט מען, אַז דער באר איז געווען אויך נאָך פטירת מרים, ווי דערציילט ווייטער אין חומש5 (ביים נס פון „אשד הנחלים\"), און ווי רש\"י איז מפרש אויף „ומבמות הגיא . . בשדה מואב\"6 — „כי שם מת משה ושם בטלה הבאר\".\nדערפון איז משמע, אַז רש\"י נעמט אָן אַז דעם באר האָט דער אויבערשטער צוריקגעקערט בזכות משה7; ובמילא איז מסתבר, אַז אויך די ענני כבוד חזרו בזכות משה8 — ווייל עס לייגט זיך ניט צו זאָגן אַז זכותו של משה האָט גע־האָלפן נאָר פאַר חזרת הבאר און ניט פאַרן אומקער פון די ענני כבוד.\nלפ\"ז איז אָבער תמוה: בנוגע דעם באר דערציילט די תורה9 ווי אַזוי ער איז צוריקגעקומען — אַז „ולא הי' מים לעדה ויקהלו על משה גו' וירב העם גו'\", און דער אויבערשטער האָט גע־זאָגט משה'ן „קח את המטה גו'\" און די אידן האָבן ווידער געהאַט מים פון דעם סלע;\nמשא\"כ בנוגע די ענני כבוד, ווערט ניט באַוואָרנט — ניט אין חומש און ניט אַפילו אין פירוש רש\"י — ווי אַזוי און ווען „חזרו\"!\nאויך דאַרף מען פאַרשטיין: כשם ווי דער ביטול הבאר נאָך מיתת מרים האָט גורם געווען צו „ויקהלו9 על משה גו' וירב העם גו'\", האָט אויך דער סילוק ענני כבוד נאָך מיתת אהרן לכאורה גע־דאַרפט אַרויסרופן אַן אויפגערודערט־קייט ביי די בנ\"י — פאַרוואָס געפינט מען ניט אַז אידן זאָלן האָבן טענות אויף דעם וואָס „נסתלקו ענני כבוד\"10?",[["1","1","תענית ט, א. ספרי דברים פי' שה. מכילתא בשלח טז, לה. ועוד."],["2","2","פרשתנו כ, ב."],["3","3","פרשתנו כא, א. ועד\"ז לפני\"ז כ, כט. לקמן פינחס כו, יג. מסעי לג, מ. עקב י, ו."],["4","4","„כדאיתא בר\"ה\" (ג, רע\"א)."],["5","5","רש\"י פרשתנו כ, י־יא. כא, טז ואילך ובפרש\"י."],["6","6","שם, כ."],["7","7","ראה שפ\"ח שם. וראה רש\"י שם, יח: חפרוה שרים משה ואהרן (ראה במקומות שבהערה 1: וחזרה בזכות שניהן)."],["8","8","ראה שפ\"ח שם, טו; הנסמן לקמן הערה 37, 38."],["9","9","פרשתנו כ, ב ואילך."],["10","10","כי מה שחזרו לאחוריהם כו' לאחרי מיתת אהרן (רש\"י פרשתנו כא, ד. פינחס ועקב שם) הי'"]]],[1300181263,"ב. לכאורה וואָלט מען געקענט איינלערנען, אַז ע\"פ פשוטו של מקרא זיינען די ענני כבוד מער ניט צוריק־געקומען נאָך זייער סילוק לאחרי פטירת אהרן10*; און דער טעם דערפון איז פשוט — מען האָט מער ניט גע־דאַרפט אָנקומען צו די עננים:\nרש\"י האָט שוין פריער11 מפרש גע־ווען אַז די עננים האָבן אַרומגערינגלט אידן „מד' רוחות . . למעלה . . למטה\", וואָס דורכדעם האָבן זיי (א) באַשיצט די אידן „לבל יכה בהם שרב ושמש\"12; (ב) ווי רש\"י ברענגט ווייטער13 — „היו שפים בכסותם ומגהצים אותם\"; און נאָך אַן ענן איז פאָראויסגעגאַנגען (ג) „לנחותם הדרך\"14, און (ד) אויסגלייכן דעם וועג און באַשיצן פון מזיקין: „מנמיך את הגבוה ומגבי' את הנמוך והורג נחשים ועקרבים\"15.\nאָבער נאָך פטירת אהרן האָבן די אידן זיך מער ניט גענויטיקט אין דעם אַלעם וואָס די עננים האָבן אויפגעטאָן פאַר זיי, ווייל „הר ההר\" געפינט זיך שוין „על גבול ארץ אדום\"16, ביים סוף פון מדבר, נאָענט צו מקומות של ישוב; ומובן אַז דאָס איז אַן אָרט וואו דער „שרב ושמש\" פון מדבר איז פיל שוואַכער.\n[און ניט נאָר מצד דעם מקום — אויך מצד דעם זמן: פטירת אהרן איז געווען „בחודש החמישי באחד לחודש\"17 — חודש אב, נאָענט צו דער צייט ווען די היצן ווערן שוואַכער, וואָרום „מחמשה עשר באב ואילך תשש כחה של חמה\"18.\n— ס'איז ניט קיין סתירה פון דעם וואָס רש\"י איז מפרש אין פ' נח19, אַז „חום\" מיינט „סוף ימות החמה חצי אב ואלול וחצי תשרי שהעולם חם ביותר . . שלהי20 קייטא קשי מקייטא\" — ווייל, דאָרט איז דער טעם, ווי רש\"י איז מדייק בלשונו: „שהעולם חם ביותר\", „לפי שכבר נתחמם כל האויר וגוף הבריות בחום הקיץ שעבר עליו\"21; אָבער היץ פון זריחת השמש מצ\"ע ווערט שוואַ־כער פון חמשה עשר באב ואילך, ווי מ'זעט עס במוחש.\nובנדו\"ד, וויבאַלד אַז ביז מיתת אהרן (דער „קיץ שעבר עליו\") האָבן די עננים באַשיצט אידן פון דעם חום השמש, איז דאָ ניט געווען „כבר נתחמם (כל האויר ו)גוף הבריות בחום הקיץ שעבר עליו\" — און היות אַז מחמשה עשר באב ואילך איז די זריחת השמש ניט מיט אַזאַ שטאַרקייט, האָבן זיי ניט געדאַרפט אָנ־קומען צו די ענני כבוד „לבל יכה בהם שרב ושמש\"].\nועד\"ז האָבן זיך די אידן ניט מער גע־נויטיקט (אַזויפיל) — (א) אין דעם וואָס",[["","","(לא מחמת הסתלקות ענני כבוד, כ\"א) מפני „מלחמה זו\" (לשון רש\"י פרשתנו שם) שהי' כמה זמן לאחרי סילוק ענני כבוד. והרי העננים שמשו לכמה דברים, כדלקמן בפנים. 10*) ראה עד\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131074\" data-slug=\"likkutei-sichot\" data-id=\"1300131074\">לקו\"ש חי\"ג ע' 74</a> הערה 16. ושם, ש(גם) מטעם זה מביא רש\"י (פרשתנו כא, ח) השאלה „וכי נחש ממית\" בשם „רבותינו\" — כי שאלה זו היא רק ע\"פ „רבותינו\" שענני כבוד חזרו (בזכות משה) והיו הורגים נחשים (כדלקמן בפנים), משא\"כ ע\"ד הפשט שאינו מפורש (ע\"ע) שחזרו העננים. אבל ראה בארוכה לקמן בפנים."],["11","11","בהעלותך י, לד."],["12","12","לשון אדה\"ז שו\"ע או\"ח ר\"ס תרכה, מטושו\"ע שם. וראה ישעי' ד, ו."],["13","13","עקב ח, ד."],["14","14","בשלח יג, כא."],["15","15","פרש\"י בהעלותך שם."],["16","16","פרשתנו כ, כג. מסעי לג, לז."],["17","17","מסעי שם, לח."],["18","18","תענית לא, א."],["19","19","ח, כב."],["20","20","יומא כט, רע\"א — צויין ברש\"י נח שם („כמו ששנינו במס' יומא\")."],["21","21","פרש\"י יומא שם ד\"ה שלהי."]]],[1300181264,"די ענני כבוד „היו שפים בכסותם ומגהצים וכו'\"22 — וואָרום אויב דאָרט וואָלט ביי אַ אידן געווען דער פאַל פון „שמלתך . . בלתה מעליך\", האָט ער גע־קענט קויפן אַ לבוש אין איינע פון די דערבייאיקע שטעט פון אומות העולם23; (ב) אויך האָט מען שוין ניט געדאַרפט אָנקומען בהכרח צום נס אַז אַן ענן זאָל זיי ווייזן דעם וועג, היות מ'האָט זיך גע־פונען אין אַן אָרט וואו ס'זיינען שוין דאָ דרכים כבושות וכו'; (ג) און עד\"ז אויך ניט דעם אויפטו פון „הורג נחשים ועקרבים\" זייענדיק נאָענט צו מקומות של ישוב24.\n[און אע\"פ אַז דער ענן האָט גע־דאַרפט משוה זיין די הרים כו', און ווי רש\"י איז מפרש אויף „הר ההר\"25 — „ואע\"פ שהענן הולך לפניהם ומשוה את ההרים, שלשה נשארו בהן . . והר נבו לקבורת משה כו'\", וואָס דערפון זעט מען, אַז דער ענן איז מיטגעגאַנגען אויך (נאָך מיתת אהרן) ווען אידן זיינען גע־קומען צו הר נבו (וואו משה איז נסתלק געוואָרן) —\nוואָלט מען געקענט פאַרענטפערן (בדוחק עכ\"פ), אַז דאָס וואָס דער ענן האָט משוה געווען אַלע הרים (חוץ הר נבו) מיינט (ניט, אַז דאָס איז פאָרגע־קומען בעת די אידן זיינען דאָרט גע־קומען, נאָר) אַז דאָס האָט זיך אָפּגעטאָן פריער (מהלך ג' ימים שהלך לפני־הם<sup data-n=\"26\">26</sup>, נאָך איידער אהרן איז נסתלק גע־וואָרן, כדי צו באַוואָרענען דעם עתיד.\nעפ\"ז וואָלט געווען אויך רעכט דער סדר ווי רש\"י רעכנט דאָרט אויס די דריי הרים וואָס זיינען ניט אויסגע־גלייכט געוואָרן: „הר סיני . . והר נבו . . והר ההר\" — וואָס לויט סדר המאו־רעות וואָלט „הר נבו\" געדאַרפט שטיין נאָך „הר ההר\" —\nאָבער ע\"פ הנ\"ל וואָלט מען עס גע־קענט מסביר זיין: מיט מקדים זיין הר נבו פאַר הר ההר איז רש\"י מרמז, אַז דאָס וואָס דער ענן האָט איבערגעלאָזט הר נבו לקבורת משה איז דאָס ניט גע־ווען אין אַ שפּעטערדיקן זמן (ווען אידן זיינען אַהינצו געקומען), נאָר אין דעם זעלבן זמן ווען ער האָט איבערגעלאָזט הר ההר לקבורת אהרן].\nג. אין אמת'ן אָבער, איז מוכרח צו זאָגן, אַז די עננים האָבן זיך אומגע־קערט און באַגלייט די אידן אויך נאָך פטירת אהרן, ווייל:\nא) בפשטות ווערט מיט „לנחותם הדרך\" ניט געמיינט (בלויז) צו פאַר־היטן פון בלאָנדזשען אין מדבר (וואו ס'זיינען ניטאָ קיין דרכים), נאָר בכלל צו ווייזן דעם דרך, די ריכטונג וואָס דער אויבערשטער וויל אַז די אידן זאָלן גיין27 — און וויבאַלד אַז אויך נאָך מיתת אהרן זיינען געווען כו\"כ מסעות, האָט מען אויך דעמאָלט געדאַרפט אָנקומען צום ענן.\nב) רש\"י זאָגט בפירוש28, אַז נאָך מיתת",[["22","22","ואף שזה נאמר במשנה תורה לאחרי מיתת אהרן — הרי משה סיפר אז מה שהי' במשך שהותם במדבר."],["23","23","ראה יומא עה, ב."],["24","24","להעיר ממש\"נ (עקב ח, טו. וראה דברים א, יט וברש\"י) „במדבר הגדול והנורא נחש שרף ועקרב\" — והרי כבר יצאו מ„מדבר הגדול והנורא\"."],["25","25","פרשתנו כ, כב."],["26","26","פרש\"י בהעלותך י, לה."],["27","27","ראה פרש\"י בשלח שם. וראה פרש\"י יהושע (ג, ג) דלאחרי מיתת משה הי' הארון מראה להם הדרך (במקום הענן)."],["28","28","נסמן לעיל הערה 10."]]],[1300181265,"אהרן „חזרו לאחוריהם דרך ים סוף . . שבע מסעות\" — צוריק אין מדבר29.\nג) די עננים האָבן באַשיצט אידן אויך פון מלחמות מיט די אומות העולם. ווי רש\"י האָט שוין מפרש געווען ביי מלחמת עמלק30, אַז „וצא הלחם בעמלק\" מיינט „צא מן הענן והלחם בו\". וואָס דערפון איז פאַרשטאַנדיק אַז כל זמן אידן זיינען געווען אַרומגענומען פון די עננים האָבן די אומות העולם ניט גע־האַט קיין שליטה צו לוחם זיין מיט זיי31; און ווי רש\"י האָט שוין מפרש געווען פריער32, אַז דער ענן האָט מקבל גע־ווען די „חצים ואבני בליסטראות\" וואָס „היו מצרים זורקים\",\n[און דערפאַר, גלייך נאָך מיתת אהרן — „וישמע הכנעני . . וילחם בי־שראל\"33, ווי רש\"י איז מפרש34, אַז דער־זעענדיק אַז „נסתלקו ענני כבוד\" האָט ער געמיינט אַז „נתנה רשות להלחם בישראל\"],\nאשר לכן האָט מען געדאַרפט די ענני כבוד צו באַשיצן אידן אויך אין די שפּעטערדיקע מלחמות.\nד) דער אויפטו פונעם ענן אין די מ\"ב מסעות, איז געווען ניט נאָר צו ווייזן וואו צו גיין, נאָר אויך (ווי די תורה איז מאריך אין פ' בהעלותך<sup data-n=\"35\">35</sup> צו מודיע זיין ווען און ווי לאַנג עס זאָל זיין דער „יחנו\" און דער „יסעו\", וואָס דאָס איז נויטיק אין אַלע מסעות, ביז מען איז אַריין אין א\"י.\nה) ועיקר: רש\"י ברענגט אַראָפּ אין פ' בלק (נאָך מיתת אהרן), אויפן פסוק36 „והוקע אותם לה' נגד השמש\" — „השמש מודיע את החוטאים הענן נקפל מכנגדו והחמה זורחת עליו\" — זאָגט דאָך רש\"י בפירוש37, אַז דער ענן איז געווען אויך נאָך מיתת אהרן38 (און האָט מגין געווען פון דעם שמש).\nאיז הדרא קושיא לדוכתא: פאַרוואָס ווערט ערגעץ ניט דערמאָנט (אַז — און ווי אַזוי) די ענני כבוד האָבן זיך צוריק־געקערט — און פאַרוואָס האָט דער סילוק זייערער ניט אַרויסגערופן קיין פאַרדרוס ביי אידן, כנ\"ל?\nד. וועט מען דאָס פאַרשטיין בהקדם אַ דיוק און שינוי לשון אין פירוש רש\"י עה\"ת: אין כמה מקומות39 רופט ער אָן די עננים — „ענני כבוד\", און אין אַ צאָל ערטער40 — „עננים\" (סתם).",[["29","29","ראה פרשתנו כא, ה."],["30","30","בשלח יז, ט."],["31","31","ומה שעמלק הי' יכול להלחם בישראל (ובפרט באופן ד„וגבר עמלק\" — שם, יא) כבר תי' רש\"י שם (פסוק ח) שבנ\"י השואלים היש ה' גו' — „השליכו מעליו\" — חוץ לענן, וכמפורש ברש\"י תצא (כה, יח) „שהי' הענן פולטן\". ועד\"ז כש„ויעפילו לעלות וגו'\" (שלח יד, מד־מה. דברים א, מא־מד) שפשוט שהי' מחוץ לענן, שהרי הי' היפך ציווי ה'. וראה לקמן בפנים סוף סעיף ה והערה 58."],["32","32","יתרו יט, ד. — בפרש\"י בשלח (יד, יט. וראה רש\"י האזינו לב, יא) שהמלאך קבלם. אבל ראה בארוכה מפרשי רש\"י בשלח שם. ואכ\"מ."],["33","33","פרשתנו כא, א."],["34","34","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081205\" data-slug=\"likkutei-sichot\" data-id=\"1300081205\">מסעי</a> לג, מ (וראה בארוכה לקו\"ש ח\"ח ע' 194 ואילך, הטעם שלא הביאו רש\"י בפרשתנו, ולאידך מוסיף בפרשתנו „ועמלק מעולם רצועה כו'\")."],["35","35","ט, יז ואילך. וראה פקודי מ, לו ואילך."],["36","36","כה, ד. ואף שמביאו מ„מדרש אגדה\" — הרי כמדובר כמ\"פ, כל מה שהובא בפרש\"י עה\"ת הוא פשוטו של מקרא או אגדה המיישבת דברי המקרא (רש\"י בראשית ג, ח. ובכ\"מ)."],["37","37","וכן מפורש בפרש\"י תצא כג, יג „חוץ לענן\" (וראה שפ\"ח ומשכיל לדוד שם). וכן מוכח בפרש\"י יהושע שם."],["38","38","ראה חזקוני, ריב\"א, שפ\"ח ומשכיל לדוד בלק שם."],["39","39","פרש\"י אמור כג, מג. פרשתנו כ, כט. כא, א. פינחס כו, יג. מסעי לג, מ. עקב ח, ד. י, ו."],["40","40","ראה לקמן בפנים."]]],[1300181266,"אָט די צוויי לשונות געפינט מען אויך אין די מדרשי חז\"ל וואו עס שטייט אַז עס זיינען געווען שבעה עננים: אין טייל מדרשי חז\"ל41 איז די גירסא „שבעה עננים היו\" (וכיו\"ב), און אין אַנדערע42 — „שבעה ענני כבוד היו\" (וכיו\"ב). רש\"י בפירושו על התורה43 קלייבט אויס און שרייבט „שבעה עננים כתובים כו'\".\nויש לומר הביאור: דעם חילוק צווישן עננים סתם און ענני כבוד — קען מען זאָגן בפשטות: „ענני כבוד\" מיינט פשוטו כמשמעו, אַז דער גאַנצער תכלית זייערער איז נאָר צו ווייזן כבודם של ישראל44. ד. ה. עס זיינען געווען עננים וואָס זייער ענין איז געווען צו באַשיצן און באַזאָרגן די אידן מיט זייערע צרכים און ענינים המוכרחים — חאָטש בדרך ממילא פאַרשטייט מען דערפון חבתן (וכבודם) של ישראל. און עס זיינען גע־ווען נאָך עננים וואָס כל ענינם איז גע־ווען לשם „כבוד\" — אַרויסווייזן אויף וויפל דער אויבערשטער איז מכבד די אידן.\nאון דערפון איז מובן, אַז ניט אַלע עננים זיינען ענני כבוד: דער ענן וואָס „מנמיך את הגבוה כו' והורג נחשים ועקרבים\"15 איז ניט פון די ענני כבוד, ווייל זיין אויפטו איז אַ דבר של הכרח אויף צו קענען גיין אין מדבר; און עד\"ז דער ענן וואָס האָט זיי באַשיצט פון חום השמש אָדער פון אוה\"ע בשעת מלחמה, איז ער ניט (נאָר) צוליב כבודם של ישראל, נאָר צוליב אַ תועלת אין ענינים נחוצים — דערפאַר נוצט רש\"י אין די מקומות דעם לשון „ענן\" (סתם)\n[לדוגמא: „וצא הלחם בעמלק — צא מן הענן\"30; „זורקים חצים . . והענן מקבלם\"32; „הר ההר — . . ואע\"פ שהענן הולך לפניהם ומשוה את ההרים כו'\"25; „נגד השמש — . . הענן נקפל כו' והחמה זורחת עליו\"36; „כל הנחשלים אחריך — . . שהי' הענן פולטן\"45].\nמשא\"כ ביי די עננים וואָס זיינען נסתלק געוואָרן נאָך מיתת אהרן, איז דאָרט דער לשון: „נסתלקו (נאָר די) ענני כבוד\"46 — נאָר די עננים וואָס זיינען געווען לכבודם של ישראל, אָבער ניט די עננים47 וואָס האָבן באַוואָרנט די צרכים פון אידן48 — און די ענני כבוד האָבן זיך (ע\"פ פשוטו של מקרא) טאַקע ניט אומגעקערט (ומובן ג\"כ ובפשטות פאַרוואָס אידן האָבן ניט געהאַט קיין טענות בנוגע ענני כבוד ווי זיי האָבן גע־האַט ביי בארה של מרים).",[["41","41","מכילתא בשלח יג, כא („שבעה עננים הם\". אבל ראה שם לאח\"ז). ספרי בהעלותך י, לד. תנחומא במדבר ב (אבל בא בהמשך למ\"ש לפני\"ז „ענני כבוד\"). זח\"ג שב, סע\"ב. ועוד."],["42","42","תנחומא בשלח ג. במדבר יב. תוספתא סוטה פ\"ד, א. מכילתא בשלח שם. ברייתא דמלאכת המשכן רפי\"ד. ספרי זוטא בהעלותך שם. במדב\"ר פ\"א, ב. יל\"ש פקודי רמז תכו. זח\"ג רפג, ב. תקו\"ז תכ\"א (נה, א). ועוד. וראה זח\"ג קג, א."],["43","43","בהעלותך שם. ולהעיר ג\"כ מרש\"י האזינו (לב, י) „והקיפם בעננים\". ברש\"י יחזקאל (טז, י) „ומדרש אגדה . . שבעת ענני כבוד כו'\". אבל (נוסף לזה שהוא „מדרש אגדה\", הרי) כמדובר כמ\"פ, פרש\"י לנ\"ך אינו ע\"ד הפשט כ\"כ — כמו פירש\"י עה\"ת."],["44","44","משא\"כ ע\"ד הדרוש כו' — ש„כבוד\" הוא כינוי לשכינה. וראה לקמן הערה 47."],["45","45","תצא כה, יח."],["46","46","אבל להעיר מפרש\"י קהלת (ז, א) „וכן אהרן בעמוד ענן\". וראה הערה 43."],["47","47","להעיר גם מרש\"י תענית (ט, א ד\"ה ונסתלקו): „ענני רקיע וענני עשן ושאר עננים אינן של כבוד\" (אבל ידוע השקו\"ט (שד\"ח ח\"ט ע' א'תתיד ועוד) אם הפי' לתענית הוא לרש\"י)."],["48","48","ראה גם שפ\"ח בלק שם. ולפ\"ז אתי פרש\"י פרשתנו (כ, כב) כפשוטו — דלא כנ\"ל בפנים ס\"ב בסופו. ומה שכותב רש\"י „הר נבו\" לפני „הר ההר\" — נת' בשיחת ש\"פ חקת תשל\"ז."]]],[1300181267,"[דערמיט קען מען פאַרענטפערן די קשיא פון רא\"ם49: וויבאַלד עס זיינען געווען עננים מד' רוחות וא' מלמעלה וא' מלמטה15 — און אַ סוכה איז בדוגמא צו די עננים (ווי רש\"י50 איז מפרש: „כי בסוכות הושבתי — ענני כבוד\") — האָט אויך אַ סוכה געדאַרפט האָבן „א' מלמעלה וא' מלמטה וד' מד' רוחותי'\" (און דער דין51 איז, אַז עס איז גענוג צוויי גאַנצע דפנות און אַ דריטע וואָס האָט אַ טפח)?\nויש להוסיף בקושיתו — פאַרוואָס מאַכט מען ניט קיין זכר צו דעם זיבעטן ענן וואָס איז געווען „לפניהם\"?\nוע\"פ הנ\"ל איז עס פאַרענטפערט: דער זכר וואָס מיר מאַכן איז נאָר צו די „ענני כבוד\"52 — די עננים וואָס כל ענינם איז נאָר לשם „כבוד\"53; אָבער דער ענן וואָס איז געווען „לפניהם\", ועד\"ז כמה פון די אַנדערע ששה עננים, האָבן (אויך) משמש געווען אויף צו באַ־וואָרענען די צרכים54 פון די אידן כנ\"ל, ובמילא איז אויך דער מספר דפנות הסוכה — ניט פאַרבונדן מיט מספר ענני הכבוד. ובפרט אַז י\"ל אַז עס איז אין דעם געווען שינוים — במסע ווען מ'האָט ניט געדאַרפט האָבן הגנה מצד מסוים — איז דער ענן מצד זה געווען אַן ענן הכבוד].\nה. עפ\"ז וועט מען אויך פאַרשטיין אַ דיוק אין פרש\"י הנ\"ל (סעיף ג) אויף „וישמע הכנעני\"34 — „שנסתלקו ענני כבוד וכסבור שנתנה רשות להלחם בישראל\" — דלכאורה האָט רש\"י גע־דאַרפט דערמאָנען דעם עיקר החידוש (אויך) — „שנתנה האפשריות והרשות להלחם בישראל\" — וויבאַלד אַז די אידן זיינען פריער געווען אַרומגענומען פון די עננים און עס איז געווען אומ־מעגלעך צו מלחמה האָבן מיט זיי (כנ\"ל שם) —\nוע\"פ הנ\"ל איז עס מובן55: אויך נאָך דעם ווי „נסתלקו ענני כבוד\" איז גע־בליבן דער ענן וואָס האָט באַשיצט אידן פון אוה\"ע בשעת מלחמה; דער כנעני האָט אָבער געמיינט, אַז וויבאַלד עס זיינען נסתלק געוואָרן די ענני כבוד — דער אויבערשטער ווייזט שוין מער ניט אַרויס אַזויפיל כבוד צו אידן, איז דאָס אַ באַווייז אַז „נתנה רשות להלחם בי־שראל\"; אָבער בנוגע דער אפשריות למלחמה (מצד די אַנדערע עננים) האָט זיך גאָרניט געביטן56.\n[און ס'איז ניט קיין קשיא: ווי איז אפשר און ווי קומט עס אַז דער כנעני57",[["49","49","בהעלותך שם. וראה גו\"א וצידה לדרך שם. ב\"ח לטאו\"ח סו\"ס תרכה. פרמ\"ג (א\"א) שם. וראה לקו\"ש אמור תשמ\"ט בסופו."],["50","50","אמור שם. ולהעיר מרש\"י בהעלותך (ט, יח) „כמין סוכה\" — אבל שם המדובר בענן שהי' על המשכן (כמשמעות הכתובים שם, וכדיוק לשון רש\"י „עמוד הענן\"), והי' „נמשך (רק) על גבי בני יהודה . . עד שמשה אומר שובה וכו'\". ואכ\"מ."],["51","51","סוכה ו, ב. טושו\"ע או\"ח סתר\"ל ס\"ב."],["52","52","כדיוק לשון רש\"י „ענני כבוד\". ולהעיר מהשינוי בין ת\"א ותיב\"ע שם."],["53","53","עפ\"ז מתורץ ג\"כ מה שהקשה בב\"ח שם „למה ציוה יותר במצות סוכה . . יותר משאר חסדים\" (כמו מן ובאר כו') — כי סוכה הוא זכר (לא לענין של הספקת צרכים, כ\"א) לענין של כבוד. וראה לקו\"ש שם."],["54","54","ראה ב\"ח שם דזה שלמטה הי' מנמיך הגבוה (ובפרמ\"ג שם, שהי' מגין מפני נחשים). אבל בפרש\"י בהעלותך (י, לד) שכל זה נעשה ע\"י זה ש„לפניהם\", וכמ\"ש בצידה לדרך שם."],["55","55","ראה ביאור באו\"א — לקו\"ש ח\"ח שם."],["56","56","אבל להעיר מתוספתא סוטה (פי\"א, א): אי' הלך התייר שלהם המכביש להם את הדרך."],["57","57","ועד\"ז סיחון ועוג. וכן אדום (פרשתנו כ, יח־כ) — שהי' לפני מיתת אהרן וסילוק ענני כבוד."]]],[1300181268,"זאָל פאַרפירן אַ מלחמה מיט אידן בשעת זיי זיינען באַשיצט פון דעם ענן? — ווייל, אין הכי נמי, אין דעם פרט האָט אים די חוצפה פאַרפירט ביז צו שטות כו'; און ער האָט גערעכנט אַז אידן וועלן אַרויסגיין פון דעם ענן כדי צו מלחמה האָבן מיט אים58.\nובפרט לויט פרש\"י לפני\"ז33 אַז דער כנעני דאָ איז עמלק — און עמלק איז דאָך געווען דער וואָס האָט שוין פון פריער געפירט מלחמה מיט אידן „הנח־שלים אחריך — שהענן פולטן\"59, אַפילו ווען „היו כל האומות יראים להלחם בכם . . קפץ וירד . . אע\"פ שנכוה כו'\"59; האָט ער ווידעראַמאָל זיך פאַרמאָסטן קעגן אידן אין אַן אופן פון „קפץ\", ניט קוקנדיק וואָס זיי זיינען געווען באַ־שיצט פון דעם ענן].\nו. אויף דער הסברה הנ\"ל, אין דעם חילוק צווישן „ענני כבוד\" און עננים סתם, קען מען אָבער פרעגן: רש\"י זאָגט דאָך13 אַז די „ענני כבוד היו שפים בכסותם ומגהצים אותם . . ואף קטניהם כמו שהיו גדלים הי' גדל לבושן עמהם\", וואָס די ביידע אויפטואונגען פון די ענני כבוד זיינען לכאורה פון די זאַכן וואָס געהערן צו הצטרכות בני אדם און ניט אַן ענין פון כבוד (לחוד)60.\nאין אמת'ן אָבער איז דאָס קיין קשיא ניט. וואָרום, בפשטות, איז דאָס וואָס רש\"י זאָגט „ואף קטניהם . . הי' גדל לבושן עמהם\" מיינט ער ניט בהמשך און אַלס אויפטו פון די ענני כבוד61 — וואָרום וואָס פאַר אַ שייכות האָט „גדל לבושן עמהם\" צו די ענני כבוד?! — נאָר ריידנדיק וועגן די לבושים זאָגט רש\"י אַז מיט זיי איז געשען אַ (באַזונ־דער) נס, וואָס זיי זיינען מיטגעוואַקסן צוזאַמען און פאַרבונדן — ניט מיט עננים וכו' — נאָר מיט זייערע גופים (ווי רש\"י זאָגט דאָרט) „כלבוש הזה של חומט שגדל עמו\".\n[און דער טעם וואָס רש\"י ברענגט דאָס בהמשך צו זיין פירוש אַז „ענני כבוד היו שפים בכסותם כו'\", איז ווייל גלייך דאָ קען זיך שטעלן די שאלה: בשלמא די גדולים האָבן געקענט נאָכ־אַנאַנד טראָגן די זעלבע קליידער, צוליב דעם וואָס „שמלתך לא בלתה מעליך\" — ווי אַזוי אָבער האָבן די קטנים גע־קענט כסדר טראָגן אין מדבר די זעלבע קליידער בעת זיי וואַקסן און ווערן גדול יותר? באַוואָרנט דעריבער רש\"י, אַז דערביי האָט דער אויבערשטער געוויזן אַ נס, אַז „הי' גדל לבושן עמהם\"].\nאון דאָס וואָס די „ענני כבוד היו שפים בכסותם ומגהצים אותם\", איז ניט געווען אַ הכרח — ווייל אויך לולא די „ענני כבוד\" וואָלטן די אידן אין מדבר דאָס געקענט טאָן — דורכפירן דעם שיפוי וגיהוץ באופן הרגיל.\n[ובדוגמא ווי „שמלתך לא בלתה\" — איז ניט געווען אַ נס הכרחי — ווייל זיי",[["58","58","כי העננים הועילו רק להגן מפני החצים כו' כנ\"ל, אבל לא שיוכלו בנ\"י לנצח האויב ולכבוש ארצו כו', וכדמוכח מפרש\"י בשלח (יז, ט) „צא מן הענן והלחם בו\". וכן הי' גם בפועל בנדו\"ד, שלכן הי' אפ\"ל „וישב ממנו שבי\" (פרשתנו כא, א). וכן במלחמת סיחון ועוג ומלחמת מדין, בפשטות יצאו בנ\"י מן הענן. ולהעיר מרש\"י יחזקאל טז, טו."],["59","59","פרש\"י תצא כה, יח."],["60","60","ובפרט שבכ\"מ (מדרש תהלים מזמור כג. דב\"ר פ\"ז, יא. שהש\"ר פ\"ד, יא) הגירסא „הענן שף כו'\", ורש\"י בוחר בהגירסא (פסיקתא דר\"כ פ' בשלח. הובא ביל\"ש עקב שם) „ענני כבוד\"."],["61","61","וכן מוכח מלשון המדרשים שצויינו בהערה הקודמת „ולא היו (הקטנים) גדלים . . החלזון הזה כו'\" — ולא נזכר ע\"ד ענני כבוד רק אח\"כ, ע\"ז ש„לא היו צריכין תכבוסת\"."]]],[1300181269,"האָבן זיך געקענט באַזאָרגן מיט נייע לבושים — אָדער פון די ריבוי „שמ־לות\"62 וואָס מ'האָט מיטגענומען ביי יציאת מצרים63, אָדער מאַכן פון דעם צמר הכבשים וכו' וואָס זיי האָבן גע־האַט פון דעם מקנה זייערן, אָדער דורך קויפן אַ לבוש בעת זיי זיינען פון צייט צו צייט געווען בקירוב צו אַ מקום ישוב64].\nאון וויבאַלד אַז דער „שפים\" און „מגהצים\" דורך די ענני כבוד דוקא איז געווען (ניט אַן ענין הכרחי פאַר אידן, נאָר) בלויז צו פאַרשפּאָרן זיי אַ טרחא (קלה), איז דאָך דאָס גופא דער אמת'ער ענין און צייכן פון כבוד — אויף וויפיל דער אויבערשטער איז מייקר ומכבד די אידן — און דערפאַר איז דאָס שייך צו די ענני כבוד.\nז. עס בלייבט אָבער צו פאַרשטיין: וויבאַלד רש\"י6 זאָגט אַז „בטלה הבאר\" איז פאַרבונדן מיט מיתת משה, איז משמע אַז רש\"י נעמט אָן, אַז חזרת הבאר איז געווען בזכות משה (כנ\"ל ס\"א) — היינט פאַרוואָס זיינען אויך די ענני כבוד ניט צוריקגעקומען בזכות משה?\nוי\"ל הביאור בזה: לויט פשוטו של מקרא — איז דאָס אַלעס וואָס אידן האָבן באַקומען דורך משה'ן — איז (ניט ווי באַ אהרן ומרים — וואָס בזכותם האָבן אידן באַקומען ענני הכבוד ומים, נאָר) — משה אַלס רועה נאמן האָט פאַרזאָרגט אידן מיט אַלעם וואָס זיי נייטיגן זיך, און ווען זיי נייטיגן זיך אין דעם.\nועפ\"ז יומתק: מען זעט, אַז דער ענין — וואָס משה האָט באַזאָרגט אידן מיט זייערע צרכים — איז (ניט ווי אַן ענין התלוי בזכות, וואָס ווערט בטל נאָך דער הסתלקות פון בעל הזכות65, נאָר) אין אַן אופן אַז עס ווערט באַוואָרנט אַז נאָך זיין פטירה זאָלן זיי (דאָס אויך באַקומען, אָדער זיי זאָלן) צו דעם ניט דאַרפן אָנ־קומען:\nאע\"פ אַז נאָך מיתת משה איז „בטלה הבאר\" — האָבן אָבער די אידן מער ניט געדאַרפט אָנקומען צום באר, ווייל זיי זיינען שוין דאַן געווען באַם ירדן66; ועד\"ז בנוגע דעם מן, האָט שוין רש\"י67 מפרש געווען, אַז (אע\"פ) „כשמת משה בז' אדר פסק המן מלירד (האָבן זיי אָבער געהאַט דעם מן אויך שפּעטער היות) ונסתפקו ממן שלקטו בו ביום עד שהקריבו העומר בששה עשר בניסן\".\nח. דערפון האָט מען דעם לימוד בנוגע צו נשיאי ישראל בכל דור ודור, אַז אויך נאָך הסתלקותם, ווען בעיני בשר זעט מען ניט זייער השפעה באופן גלוי (ע\"ד ווי דער מן נאָך מיתת משה, וואָס מ'האָט אַ קוק געטאָן אין וועלט האָט מען געזען אַז פסק מלירד) — איז אָבער דאָ דער כלל מפורסם, אַז „לא יפרדו מעל צאן מרעיתם\"68;",[["62","62","בא יב, לה („כלי כסף וכלי זהב ושמלות\". והרי הי' באופן של „וינצלום\" (שם, לו). וראה פרש\"י בא יג, יג — ע\"ד ריבוי הכלי כסף וזהב)."],["63","63","כמ\"ש הראב\"ע עקב שם."],["64","64","ועפ\"ז, גם את\"ל ד„הי' גדל עמהם\" שייך לענני כבוד — אי\"ז ענין הכרחי."],["65","65","כמו „ולא הי' מים לעדה\" לאחרי מיתת מרים, ונסתלקו ענני כבוד לאחרי מיתת אהרן."],["66","66","סוף פרשתנו. ועוד."],["67","67","בשלח טז, לה (ממכילתא שם. ולדעת ר\"י שם, אכלוהו י\"ד שנה אחר מיתת משה!)."],["68","68","לשון כ\"ק מו\"ח אדמו\"ר ע\"ד אביו כ\"ק אדמו\"ר מהורש\"ב נ\"ע במכתבו ליאָרצייט הראשון שלו (ב' ניסן תרפ\"א) — נדפס בס' חכמי ישראל (נ.י. תרפ\"ד) לג, א. אגרות קודש אדמו\"ר מהוריי\"צ נ\"ע ח\"א ע' קמא."]]],[1300181270,"און ניט נאָר מצד דעם וואָס „אף כאן עומד ומשמש (ממרום)\"69 — וואָס דאָס איז ניט שייך צו זען בעיני בשר — נאָר אויך דערפאַר וואָס די פעולות וענינים וואָס זיי האָבן אויפגעטאָן פאַר אידן בחיים חיותם בעלמא דין, זיינען אַ פעולה נמשכת — מ'איז זיך „מסתפק\" פון זיי אויך נאָך זייער הסתלקות פון עולם הזה.\nט. און דאָס איז אויך די שייכות מיוחדת פון דעם ענין הנ\"ל מיט דעם חג הגאולה פון כ\"ק מו\"ח אדמו\"ר די\"ב־י\"ג תמוז — וואָס פאַלט אויס (בכו\"כ שנים — וכקביעות שנה זו) אין די ימי השבוע פון שבת פ' חקת (דמיני' מתברכין<sup data-n=\"70\">70</sup> — ווייל אָט דער ענין זאָגט זיך אַרויס באופן ניכר אין דער גאולה פון רבי'ן:\nמ'זעט במוחש, ווי דער נצחון וגאולה פון י\"ב־י\"ג תמוז בימים ההם, וואָס האָט גע'פועל'ט אַז אַפילו אין יענער מדינה זאָל זיין החזקת התורה והפצת היהדות וכו' — איז אַ פעולה נמשכת עד היום הזה. דאָס האָט שוין אויפגעשטעלט דריי דורות פון אידן שומרי תורה ומצוה במדינה ההיא — וואָס דאַן פסק'נט אָפּ תורה אַז „לא ימושו מפיך ומפי זרעך ומפי זרע זרעך גו' מעתה ועד עולם\"71.\nאון נאָכמער: מ'זעט, אַז אַפילו אַזעלכע וואָס זיינען שוין כמה דורות געווען אָפּגעריסן ר\"ל פון תורה און אידישקייט — צוליב דעם מצב איום ותנאים איומים במדינה ההיא — אויך זיי זיינען זיך „מסתפק\" פון דער פעולת הגאולה עד היום הזה, אַז דאָס איז זיי איצט מעורר מיט אַ תנועה פון תשובה און זיי קערן זיך אום צו אַ לעבן פון תורה און אידישקייט.\nאון דורך דעם וואָס מ'וועט טאָן כדבעי אין די פעולות פון דעם חג הגאולה72 צו מחזק זיין תורה ויהדות און מפיץ זיין זיי, כולל ובפרט ענין שהזמן גרמא — הפצת מעיינות החסידות חוצה — וועט דאָס אַראָפּברענגען דעם „קא אתי מר\" דא מלכא משיחא, במהרה בימינו אמן.\n(משיחות מוצאי ש\"פ מטו\"מ, ש\"פ דברים וט\"ו באב תשל\"ט)",[["69","69","סוטה יג, סע\"ב."],["70","70","זח\"ב סג, ב. פח, א."],["71","71","ישעי' נט, כא. ב\"מ פה, א."],["72","72","ראה מכתב בעל הגאולה לחגיגה הראשונה — י\"ב תמוז תרפ\"ח (נדפס בסה\"מ תרפ\"ח (ע' קמו) ותש\"ח (ע' 263) ועוד)."]]],[1300181271,"<h3>בלק</h3>\nא. שוין גערעדט אַמאָל בארוכה, אַז כאָטש רש\"י בפירושו עה\"ת איז מפרש פשוטו של מקרא, און דאָרטן וואו ער ברענגט אין זיין פירוש דרשות רז\"ל, איז דאָ אויף זיי אַ הכרח ע\"פ פשט 1 — פונדעסטוועגן זעט מען אַז אין אונזער פרשה, בשייכות צו דברי בלעם, ברענגט רש\"י אַראָפ אַ ריבוי דרשות רז\"ל, כלל שלא ע\"ד הרגיל בפירושו.\nדי הסברה אין דעם: תורה — בפשוטו של מקרא — זאָגט בפירוש „וישא משלו” 2, איז מובן, אַז (אויך) לויטן דרך הפשט איז דער פירוש פון אָט די פסוקים ניט (באַגרענעצט) לויט דעם פשוט'ן טייטש פון די ווערטער 3, נאָר עס איז דאָ אַ נמשל, אין זיי געפינען זיך (אויך) רמזים און דרשות וואָס זיינען ניט מפורש אין די ווערטער פון פסוק:\nאָבער צוזאַמען דערמיט איז מובן, אַז אויך די דרשות האָבן אַ הכרח אין פשט הכתוב, זיי האָבן אַ שייכות און זיינען נוגע צום הבנת הכתוב 4.\nעפ\"ז דאַרף מען פאַרשטיין דעם צווייטן ד\"ה בפירוש רש\"י אויפן פסוק 5 (אין דברי בלעם) „כי לא נחש ביעקב ולא קסם בישראל כעת יאמר ליעקב ולישראל מה פעל א-ל”. רש\"י איז מעתיק די ווערטער „כעת יאמר ליעקב וגו'” און איז מפרש: עוד עתיד להיות עת כעת הזאת אשר תגלה חיבתן לעין כל שהן יושבין לפניו ולומדים תורה מפיו ומחיצתן לפנים ממלאכי השרת והם ישאלו להם מה פעל א-ל וזהו שנאמר 6 והיו עיניך רואות את מוריך, ד\"א יאמר ליעקב אינו לשון עתיד אלא לשון הווה אינן צריכים למנחש וקוסם כי בכל עת שצריך להאמר ליעקב ולישראל מה פעל הקב\"ה ומה גזרותיו במרום אינן מנחשים וקוסמים אלא נמסר להם ע\"פ נביאיהם מה היא גזירת המקום או אורים ותומים מגידים להם. ואונקלס לא תרגם כן.\nולכאורה:\nא) די אריכות אין פרש\"י — בפרט אין ערשטן פירוש — וואו איז דאָס אַלץ מרומז (און וואָס איז עס נוגע צום פשט) אין די ווערטער פון פסוק ?\nב) וואָס איז די שווערקייט אין יעדן פון די פירושים, וואָס רש\"י דאַרף אָנקומען צו ביידע פירושים ?\nג) רש\"י איז מקדים דעם ערשטן פירוש פאַרן צווייטן, וואָס ווייזט אַז ער איז נעענטער צום פשט — מיט וואָס איז דער ערשטער פירוש נעענטער צו פשש\"מ ?\nד) וואָס איז רש\"י אויסן מיט'ן סיום „ואונקלס לא תרגם כן” 7 — בריבוי",[["1","1","כפירושו בפ' בראשית — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051001\" data-slug=\"likkutei-sichot\" data-id=\"1300051001\">לקו\"ש ח\"ה ע' 1</a> ובהערות שם."],["2","2","כג (ז. יח). כד (ג. טו. כ. כא. כג)."],["3","3","שע\"ד הפשט מדבר ברמז — ראה פרש\"י משפטים כא, יג. ובכללות יותר: כל דברי בלעם אלה ה\"ה ענין של נבואה ובלילה (ראה רש\"י פרשתנו כב, ה. כב, ח), והרי נבואה (גם לנביאי ישראל) היא בחלום וחזיון (בהעלותך יב, ו. ובפרש\"י שם) ו„בחידות” (שם, ח) וא\"כ מובן שע\"פ דרך הפשט הכתוב אומר דרשני."],["4","4","ראה פרש\"י משפטים שם."],["5","5","כג, כג."],["6","6","ישעי' ל, כ."],["7","7","בכמה כת\"י רש\"י ליתא."]]],[1300181272,"מקומות איז תרגום אונקלס אַנדערש פון פרש\"י, און רש\"י דערמאָנט עס ניט.\nב. מפרשים 8 זאָגן, אַז דער הכרח אויף דעם ערשטן פירוש איז פון דעם לשון „כעת” — מיט אַ כ\"ף הדמיון 9, וואָס פון דעם נעמט רש\"י אַז „עוד עתיד להיות עת כעת הזאת”: ניט די איצטיקע צייט ממש, און בדומה צו דער פריער געזאָגטער צייט פון „ותרועת מלך בו” 10 (וואָס איז ווי רש\"י טייטשט) „לשון חיבה ורעות”, וועט קומען נאָך אַזאַ צייט („כעת”) ווען „תגלה חיבתן לעין כל כו'”, און איז מפרש וואָס עס מיינט דער ענין פון „תגלה חיבתן”.\nאון לויטן צווייטן פירוש קומען די ווערטער „כעת יאמר ליעקב” בהמשך צו התחלת הכתוב „כי לא נחש ביעקב ולא קסם בישראל”: בשעת אידן דאַרפן עפעס וויסן ווערט זיי דאָס איבער־געגעבן דורך די נביאים אָדער אורים ותומים.\nולפ\"ז, איז לויטן ערשטן פירוש שווער, וואָס דער תוכן פון „כעת יאמר וגו'” האָט ניט קיין המשך צו התחלת הכתוב 11; און אויך אין צווייטן פירוש איז דאָ אַ שווערקייט: א) בפשטות איז „יאמר” לשון עתיד, ניט לשון הווה 12, ב) דער לשון „כעת”, מיט אַ כ\"ף הדמיון 11.\nאָבער לויט דעם בלייבט נאָך אַלץ צו פאַרשטיין:\nא) אין הכי נמי אַז פון פסוק איז מוכח אַז ס'וועט זיין נאָך אַ צייט בדומה צו דער צייט, וואָס דעמאָלט וועט געזאָגט ווערן „ליעקב ולישראל מה פעל א-ל” — פון וואַנעט איז אָבער די ראי', און וואָס איז נוגע אין פשטות פירוש הכתובים, די פרטים „שהן יושבין לפניו ולומדים תורה מפיו ומחיצתן לפנים ממלאכי השרת” און די מלאכים וועלן זיין די וואָס וועלן פרעגן „מה פעל א-ל”.\nב) פאַרוואָס איז ער מקדים דעם ערשטן פירוש פאַר דעם צווייטן — אדרבא, דער צווייטער פירוש (טראָץ זיין שווערקייט אין לשון כנ\"ל) איז דאָך פאָרט נעענטער צו פשש\"מ 13 דערמיט וואָס דער צווייטער טייל פסוק קומט בהמשך צו התחלת הכתוב, משא\"כ לויטן ערשטן פירוש ?\nאון ווי מען געפינט טאַקע, אַז אין מדרש 14 שטייט דער צווייטער פירוש (פון רש\"י) פאַר דעם ערשטן; נאָך מער, דער רמב\"ן אויפן פסוק ברענגט פון רש\"י בלויז דעם צווייטן פירוש 15.\nג) פון רש\"י'ס לשון „ד\"א יאמר ליעקב אינו לשון עתיד אלא לשון הווה” איז מוכח, אַז „יאמר” קען געטייטשט ווערן (אויך) בלשון הווה, ווי רש\"י (שוין פריער) 16 איז דאָס מסביר וויבאַלד דאָס",[["8","8","רא\"ם, שפ\"ח, וראה גו\"א."],["9","9","ראה גם באר מים חיים ודבק טוב לפרש\"י."],["10","10","כג, כא."],["11","11","ראה רא\"ם ומשכיל לדוד עה\"פ."],["12","12","ראה משכיל לדוד שם."],["13","13","ראה רע\"ב כאן עה\"פ."],["14","14","תנחומא (פרשתנו יד) ובמדב\"ר (פ\"כ, כ). אלא שבפשטות — ב' מדרשים הנ\"ל אינם במחלוקת, כ\"א שמתחלה מפרש תחלת הכתוב „כי לא נחש ביעקב ולא קסם בישראל”, והפי' „ראתה עינו את ישראל יושבין לפני הקב\"ה כו'” הוא על המשך הכתוב „כעת יאמר ליעקב גו'”. אבל בפי' מהרז\"ו (למד\"ר שם) מפרש דראתה עינו את ישראל הוא ד\"א ופירוש אחר על הפסוק. וגם הפי' „הרי את מחזר כו' ונשאל בהקב\"ה” הוא על המשך הכתוב „כעת יאמר ליעקב”."],["15","15","ופי' הרמב\"ן עצמו הוא ג\"כ שמדבר בהווה ולא בעתיד."],["16","16","בשלח טו, א."]]],[1300181273,"איז „דבר ההווה תמיד” — „בכל עת”; און אויך דעם לשון „כעת” קען מען פאַרענטפערן לויטן צווייטן פשט — ווי מפרשים 17 טייטשן, אַז „כעת” מיינט: ווען עס קומט די צייט וואָס מ'דאַרף עפעס וויסן איז „נמסר להם ע\"פ נביאיהם וכו'”.\nג. לכאורה וואָלט מען געקענט פאַרענטפערן, אַז דער המשך צום התחלת הכתוב לויטן ערשטן פירוש איז ווי די גמרא 18 זאָגט „כל אדם שאינו מנחש מכניסין אותו במחיצה שאפילו מלאכי השרת אין יכולין ליכנס בתוכה שנאמר כי לא נחש ביעקב ולא קסם בישראל כעת 19 יאמר ליעקב ולישראל מה פעל א-ל” 20 —\nמ'קען אָבער ניט זאָגן, אַז דאָס איז די כוונה אין פירוש רש\"י וואָרום:\nא) אין רש\"י איז ניטאָ קיין רמז אפילו אַז דאָס וואָס „מחיצתן לפנים ממלאכי השרת” איז אַ תוצאה פון „לא נחש גו'”.\nב) לפ\"ז האָט עס ניט געדאַרפט זיין ערשט לעתיד לבא — „עוד עתיד להיות עת כעת הזאת”: וויבאַלד אַז „לא נחש ביעקב ולא קסם בישראל” איז בהווה (כפרש\"י), האָט אויך די תוצאה („יאמר ליעקב וגו'”), געדאַרפט זיין אין זעלבן זמן, און ווי ס'איז געווען בשעת מ\"ת אַז למדו עשרת הדברות מפי הקב\"ה 20*.\nג) וואָס איז דאָ נוגע און שייך דער ענין „שהן יושבין לפניו ולומדים תורה מפיו” 21 ?\nד. אויך דאַרף מען פאַרשטיין נאָך דיוקים אין פירוש רש\"י. ומהם:\nא) אין ערשטן פירוש — וואָס איז דער לשון „מלאכי השרת” — ניט מלאכים סתם ?\nב) „וזהו שנאמר והיו עיניך רואות את מוריך” — צי דען איז רש\"י'ס ענין בפירושו עה\"ת צו מסביר זיין פסוקים אין נ\"ך ?\nג) אין צווייטן פירוש 22 איז רש\"י מוסיף (נאָך „ומה פעל א-ל”) „ומה גזרותיו במרום” — וואָס פאַר אַ שייכות האָט עס דאָ ? נאָכמער: אין דעם המשך דערמאָנט ער נאָר „(אלא נמסר להם ע\"פ נביאיהם) מה היא גזירת המקום” און ניט „מה פעל א-ל”.\nה. דער ביאור בזה:\nבלק האָט „געדונגען” בלעמ'ען אויף — לכה נא ארה לי את העם הזה 23; און בשייכות דערמיט איז געווען דער ענטפער „וישא משלו” צום ערשטן מאָל, פאַרוואָס ער קען דאָס ניט טאָן — „מה אקוב גו'” — „כי מראש צורים אראנו",[["17","17","ראה שפ\"ח עה\"פ."],["18","18","נדרים לב, א. ועד\"ז — ירושלמי שבת ספ\"ו (כגי' ופי' הקה\"ע ופ\"מ שם. וראה להלן שם בירוש'). וראה אוה\"ת עה\"פ. וש\"נ."],["19","19","כן הוא בע\"י (והתיבות כי לא נחש ביעקב וגו' הן בחצאי רבוע), וכ\"ה בפי' הר\"ן שם (ובירושלמי שם — רק סיום הכתוב). ובגמרא לפנינו לא הובא סיום הכתוב ורק עד „קסם בישראל וגו'”. אבל ראה פרש\"י וחדא\"ג שם."],["20","20","וראה ר\"ן שם. עיון יעקב לע\"י שם. מפרשים לירושלמי שם. ועוד. 20*) פרש\"י יתרו כ, א."],["21","21","גם: מהו הלשון „מה פעל א-ל” — דלכאורה מכיון שהמדובר בתורה הול\"ל „מה הורה א-ל”, כבמדרשים הנ\"ל, ועד\"ז בירושלמי שם."],["22","22","ב' הענינים דנביאים ואורים ותומים י\"ל שהם לנגד „נחש” ו„קוסם”. ובפרט כפי שמשמע מפרש\"י שופטים יח, יוד ש„נחש” שייך לפעולה משא\"כ „קוסם”. ולהעיר מפרש\"י שם, יד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300141078\" data-slug=\"likkutei-sichot\" data-id=\"1300141078\">לקו\"ש חי\"ד ע' 66</a> הערה 16."],["23","23","כב, ואו."]]],[1300181274,"וגו'” 24 — די אויסערגעוויינליכע מעלות פון אידן, ווי רש\"י איז זיי מפרט בפירושו אויף די פסוקים.\nועד\"ז ביים צווייטן מאָל „וישא משלו” הויבט ער אָן „לא איש א-ל ויכזב”, אַז מען קען ניט דורכפירן בלק'ס ווילן „להמיתם במדבר” 25, און ער איז ממשיך ווייטער אין די מעלות פון אידן וחיבתם אַז דער אויבערשטער פאַרקוקט די עבירות פון אידן, ואדרבה „תרועת מלך בו — לשון חיבה ורעות כו'” 26.\nאון אויף דעם איז ער דערנאָך מוסיף, אַז ניט נאָר איז ניט שייך ארה לי את העם, נאָר פונקט להיפוך — „כי לא נחש ביעקב” — „כי ראויים הם לברכה (מצד מעלתם) שאין בהם מנחשים וקוסמים” 27.\nוויבאַלד אָבער אַז דאָס וואָס „אין בהם מנחשים וקוסמים” בריינגט ברכה ווייזט אויף דער פחיתות פון בלעמ'ען (וואָס ענינו איז אַ קוסם<sup data-n=\"28\">28</sup> — דעריבער האָט בלעם ווייטער ממשיך געווען וועגן דער מעלה פון אידן און דערמיט מדגיש געווען, אַז די סיבה וואָס ער קען ניט ארה לי את העם איז ניט מצד זיין (בלעמ'ס) חסרון, נאָר מצד דער מעלה פון אידן וואָס ער האָט מרמז געווען אין „משלו” מיט די ווערטער „כעת יאמר ליעקב ולישראל מה פעל א-ל”.\nו. דער ביאור אין דעם: „כעת” (מיט אַ כ' קמוצה) ווייזט אויף אַ באַוואוסטער צייט 29 — און וויבאַלד דאָ רעדט זיך וועגן חיבת ישראל, איז מובן אַז ס'רעדט זיך וועגן אַ צייט ווען מ'האָט געזען די חיבה פון אויבערשטן צו אידן.\nאון דאָס ווייס אויך אַ בן חמש למקרא, אַז די צייט, ווען די חיבה פון אויבערשטן צו אידן איז געווען ניכר בגלוי, איז געווען אין זמן פון מ\"ת, אויף וועלכן ס'שטייט 30: „והייתם לי סגולה מכל העמים כי לי כל הארץ”, און ווי רש\"י פאַרטייטשט עס: „אוצר חביב כו' כך אתם תהיו לי סגולה משאר אומות ולא תאמרו אתם לבדכם שלי ואין לי אחרים עמכם ומה יש לי עוד שתהא חבתכם נכרת כי לי כל הארץ והם בעיני ולפני לכלום”.\nאון פון דעם וואָס מ'זאָגט „כעת יאמר ליעקב”, אַז דער „עת” דלעתיד וועט זיין גלייך צו דער עת הידועה, דער זמן פון מ\"ת — איז מובן, אַז פונקט ווי ביי מ\"ת האָבן אידן געלערנט תורה פון דעם אויבערשטן אַליין (די עשרת הדברות וואָס מ'האָט געהערט פון אויבערשטן), עד\"ז „עתיד להיות”, אַז מ'וועט לערנען „תורה מפיו”, פון דעם אויבערשטן 31.\nאון וויבאַלד אַז חיבה בגלוי דריקט זיך אויס אין פאַרגלייך צו אַנדערע, וואָס לגבי זיי איז „חיבתן נכרת” (כנ\"ל בפרש\"י), במילא איז מובן, אַז בשעת עס רעדט זיך וועגן לימוד התורה (וואָס אומות העולם האָבן דערצו בכלל קיין",[["24","24","כג, ח ואילך ובפרש\"י."],["25","25","שם, יט בפרש\"י."],["26","26","שם, כא ובפרש\"י."],["27","27","פרש\"י בתחלת הכתוב כאן (כג)."],["28","28","ראה פרש\"י כב, ז. יהושע יג, כב (הובא בפרש\"י כאן פסוק הבא (כג, כד)). וראה רד\"ק יהושע שם. פרש\"י מטות לא, ו. רמב\"ן שופטים יח, ט."],["29","29","ראה מירא דכיא בפרש\"י. ומ\"ש ברא\"ם שהוא כ\"ף הדמיון שמדמה זמן א' להשני — צ\"ע, שהרי נאמר בקמ\"ץ, והרא\"ם לשיטתו אזיל בפירושו לוירא יח, יוד. אבל ראה מירא דכיא שם. וגם בגו\"א עה\"פ כאן שכתב שהכ\"ף הוא כ\"ף הדמיון אינו מפרש כן מצד הדמיון דזמן א' להשני, אלא על הזמן שנאמר בהמשך הכתוב."],["30","30","יתרו יט, ה."],["31","31","להעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו</a>."]]],[1300181275,"שייכות ניט), מוז מען זאָגן אַז אין דעם איז דער גילוי החיבה אין פאַרגלייך לגבי „מלאכי השרת” 32, אפילו לגבי די מלאכים וואָס זייער ענין איז „לשרת” כביכול דעם אויבערשטן\n[ניט נאָר ווי די מלאכים שטייען אין אַ מצב וואָס זיי פירן אויס אַ שליחות (פון דעם אויבערשטן) למטה, ע\"ד ווי מ'האָט שוין געלערנט פריער וועגן די מלאכים וואָס זיינען געקומען צו אברהם דורכצופירן שליחות'ן 33 (א' לבשר את שרה ואחד להפוך את סדום ואחד לרפאות את אברהם שאין מלאך אחד עושה שתי שליחות), וע\"ד בא הגר 34 וכיו\"ב 35, נאָר ווי זיי זיינען משרת למעלה, כביכול, דעם אויבערשטן];\nד.ה. אַז אויך לגבי דעם ווי די מלאכים זיינען משרת וועט זיין ניכר די חיבה פון אידן 36, לערנענדיק תורה מפיו פון אויבערשטן — „והם ישאלו להם מה פעל א-ל” 37.\nעפ\"ז איז פאַרשטאַנדיק וואָס בהמשך צו דעם וואָס „ראויים הם לברכה” מטעם „כי לא נחש ביעקב” האָט בלעם מוסיף געווען און באַוואָרענט, אַז דאָס וואָס ס'קען ניט שולט זיין אַ קללה אויף די אידן איז ניט ווייל ער איז (אַ פחות) אַ מנחש וקוסם און זיי זיינען „לא נחש”, נאָר מצד דעם עצם מעלה פון אידן, וואָס עס וועט נתגלה ווערן חיבתם אַז „מחיצתן לפנים ממלאכי השרת” 38.\nז. עס ווערט אָבער די שאלה:\nא) מ'געפינט דאָך ביי מ\"ת אַז אידן האָבן געזאָגט צו משה'ן „דבר אתה עמנו ונשמעה ואל ידבר עמנו אלקים פן נמות”, און אַזוי איז טאַקע געווען „ויעמוד העם מרחוק” 39 איז ווי קען זיין כעת אַז אידן וועלן לערנען „תורה מפיו” של הקב\"ה ?\nב) און אויב אפילו יע, אַז עס וועט זיין נאָכאַמאָל אַן עת ווי באַ מ\"ת — איז פאַרוואָס איז עס שולל דעם „ארה לי” מער ווי דער עת פון מ\"ת ?\nדעריבער ברענגט רש\"י: א) „וזהו שנאמר 40 והיו עיניך רואות את מוריך” — עס איז מפורש נאמר אין פסוק אַז דער אויבערשטער וועט זיין „מוריך” פון אידן, און אין אַן אופן פון „והיו עיניך רואות” 41; ב) „שהן יושבין לפניו”,",[["32","32","הלשון „מלאכי השרת” הובא גם בפרש\"י וירא יח, ט. תולדות כז, א. יתרו ח, טו. תשא לג, ז. ר\"פ ויקרא. ועוד."],["33","33","וירא יח, ב."],["34","34","לך טז, ז ואילך."],["35","35","„מלאך ה' בדרך לשטן” — לבלעם — דפרשתנו כב, כב ואילך. מלאכים ממש דר\"פ וישלח. ועוד."],["36","36","עפמ\"ש בפרש\"י תשא שם „והי' כל מבקש ה' אפילו מלאכי השרת כשהיו שואלים מקום שכינה כו' אומרים להם הרי הוא באהלו של משה” — יומתק הלשון בפרש\"י „כעת הזאת”, שלא קאי רק על זמן מ\"ת אלא על כל זמן היות ישראל במדבר, ו„עוד עתיד להיות עת כעת הזאת אשר תגלה חבתן לעין כל”, שגם אוה\"ע ידעו ויבינו חבתן זו."],["37","37","לכאורה יש להקשות למה נאמר בכתוב „כעת יאמר” ולא ישאלו (כבפרש\"י) וכיו\"ב ? וי\"ל שגם מזה הכרח להפירוש שכל הכתובים האלה מדברים במעלתם של ישראל (ראה בפנים סי\"א) — כי לשון „יאמר” אינו מדגיש הפועל, המדבר, כ\"א הנפעל: יאמר לישראל."],["38","38","ויש להוסיף בזה שאצל בלעם הי' מעלה מיוחדת בזה שבנ\"י „מחיצתן לפנים (אפילו) ממלאכי השרת” — ע\"פ פרש\"י ר\"פ ויקרא „לשון שמלאכי השרת משתמשין בו. אבל לנביאי האומות (הם למטה ממלאכי השרת) כו' בלשון ארעי וטומאה שנאמר ויקר אלקים אל בלעם”."],["39","39","יתרו כ, טז. שם, יח."],["40","40","ונראה שצ\"ל כבדפוס א' וב' וכו\"כ כת\"י רש\"י „שנאמר” במקום „וזהו שנאמר”."],["41","41","ולכן הביא רש\"י רק פסוק זה ולא הפסוק הראשון שהובא במדרש וגם לא הכתוב (ישעי' מ, ה) „ונגלה כבוד ה' וראו כל בשר” — כי דוקא בפסוק זה מפורש שהקב\"ה יהי' „מוריך”."]]],[1300181276,"דאָס וועט ניט זיין אַן איינמאָליגע זאַך און לזמן קצר, נאָר אין אַן אופן פון „יושבין” — בקביעות 42, ווי רש\"י האָט שוין מפרש געווען 43 „אין תשב אלא לשון עכבה” 44.\nח. עס ווערט אָבער די שאלה: ווי־באַלד אַז סו\"ס איז דאָס אַן ענין וואָס וועט זיין לעתיד — איז ווי אַזוי טוט עס אויף, אַז צוליב דעם זאָל איצט ניט קענען זיין „ארה לי” ?\nדעריבער ברענגט רש\"י „ד\"א”, וואָס לויט דעם איז „יאמר ליעקב אינו לשון עתיד אלא לשון הווה כו' כי בכל עת שצריך להאמר ליעקב ולישראל מה פעל הקב\"ה כו' אינן מנחשים וקוסמים אלא נמסר להם ע\"פ נביאיהם כו'” —\nוואָס לפ\"ז איז דאָס אַן ענין שבהווה, ניט (נאָר) אַ זאַך וואָס וועט זיין לעתיד.\nלויטן צווייטן פירוש אָבער איז קשה, וואָס „כעת יאמר ליעקב ולישראל גו'” איז ניט מוסיף אויף דעם וואָס „ראויים הם לברכה” און אויף דעם וואָס בלעם קען ניט „ארה לי”, ער איז בלויז דער סיום והמשך הענין פון תחלת הכתוב „כי לא נחש ביעקב”, אַז דאָס וואָס זיי דאַרפן, ווייסן זיי ע\"י נביאיהם.\nועפ\"ז איז מובן וואָס רש\"י נעמט אָן דעם ערשטן פירוש אַלס פירוש העיקרי בפשש\"מ: וויבאַלד אַז דאָ רעדט זיך וועגן דברי בלעם אין וועלכע ער האָט געבענטשט אידן און גערעדט וועגן זייער מעלה, איז מובן, אַז דער פירוש אין זיינע רייד, וואָס ברענגט אַרויס מער די מעלה פון אידן, איז ער נעענטער צום פשט הכתובים.\nט. עס איז אָבער מסתבר צו זאָגן, אַז אויך לויטן צווייטן פירוש איז דער המשך פון דברי בלעם מוסיף אויף פריער אין דער הסברה פאַרוואָס עס קען ניט זיין „ארה לי”:\nבלעם האָט געוואוסט, אַז דער אויבערשטער וויל עס ניט; ער האָט אָבער געטראַכט אַז ער קען מכוון זיין די שעה „שהקב\"ה כועס” 45 און דעמאָלט וועט ער קענען „ארה לי”.\nאון דעריבער איז רש\"י מוסיף אין צווייטן פירוש „ומה גזרותיו במרום” — „נמסר להם ע\"פ נביאיהם מה היא גזרת המקום” —\nאַז אויך לויטן צווייטן פירוש זיינען די ווערטער „כעת יאמר ליעקב ולישראל גו'” אַ הוספה אין שלילת הקללה ע\"י בלעם: וויבאַלד אַז אפילו אין דער „שעה” וואָס „כועס בה” ווייסן דערפון די אידן דורך נביאיהם ואורים ותומים און זיי נעמען אַראָפ די גזירה דורך תשובה כו' 46.",[["42","42","ועפ\"ז יובן גם הלשון „והם ישאלו להם מה פעל א-ל” ולא מה הורה וכיו\"ב כנ\"ל הערה 21 — כי מעלתם למעלה אינה מספיקה באמירת בלעם לבלק שמשו\"ז אא\"פ לקללם, כ\"א דוקא עי\"ז שמעלתם למעלה פועלת למטה, שלכן מלאכים ישאלו מה פעל הקב\"ה למטה. ולהעיר גם מפ\"מ לירושלמי שם (ד\"ה ואומרין להם)."],["43","43","תזריע יב, ד. ובפרש\"י פרשתנו כב, ח: וישבו „לשון עכבה”."],["44","44","ובפרט ש„יושבין לפניו” הוא לא רק יתור לשון (שהי' אפ\"ל „שהן לומדים תורה מפיו”) אלא שגם תמוה, דלכאורה „לפניו” צ\"ל „עומדים ולומדים תורה מפיו” של הקב\"ה (ולהעיר מבהעלותך ט, ח „עמדו ואשמעה”). ועכצ\"ל שהכוונה להדגיש שיהי' בקביעות כבפנים."],["45","45","ראה פרש\"י כג, ח."],["46","46","עפ\"ז יובן הלשון „נמסר להם ע\"פ נביאיהם כו'” — דלכאורה: השלילה דמנחש וקוסם היא, דהם שואלים לנביאים ואו\"ת, וא\"כ הול\"ל דשואלים לנביאיהם ואו\"ת — כי עפ\"ז מודגשת גם בזה מעלת ישראל (ע\"ד בפי' הא'), שאינם צריכים לשאול אלא"]]],[1300181277,"יוד. עפ\"ז י\"ל, אַז דער חילוק צווישן די צוויי פירושים איז אַ שקלא וטריא אין אַ שאלה כללית — און אויך בהלכה 47: וואָס איז גובר — אַ גרעסערע מעלה וואָס וועט זיין לעתיד, אָדער אַ קלענערע מעלה וועלכע איז דאָ שוין בהווה 48.\nלויטן ערשטן פירוש קומט אויס, אַז „כעת יאמר ליעקב ולישראל” מיינט אַז זיי זיינען „ראויים הם לברכה” און עס קען כלל ניט זיין אַ מקום לקללה צוליב זייער גרויסער מעלה וואָס „תגלה חיבתן לעין כל” און „מחיצתן לפנים ממלאכי השרת”, אָבער דאָס איז אַ מעלה וואָס „עתיד להיות”.\nדאַקעגן לויטן צווייטן פירוש, איז אדרבה, מעלתם איז ניט אַזוי גרויס, ס'איז דאָ אַן אָרט אַז המקום כועס און ס'איז שייך קללה, נאָר וויבאַלד אַז „נמסר להם ע\"פ נביאיהם מה היא גזרת המקום” פאַרהיטן זיי אַז עס זאָל בטל ווערן, ניט דורכגעפירט ווערן לפועל. אָבער לאידך איז דאָס אַ מעלה וואָס איז בכל עת — בהווה.\nועפ\"ז קומט אויס, לכאורה, אַז פון דעם סדר הפירושים אין רש\"י קען מען מכריע זיין דעתו ע\"ד הפשט, אַז אַ מעלה גדולה בעתיד, איז מכריע די קלענערע מעלה וואָס איז דאָ בהווה.\nאָבער באמת קען מען פון דעם פרש\"י עס ניט אָפלערנען, ווייל: א) רש\"י איז דאָך דאָס מפרש אין דברי בלעם, אַ נביא באַ או\"ה ע\"ד ווי נביאי ישראל 48* — איז דאָס וואָס „נמסר להם ע\"פ נביאיהם” ניט אַזאַ גרויסע מעלה ווי דאָס וואָס זיי לערנען „מפיו” של הקב\"ה. ב) ועיקר: לויט דעם ערשטן פירוש איז דאָס ניט נאָר אַ מעלה וואָס וועט זיין לעתיד, נאָר עס איז דאָ די מעלה אויך בהווה, און בעתיד וועט נאָך צוקומען „תגלה חיבתן לעין כל” — בעתיד וועט די חיבה און מעלה פון אידן נתגלה ווערן פאַר אַלעמען.\nובמילא איז פון דעם ניט קיין ראי' צו אַן ענין, וואו די מעלה וועט זיך ערשט אויפטאָן לעתיד אַז אויך זי איז מכריע דעם הווה.\nיא. ע\"פ כהנ\"ל זעט מען אַז דער תוכן העיקרי אין אַלע בלעמ'ס רייד איז — די אויסערגעוויינליכע מעלות פון אידן\nוואָס ער איז געווען מוכרח מדגיש זיין דאָס וכו\"כ פעמים — כדי פאַרענטפערן זיך פון די תביעות פון בלק'ן כו\"כ פעמים „ארה לי” „וקבנו לי” וכו'\nוואָס דערפאַר איז ע\"פ פשש\"מ און אויך ע\"ד הדרוש והרמז, „משלו” — פירוש הכתובים אַז עס רעדט זיך במעלתם של ישראל.\nאון דערפאַר באַוואָרנט רש\"י און וואונדערט זיך: בכו\"כ מקומות אין די אַלע פסוקים בפרשתנו 49 איז „כתרגומו”",[["","","שנמסר להם מה גזרותיו במרום בלי שאלה. ולכן מפריד רש\"י ואומר „או או\"ת מגידים להם”, ולא כללו „נמסר להם ע\"פ נביאיהם ואו\"ת” *, כי הגדת או\"ת הוא באופן דמענה לשאלה."],["47","47","ראה שדי חמד אסיפת דינים מע' יוהכ\"פ ס\"א ס\"ק י. וש\"נ. וראה גם כללים שם מע' ז' כלל ג."],["48","48","ראה בכ\"ז — <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161466\" data-slug=\"likkutei-sichot\" data-id=\"1300161466\">לקו\"ש חט\"ז ע' 453</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191412\" data-slug=\"likkutei-sichot\" data-id=\"1300191412\">חט\"ז ע' 398</a> ס\"ז ואילך. חי\"ט ע' 73 ואילך. ועוד. *) ברמב\"ן הביא מפרש\"י הלשון „נאמר להם כו'” וכ\"ה בדפוס א' וב' ובכו\"כ כת\"י רש\"י. וג\"כ מתאים להמבואר בפנים, שהרי לא כתב „אומרים להם” וכיו\"ב. 48*) רש\"י כב, ה."],["49","49","אולי י\"ל הטעם כי בלעם הרי הי' מפתור ארם (דברים כג, ה. אונקלוס בפרשתנו כב, ה)."]]],[1300181278,"„וכן תרגם אונקלוס” (אָדער עכ\"פ מיט נאָך אַ פירוש),\nמיט דעם אויסנאַם אין דעם פסוק (אויך לגבי די פסוקים שלאחריו) און די תמי' אַז „ואונקלס לא תרגם כן” (ניט ווי ביידע פירושים) — און קלייבט אויס דוקא פשוטו של מקרא ממש —\nואע\"פ אַז רש\"י האַלט אַנדערש, ווייל עס איז „משלו” (כנ\"ל) און אַלע פסוקים רעדן במעלתם של ישראל\nאינגאַנצן שולל זיין פירושו וויל רש\"י ניט — ובהסברה אַז „אונקלוס” וואָס דרכו איז פשש\"מ אפילו וואו רש\"י זאָגט „אין המקרא הזה אומר אלא דרשני” 50 וכיו\"ב — לא תרגם כן, לשיטתי' וואָס איז אויך שיטת רש\"י בשאר כתובי התורה.\nיב. איינע פון די הוראות וואָס מ'קען אַרויסלערנען פון הנ\"ל:\nניט נאָר איז דער גילוי שע\"י הנביאים אַ פעולה נמשכת בהווה, און עס איז אויך דאָ בכל זמן הוראות ברורות, וואָס גילה דבריו ע\"י עבדיו ראשי אלפי ישראל עיני העדה בכל דור ודור — נאָר אויך דאָס וואָס אידן לערנען תורה מפיו של הקב\"ה איז געווען ניט בלויז איין מאָל בזמן מ\"ת, אין מדבר, נאָר ס'איז אַזוי בכל עת, אַז ווען אַ איד לערנט תורה כדבעי — ווערט תען לשוני אמרתך 51 ער לערנט עס מפיו של הקב\"ה; עס איז נאָר וואָס יעצט איז דאָס בהעלם און לעתיד „תגלה חיבתן לעין כל”.\nובמילא איז פאַרשטאַנדיק, אַז ס'איז ניטאָ וואָס נתפעל צו ווערן פון די מלעיגים אויף לימוד התורה וקיום המצות, ובפרט אין הפצת התורה והיהדות, וויבאַלד ער האָט קלאָרע הוראות פון דעם וואָס גילה דבריו ע\"י עבדיו, און נאָכמער — ער לערנט מפיו של הקב\"ה און פשיטא אַז ער געפינט זיך צוזאַמען מיטן אויבערשטן — הקב\"ה קורא ושונה כנגדו 52, ביז אַז „מה להלן (בשעת מ\"ת) באימה וביראה וברתת ובזיע אף כאן” 53 אַזוי.\nאון וויבאַלד אַז ער איז „תמים תהי' עם ה' אלקיך” 54 — צוזאַמען מיטן אויבערשטן — איז ניטאָ וואָס נתפעל צו ווערן אויך פון דעם וואָס „רגשו גוים” און „לאומים יהגו” 55, ווייל ער ווייס אַז עס איז „ריק”; אפילו אַז דאָס קומט פון אַ מלך אָדער אַ שר (ווי בלק מלך מואב) אָדער פון איינעם פון די נביאי אוה\"ע, ע\"ד ווי בלעם, וואָרום אויך זיי ווייסן (ומזלייהו חזי — זעט עס) די מעלה נפלאה פון אידן אַז „מחיצתן לפנים (אפי') ממלאכי השרת”.\nביז אַז אַלע או\"ה מוזען מודה זיין אַז אידן זיינען „ראויים הם לברכה” ווייל „אין בהם מנחשים וקוסמים”, ד.ה. זיי רעכענען זיך כלל ניט מיט די חוקות והנהגות הגוים — אידן שטייען שטאַרק אין זייער אמונה אין תורה.\nאון דעמאָלט אָנשטאָט צו ח\"ו שטערן אידן — בענטשן זיי און זיי העלפן אידן אַז עס זאָל זיי גאָרניט פעלן, ואדרבא,",[["50","50","בראשית א, א."],["51","51","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381050\" data-slug=\"likkutei-torah\" data-id=\"4001381050\">לקו\"ת סוכות פא, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381305\" data-slug=\"likkutei-torah\" data-id=\"4001381305\">שה\"ש מד, ב</a>."],["52","52","יל\"ש איכה רמז תתרלד. תדבא\"ר רפי\"ח."],["53","53","ברכות כב, א."],["54","54","שופטים יח, יג (ובפרש\"י שם). והיא הקדמה להכתוב שלאח\"ז שם „הגוים גו' אל מעוננים ואל קוסמים וגו'”, ראה רמב\"ן שם. אבל ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300141076\" data-slug=\"likkutei-sichot\" data-id=\"1300141076\">לקו\"ש חי\"ד ע' 64</a> ואילך."],["55","55","תהלים ב, א."]]],[1300181279,"ובפרט אין זייער אַרויסגיין בקרוב ממש פון מדבר הגלות און אַריינגעין אין דער גאולה האמתית, אין ארץ הקודש (היפך כוונת בלק) 56,\nאון מען קומט צו דעם „תגלה חיבתן לעין כל”, והיו מלכים אומניך ושרותיהם מיניקותיך 57, ועמדו זרים ורעו צאנכם 58 אין דער גאולה האמתית והשלימה בקרוב ממש.\n(משיחת ש\"פ בלק תשל\"ז)",[["56","56","ראה פרש\"י כג, יט."],["57","57","ישעי' מט, כג."],["58","58","שם סא, ה."]]],[1300181280,"<h3>בלק ב</h3>\nא. אין סוף הל' מלכים 1, וואו עס רעדט זיך וועגן מלך המשיח, זאָגט דער רמב\"ם ז\"ל: „וכל מי שאינו מאמין בו או מי שאינו מחכה לביאתו לא בשאר נבי־אים בלבד הוא כופר אלא בתורה ובמשה רבינו שהרי התורה העידה עליו שנאמר 2 ושב ה\"א את שבותך כו'\". דער־נאָך איז ער ממשיך: „אף בפרשת בלעם נאמר ושם נבא בשני המשיחים במשיח הראשון שהוא דוד שהושיע את ישראל מיד צריהם, ובמשיח האחרון שעומד מבניו שמושיע את ישראל [באחרונה 3] ושם הוא אומר 4 אראנו ולא עתה זה דוד אשורנו ולא קרוב זה מלך המשיח. דרך כוכב מיעקב זה דוד. וקם שבט מישראל זה המלך 5 המשיח. ומחץ פאתי מואב זה דוד. וכן הוא אומר 6 ויך את מואב וימדדם בחבל. וקרקר כל בני שת זה המלך המשיח שנאמר 7 בו ומשלו מים עד ים. והי' אדום ירשה זה דוד 8. שנאמר 9 ותהי' אדום 10 לדוד לעבדים וגו' *10. והי' ירשה שעיר אויביו 11 זה המלך המשיח שנאמר 12 ועלו מושיעים בהר ציון וגו'\" *12.\nדער ס' היד איז דאָך אַ ספר פון הלכות — כדברי הרמב\"ם בהקדמתו בסופה — (ניט פון דרשות אויף פסוקי התורה וכיו\"ב), דאַרף מען פאַרשטיין: צו אַרויסברענגען די ראי' צו דער הלכה אַז „כל מי שאינו מאמין בו כו'\" איז ער „כופר בתורה ובמשה רבינו\", וואָלט גע־ווען גענוג ווען ער זאָגט בלויז „אף בפרשת בלעם 13 נאמר ושם נבא במשיח (האחרון שעומד מבניו) שמושיע את",[["1","1","פרק יא ה\"א."],["2","2","נצבים ל, ג."],["3","3","אבל בכת\"י הרמב\"ם ודפוסים שלא שלטה בהם בקורת הצנזור (רומי רמ. שונציא רנ. קושטא רסט. ווינציאה רפד. שי (— ברגדין). שיא (יושטיניאן)) „מיד בני עשו\". „נוסח מלא בלתי מצונזר של פרק זה (פי\"א מהל' מלכים) ע\"פ כת\"י ודפוסים ישנים בצירוף מבוא ושינויי נוסחאות\" נדפס בסוף הרמב\"ם דהוצאת פרדס (ירושלים). ושם גם צילומים מכמה כת\"י דפרק זה. לקמן בפנים ובהערות צויינו (בעיקר) השינויים הנוגעים לנדו\"ד."],["4","4","פרשתנו כד, יז־יח."],["5","5","כ\"ה בדפוסים וכמה כת\"י הנ\"ל (הערה 3)*. וי\"ל בפשטות השינוי דבענין הא' כתב „זה מלך המשיח\" ולאח\"ז (שכבר ידוע) כתב „זה המלך המשיח\" (ה\"א הידיעה (מלפני זה)). *) ובדפוסים שלפנינו גם ב„וקם שבט מישראל\" כתב „זה מלך המשיח\", ורק בב' ענינים האחרונים כתב „זה המלך המשיח\". ובב' כת\"י (אוקספורד 591. שטוקהולם — הובאו ברמב\"ם הנ\"ל הערה 3) בכל הלכה זו „זה מלך\". ולאידך, בב' כת\"י אחרים שם (אוקספורד 568, 610) גם באשורנו ולא קרוב כתב „זה המלך המשיח\"."],["6","6","ש\"ב ח, ב."],["7","7","זכרי' ט, י."],["8","8","בדפוסים ורוב כת\"י הנ\"ל (הערה 3). „לדוד\"."],["9","9","ש\"ב שם, ו."],["10","10","בכתוב „ארם\". ושם פסוק יד „ויהי כל אדום עבדים לדוד\". ועד\"ז בדה\"א יח, יג. ובכת\"י שטוקהאלם „עבדים לדוד\". ולפ\"ז כנראה הכוונה לפסוק יד. *10) ברוב כת\"י ליתא „וגו'\". וגם מזה משמע קצת שהכוונה לפסוק יד שבש\"ב שם, שהמשך הכתוב אין שייך לכאן. משא\"כ בפסוק ח שם שממשיך „נושאי המנחה\"."],["11","11","בדפוסים שלפנינו „והי' ירשה וגו'\". אבל כ\"ה בדפוסים וכת\"י הנ\"ל (הערה 3)."],["12","12","עובדי' א, כא. *12) ברוב הכת\"י הנ\"ל נעתק גם המשך הכתוב „לשפוט את הר עשו\", ובכת\"י (אוקספורד 610) נוסף גם „והיתה גו'\"."],["13","13","וכלשונו בפיה\"מ פרק חלק יסוד הי\"ב ומי שהסתפק בו כו' כפר בתורה שיעד בו בתורה בפירוש בפרשת בלעם ופרשת אתם נצבים (ועד\"ז הוא בתרגום הר\"י קאפאח)."]]],[1300181281,"ישראל [באחרונה]\", און מ'וואָלט שוין אַליין געוואוסט, אַז ער רעדט וועגן די פסוקים פון דער נבואה וואָס איר אָנ־הויב איז „ . . אשר יעשה העם הזה לעמך באחרית הימים\" 14 —\nפאַרוואָס איז ער מאריך אין די פרטי הראיות אַז אין די כתובים רעדט זיך וועגן „שני המשיחים\" און אויף וועמען יעדער חלק פון פסוק איז מרמז וכו'?\nאפילו אויב מען וויל אויסטייטשן בפירוש וועלכע פסוקים מען מיינט, וואָלט דאָך געווען גענוג ווען מען בריינגט נאָר (די התחלה וסיום) — אַז דאָס איז געזאָגט געוואָרן אין די פסוקים „אראנו ולא עתה וגו' והי' ירשה שעיר אויביו גו'\" 15.\nב. פון דעם וואָס דער רמב\"ם איז מוסיף די ראי' „אף בפרשת בלעם נאמר\", כאָטש ער האָט שוין פריער גע־בראַכט די ראי' אויף דעם עצם ענין „שהרי התורה העידה עליו שנאמר ושב ה\"א את שבותך\", איז משמע (און ווי ס'איז פאַרשטאַנדיק פון פשטות לשונו) אַז די פסוקים פון „פרשת בלעם\" בריינגט דער רמב\"ם בעיקר ניט (נאָר) אַלס ראי' אויף עצם ביאת המשיח, דעם אויסלייזן אידן פון גלות, נאָר (אויך) אַז „נבא בשני המשיחים במשיח הראשון שהוא דוד כו' ובמשיח האחרון שעומד מבניו\". וואָס דערפאַר איז ער מפרט ומפרש די פסוקים, ווי אַזוי עס איז מוכח אַז „נבא בשני המשיחים\".\nאָבער הא גופא צריך ביאור:\nבשלמא דאָס וואָס ער איז מוסיף די ראי' פון די פסוקים שבפרשת בלעם אויף דעם עצם הענין פון משיח'ן, י\"ל ווייל אין דעם פסוק „ושב ה\"א את שבותך\" שטייט ניט 16 אַז דאָס וועט זיין דורך משיח'ן 17, דעריבער ברענגט ער אויך אַ ראי' פון המפורש בתורה אַז נבא אויף מלך המשיח. אָבער וואָס איז נוגע צו די ראיות (מן התורה) אויף ביאת המשיח אַז „שם נבא\" ניט נאָר וועגן „משיח האחרון\", נאָר אויך וועגן דוד'ן, „משיח הראשון\"; ובפרט נאָך מיט אַן אריכות צו מפרש זיין אַלע פרטי הלשו־נות אין די פסוקים, וועלכע פון זיי מיינען דעם מלך דוד און וועלכע דעם מלך המשיח 18?",[["14","14","כד, יד."],["15","15","ראה אגרת תימן פ\"ג קרוב לסופו (מהדורת קאפח): כמו שהבטיחנו ה' בתורה באמרו אראנו ולא עתה אשורנו ולא קרוב וכו' והי' אדום ירשה."],["16","16","אבל להעיר שלשון הרמב\"ם הוא „העידה עליו\"."],["17","17","להעיר מפרש\"י סנהדרין (צט, א) ד\"ה „אין להם משיח לישראל, אלא הקב\"ה ימלוך בעצמו ויגאלם לבדו\". וראה שו\"ת חת\"ס יו\"ד בסופו (סי' שנו). ושם: והאומר כדעת רבי הלל (שאין משיח לישראל אלא הקב\"ה יגאלם) הרי הוא כופר בכלל התורה."],["18","18","ופשיטא שאין לומר שזהו המדרש* היחידי שמצא הרמב\"ם שמפרש הכתובים האלו על מלך המשיח, ולכן הביאו כצורתו (חצי הכתוב הראשון על דוד וכו') — כי א) פשוט שאעפ\"כ אין דרך הרמב\"ם להעתיק כל פרטי הדברים שבמדרש, כ\"א זה שנוגע לנדו\"ד, ב) מצינו במדרשי חז\"ל שגם חלק הראשון „דרך כוכב מיעקב\" מפרשו במשיח (ראה ירושלמי תענית פ\"ד ה\"ה. דב\"ר פ\"א, כ. וראה ת\"א ותיב\"ע עה\"פ. ועד\"ז מפרש הרמב\"ן עה\"פ כל הכתובים על משיח. וראה דבריו בספר הגאולה (ע' רסו — בהוצאת שעוועל) מה שהשיג על הראב\"ע בפרשתנו שפירשו על דוד) — וראה לח\"מ לרמב\"ם שם: ואולי הם מדרשים חלוקים — ג) ועוד ועיקר: הרמב\"ם כאן אינו בא להביא ראיות ממדרשי חז\"ל „שכל הספרים מלאים בדבר זה\" (יותר מ„בדברי הנביאים\" — לשון הרמב\"ם שם ה\"ב), כ\"א מהמפורש בתורה ופשטות הכתובים. *) ע\"ד לשון הרמב\"ם הוא בבחי' פרשתנו עה\"פ „על דרך המדרש\". ועד\"ז הוא במדרש הגדול עה\"פ. וברמב\"ן בספר הגאולה שם (מבלי הראיות של הכתובים). ועד\"ז קצת במדרש אגדה (באבער) עה\"פ. וראה רלב\"ג עה\"פ."]]],[1300181282,"ג. לכאורה י\"ל, אַז דער טעם וואָס דער רמב\"ם בריינגט די ראי' אויף דעם אַז „נבא בשני המשיחים\", אויך וועגן „משיח הראשון שהוא דוד שהושיע את ישראל כו'\" — דלכאורה, וואָס איז נוגע צו דער אמונה אין ביאת המשיח אַז אויך דוד ווערט אָנגערופן משיח פונקט ווי מלך המשיח, ביז אַז אויף זיי ביידן זאָגט מען „בשני המשיחים\" (מיט אַ ה\"א הידיעה) —\nאיז ווייל דאָס איז נוגע ומחזק די אמונה אין ביאת המשיח: וויסנדיק אַז דער ענין פון „משיח\" איז ניט קיין נייע זאַך, ווייל ס'איז שוין געווען דער „משיח הראשון שהוא דוד שהושיע את ישראל מיד צריהם\", גיט דאָס צו אַ תוקף אין דער אמונה אַז אויך לעתיד וועט קומען משיח שמושיע את ישראל\n(ע\"ד ווי די הוכחה פון חז\"ל 19 אויף תחיית המתים: „דלא הוו חיי דהוי חיי לא כ\"ש\");\nאָדער באופן אחר, ווי מפרשים 20 זיינען מסביר: וויבאַלד אַז „שני המשי־חים\" זיינען געזאָגט געוואָרן אין דער זעלבער נבואה, איז פונקט ווי עס איז מקויים דער חלק הנבואה בנוגע דעם „משיח הראשון שהוא דוד שהושיע את ישראל מיד צריהם\"; אַזוי וועט זיכער מקויים ווערן די נבואה וועגן משיח „האחרון שעומד מבניו שמושיע את ישראל [באחרונה]\".\nעס איז אָבער מובן, אַז ס'איז שווער צו לערנען אַז דאָס איז דער גאַנצער טעם: וואָרום מיט די פסוקים איז דער רמב\"ם (כפשטות לשונו) ניט אויסן צו ברענגען אַ ראי' און הוכחה אַז מלך המשיח וועט זיכער קומען, נאָר אַז זיין קומען איז אַ זאַך וואָס שטייט אין דער תורה; ומזה, אַז דער וואָס „אינו מאמין בו או מי שאינו מחכה לביאתו\" איז „לא בשאר נביאים בלבד הוא כופר אלא בתורה ובמשה רבינו\" —\nהיינט וואָס איז דאָ נוגע אַז „נבא בשני המשיחים\", אויך „במשיח הראשון שהוא דוד\", ובפרט נאָך צו מפרש זיין די (פיר) דאָפּעלטע לשונות פון די פסוקים, אַז מיט די ערשטע ווערט געמיינט דער משיח ראשון און די צווייטע — משיח האחרון?\nד. בהמשך לזה זאָגט דער רמב\"ם, אָבער אין אַ באַזונדער הלכה: „אף בערי מקלט הוא אומר 21 אם ירחיב ה' אלקיך את גבולך ויספת לך עוד שלש ערים וגו' ומעולם לא הי' דבר זה ולא צוה הקב\"ה לתוהו\".\nס'איז ידוע אַז אויך די חלוקת ההלכות אין רמב\"ם איז בדיוק — דאַרף מען פאַרשטיין: פאַרוואָס בריינגט דער רמב\"ם די ראי' אין אַ הלכה בפ\"ע און ניט אין דער פריערדיקער הלכה צו־זאַמען מיט די אַנדערע צוויי ראיות מן התורה? און אויב ס'איז מתאים אַז יעדע ראי' זאָל שטיין אין אַ באַזונדער הלכה, האָט ער אויך די ראי' פון פרשת בלעם געדאַרפט זאָגן אין אַ באַזונדער הלכה *21.\nאויך: פאַרוואָס איז ער מדייק צו מציין זיין דעם מקור פון פסוק, און בפרט מיטן לשון „אף בערי מקלט הוא אומר\" און ניט „(אף) בפרשת שופטים\" 22, ע\"ד ווי ער זאָגט פריער „בפרשת בלעם\"?",[["19","19","סנהדרין צא, א."],["20","20","קרית ספר לרמב\"ם הל' מלכים שם. — ע\"ד סיום מס' מכות."],["21","21","שופטים יט, ח־ט. *21) וראה לקו\"ש שנסמן לקמן הערה 67. לקו\"ש חל\"ד ע' 114 ואילך."],["22","22","שהרי בנוגע לערי מקלט ישנה עוד פרשה לפנ\"ז (מסעי לה, ט ואילך. וראה גם פ' ואתחנן ד, מא ואילך), שמהלשון „בערי מקלט נאמר\" אינו ברור מקומו בתורה (גם אם הי' נאמר „בפרשת ערי מקלט\")."]]],[1300181283,"ה. אויך דאַרפ'ן פאַרשטיין דעם דיוק הלשון 23 „בשני המשיחים\" וואָס איז דאָס נוגע דאָ און וואָס איז דוקא (נאָר) דוד אָנגערופן „משיח\"?\n[וואָרום כשם ווי דוד איז נמשח גע־וואָרן בשמן המשחה (בקרן<sup data-n=\"24\">24</sup> און ווערט אָנגערופן משיח ה' 25, אַזוי אויך, לפנ\"ז, איז שאול נמשח געוואָרן 26 (בפך<sup data-n=\"24\">24</sup> און אויך ער ווערט אָנגערופן „משיח ה'\" 27]\nאויב אויסטיילן צוויי מושיעי ישראל (בראשונה ובאחרונה), וואָלט לכאורה מער מתאים געווען משה רבינו אַלס גואל ראשון און משיח אַלס גואל אחרון 28.\nביידע האָבן מושיע געווען מגלות, משא\"כ — דוד.\nולהעיר אַז אויך בנוגע מדריגתם בנבואה זאָגט דער רמב\"ם אַז משיח איז גדול מכל הנביאים 29 אָדער ווי ער זאָגט",[["23","23","עוד יש לדייק בלשון הרמב\"ם: א) „בפרשת בלעם\", והרי אין דרכו לציין המקור, וכמו שלא כתב בהפסוק שהקדים ושב ה\"א, „שהרי נאמר בפרשת אתם נצבים\", ב) הלשון „ושם נבא\" למאי נפק\"מ (ודוחק גדול לומר, כיון שמקדים „פרשת בלעם\" צריך לבאר ד„שם נבא\"). לכאורה י\"ל שהוסיף „ושם נבא\"*, בהתאם למש\"כ לפנ\"ז „כופר . . בתורה ובמשה רבינו\", ע\"ז ש„כופר . . בתורה\" כ' „שהרי התורה העידה עליו כו'\", וע\"ז שכופר „במשה רבינו\" כ' „אף בפרשת בלעם נאמר ושם נבא\" (ולא „ואף בלעם נבא\" (כבקרית ספר לרמב\"ם שם)) וכוונתו לנבואת משה (וכן משמע בפיה\"מ אבות (פ\"ד מ\"ד) „וכן דוד כו' ושיעדו הש\"י לנו ע\"י משה רבינו והוא הכוכב אשר דרך מיעקב כמו שביארו רז\"ל\". ולהעיר משל\"ה (פרשתנו שסב, ב) בפי' הגמ' (ב\"ב יד, ב) „משה כתב ספרו ופרשת בלעם\". ולהעיר משו\"ת חת\"ס יו\"ד שם), היינו שכופר בתורה ובנבואת משה (ונק' אפיקורוס וכופר) אף שגם תורה היא בכלל נבואת משה** (ראה רמב\"ם הל' תשובה פ\"ג ה\"ח***). ועפ\"ז יתורץ לכאו' ג\"ז שהביא הראי' מערי מקלט בהלכה בפ\"ע, כי זוהי ראי' נוספת מסברא „ומעולם לא הי' דבר זה ולא צוה הקב\"ה לתוהו\", ואינו שייך ל„כופר . . בתורה ובמשה רבינו\". וגם מובן מה שכתב „בערי מקלט הוא אומר\" ולא „בפרשת שופטים נאמר\" וכיו\"ב, להדגיש שא\"ז שייך לכופר בתורה כו'. אבל מובן שג\"ז דוחק ואכ\"מ. וראה לקמן בפנים סי\"א. *) לכאורה י\"ל באו\"א (ועפ\"ז מובן הצורך להוסיף ראי' זו „אף בפרשת בלעם\" על מש\"כ לפנ\"ז „שהרי התורה העידה עליו\" — דפ' נצבים), שבזה מוכיח שמוכרח להתקיים, כי ההבטחה של תורה יתכן שלא תתקיים שמא יגרום החטא (ברכות ד, א) משא\"כ בנבואה שהנבואה לטובה אפילו על תנאי אינו חוזר (רמב\"ם הל' יסוה\"ת פ\"י ה\"ד) — ראה גו\"א וישלח לב, ח (ובגבורת ה' פ\"ז). אבל נוסף ע\"ז שכבר נת\"ל (בפנים ס\"ג) שהרמב\"ם כאן לא בא להוכיח אמיתת הענין שבודאי יהי', כ\"א איך שהוא כופר בתורה ובמשה רבינו, וא\"כ אין נוגע הענין דנבואה — הרי החילוק בין ההבטחה דאפשר שתתבטל שמא יגרום החטא לנבואה לטובה כו', מפרש הרמב\"ם בהקדמתו לפיה\"מ שהיינו החילוק במה שבין ה' לנביא עצמו (שבזה אפ\"ל שיגרום החטא) לזה שיאמר ה' להבטיח לבנ\"א טובה בסתם, שבזה א\"א שלא תתקיים ההבטחה, וא\"כ מובן שג\"ז „שהתורה העידה עליו\" בודאי תתקיים. ועצ\"ע. — וראה לקו\"ש חל\"ד ע' 116־7 ובהערות שם. **) ראה פיה\"מ פ' חלק יסוד השביעי ויסוד השמיני. ולהעיר מלשון הרמב\"ם הל' יסוה\"ת פ\"ח ה\"ג. שם פ\"ט סה\"א. ה\"ד. ה\"ה. נתבאר בארוכה בלקו\"ש חי\"ט <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191190\" data-slug=\"likkutei-sichot\" data-id=\"1300191190\">ע' 177</a> ואילך. ***) ברמב\"ם שם: „האומר שאין תורה מעם ה' כו' אם אמר משה אמרו מפי עצמו הרי זה כופר בתורה\", אף שבזה גם מכחיש נבואתו של משה רבינו, שזהו א' מהשלשה הנק' אפיקורסין (שברמב\"ם לפנ\"ז), ומשמע שתלוי במה בא להכחיש, אף שהכופר בתורה בדרך ממילא מכחיש נבואתו של משה, לא נקרא עי\"ז אפיקורוס. ועצ\"ע."],["24","24","מגילה יד, א."],["25","25","ש\"ב יט, כב. וראה שם כג, א."],["26","26","ש\"א יוד, א. וכ' זה הביא הרמב\"ם (הל' מלכים פ\"א ה\"ז) לענין משיחת מלך. וראה מגילה שם."],["27","27","ש\"א כד, ז. יא. כו, ט. יא. טז. ש\"ב א, יד. טז."],["28","28","להעיר משמו\"ר פ\"ב, ד. זח\"א רנג, א. שער הפסוקים פ' ויחי."],["29","29","באגרת תימן רפ\"ד (תרגום הר\"י קאפח): שהמשיח נביא גדול מאד גדול מכל הנביאים אחרי משה רבינו . . מעלתו הרי היא הרמה בדרגות הנביאים והנכבדת אחרי משה רבינו."]]],[1300181284,"אין ספר היד 30 „ונביא גדול הוא קרוב למשה רבינו\" משא\"כ — דוד 31.\nו. וועט מען דאָס פאַרשטיין דורך מסביר זיין כמה דיוקים אין די צוויי ווייטערדיקע הלכות אין הל' מלכים דאָרט. אין הלכה ג' זאָגט דער רמב\"ם: ואל יעלה על דעתך שהמלך המשיח צריך לעשות אותות ומופתים ומחדש דברים בעולם או מחי' מתים וכיוצא בדברים אלו 32 אין הדבר כך שהרי רבי עקיבא כו' (ווי ער ברענגט דאָרטן די ראי' פון בן כוזיבא, און פירט אויס) ולא שאלו ממנו חכמים לא אות ולא מופת ועיקר הדברים ככה הן שהתורה הזאת חוקי' ומשפטי' *32 לעולם ולעולמי עול־מים ואין מוסיפין עליהן ולא גורעין מהן [וכל 33 המוסיף או גורע או שגילה פנים בתורה והוציא הדברים של מצותן מפשוטן, הרי זה ודאי בדאי ורשע ואפי־קורוס].\nפון דעם וואָס אין המשך ההלכה וועגן מלך המשיח איז דער רמב\"ם מסיים „ועיקר . . שהתורה הזאת חוקי' ומשפטי' לעולם כו'\" איז לכאורה משמע, אַז ווען איינער זאָגט אַז משיח וועט דאַרפן מאַכן „אותות או מופתים\" אָדער „מחדש (זיין) דברים בעולם\" איז ער דערמיט מוסיף או גורע בתורה, היפך הענין אַז אין מוסיפין עליהן כו'. מ'דאַרף אָבער פאַרשטיין: וואָס איז דער קשר פון די ביידע ענינים 34?\nנאָכמער: בנוגע אַ נביא זאָגט דער רמב\"ם 35 אַז „כל נביא שיעמוד לנו ויאמר שה' שלחו אינו צריך לעשות אות כאחד מאותות משה רבינו או כאותות אליהו ואלישע שיש בהם שינוי מנהגו של עולם אלא האות שלו שיאמר דברים העתידים להיות בעולם ויאמנו דבריו שנאמר כו'\". זעט מען אַז כאָטש אויך דאָרטן איז ער שולל אַן „אות . . שיש בהם שינוי מנהגו של עולם\", פונדעסט־וועגן פירט ער דאָרטן ניט אויס (ווי בנדו\"ד) „שהתורה הזאת חוקי' ומשפטי' לעולם\"; ולאידך זאָגט ער דאָרט אַז ער דאַרף ווייזן אַן אות: „שיאמר דברים העתידים\".",[["30","30","הל' תשובה פ\"ט ה\"ב."],["31","31","ראה מגילה שם ברש\"י שהוא נביא וכן סוטה מח, רע\"ב. וקשה מזח\"ב קנד, א (וראה ניצוצי זוהר שם). וראה ש' רוה\"ק בתחלתו. ובכ\"מ דדוד ושלמה (תהלים ומשלי — כתובים — דלא כסוטה שם) — מל' רוה\"ק ולא נבואה נ\"ה. ואכ\"מ. במו\"נ ח\"ב פמ\"ה (המעלה השני') כתב: דוד ושלמה ודניאל הם מן הסוג הזה ואינם מסוג ישעי' וירמי' . . ודומיהם לפי שאלו . . לא דברו . . כ\"א ברוה\"ק. בפיה\"מ אבות (פ\"ד מ\"ד) „וכן בדוד כו' והוא נביא\" (ולהעיר דשם בא בהמשך „ויש לך ללמוד ממשה רבינו כו'\"), אבל בפשטות משם אין ראי' כי אינו מדבר במדרי' ומעלות הנבואה, כ\"א ע\"ד ענוה כו' ואינו נוגע החילוקי מדריגות דנבואה ורוה\"ק. בשמונה פרקים (פ\"ז): וכן דוד המלך ע\"ה נביא אמר כו'. ושם בא לבאר מארז\"ל „אין הנבואה* שורה אלא על חכם גבור ועשיר . . ואין מתנאי הנביא שיהיו אצלו כל המעלות\" ומביא דוגמא משלמה ודוד, אליהו שמואל יעקב."],["32","32","בדפוסי וכת\"י רמב\"ם הנ\"ל (הערה 3) „שהטפשים אומרים\". *32) בכמה כת\"י (הובאו ברמב\"ם הנ\"ל הערה 3): אין חוקי' ומשפטי' משתנים (משתנות). *) כ\"ה בפיה\"מ שלפנינו ובתרגום הר\"י קאפח. בגמ' שבת (צב, א) „אין השכינה שורה\". ובנדרים (לח, א) „אין הקב\"ה משרה שכינתו\"."],["33","33","כ\"ה בדפוסים וכת\"י הנ\"ל (הערה 3) ונשמט בדפוסים שלפנינו."],["34","34","סיום הלשון שבהלכה שנשמט ע\"י הצנזור וכל המוסיף כו' רשע ואפיקורס — כנראה הכוונה לאותו האיש. ועפ\"ז מובן המשך הלשון בהלכה שלאחרי' ראה בהנסמן בהערה 36. אבל לפ\"ז — למה הוצרך לומר גם „ועיקר הדברים . . שהתורה כו' מהן\"."],["35","35","הל' יסודי התורה רפ\"י."]]],[1300181285,"ז. אין דער הלכה שלאח\"ז אין הל' מלכים איז דער רמב\"ם ממשיך: ואם 36 יעמוד מלך מבית דוד הוגה בתורה ועוסק במצות כדוד אביו כפי תורה שבכתב ושבעל פה ויכוף כל ישראל לילך בה ולחזק בדקה וילחם מלחמות ה' הרי זה בחזקת שהוא משיח אם עשה והצליח (ונצח כל האומות שסביבין<sup data-n=\"33\">33</sup> ובנה מקדש במקומו וקבץ נדחי ישראל הרי זה משיח בודאי ויתקן 37 את העולם כו'.\nדאַרף מען פאַרשטיין: פאַרוואָס דערמאָנט ניט דער רמב\"ם דאָ (און אויך ניט אין דעם גאַנצן פרק) די מעלות הגדולות מיט וועלכע מ'איז מתאר דעם מלך המשיח 29, און ווי דער רמב\"ם אַליין זאָגט במקום אחר אין ספר היד 30: „בעל חכמה יהי' יותר משלמה ונביא גדול הוא קרוב למשה רבינו\" (וכנ\"ל סוס\"ה).\nח. דער ביאור בכל זה יש לומר, בהקדים וואָס דער רמב\"ם האָט אַריינ־געשטעלט הל' מלכים (ומלחמותיהם 38, או ומלחמות *<sup data-n=\"38\">38</sup> בסיום וסוף ספרו היד\n— דלכאורה, לפי סדר הזמנים, ווי דער רמב\"ם זאָגט אין אָנהויב פון הל' מלכים „שלש מצות נצטוו ישראל בשעת כניסתן לארץ למנות להם מלך כו' ולהכרית זרעו של עמלק כו' ולבנות בית הבחירה\" — האָט ער די הלכות מלכים געדאַרפט שטעלן בספרו אַ סך פריער 39?\nוי\"ל, מיט דעם וואָס דער רמב\"ם שטעלט דאָס אין סיום ספרו היד — דער ספר פון „הלכות\" — איז ער דער־מיט מדגיש אַז די שלמות פון (קיום ה)תורה וההלכה ווערט בשעת עס איז דאָ (דער ענין ה)מלכים 40. און ווי דאָס",[["36","36","ביאור הלכה זו ברמב\"ם — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081369\" data-slug=\"likkutei-sichot\" data-id=\"1300081369\">לקו\"ש ח\"ח ע' 358</a>, 361־2 בהערות."],["37","37","כ\"ה בדפוסים שלפנינו. אבל בכת\"י ודפוסים הנ\"ל (בהערה 3) בא כאן קטע שנשמט „ואם לא הצליח כו'\", והתיבות „ויתקן את העולם כו'\" הן באמצע דבריו שם, „וכל הדברים האלו (של ישוע הנוצרי) ושל זה הישמעאלי . . אינן אלא ליישר דרך למלך המשיח ולתקן את העולם כולו כו'\". וראה שם בסיום לשונו. וראה לקמן בפנים סעיף טז."],["38","38","זהו השם המלא — בבהקדמת הרמב\"ם (ב„מנין המצות על סדר הלכות הרמב\"ם\") ובהכותרת בספר שופטים והל' מלכים. *38) כ\"ה בדפוס רומי הנ\"ל. ווינציאה רפד. שי. בהכותרת דספר שופטים והל' מלכים*. ובכת\"י התימנים שם. וכן הוא שם (ובכמה כת\"י) בהקדמת הרמב\"ם בסופה בההלכות דספר שופטים והלכות מלכים — ראה רמב\"ם ספר המדע (ירושלים תשכ\"ד). וש\"נ. *) אבל בהקדמת הרמב\"ם בסופה (בסידור ההלכות דספר שופטים וכן בהלכות מלכים) בכל דפוסים הנ\"ל „ומלחמותיהם\" („ומלחמותיהן\")."],["39","39","בהקדמת הרדב\"ז לספר שופטים „לפי שדיניו הלכתא למשיחא\". אבל צ\"ע, כי: א) כמה הלכות לכאורה אינן הלכתא למשיחא (ראה לדוגמא: פ\"א ה\"ח ואילך שלכאו' אינן שייכות לאחרי ביאת המשיח) ב) מטעם זה גם ספר הח' והט' (ספר עבודה וקרבנות) היו צ\"ל ב(קירוב עכ\"פ ל)סיום ספרו. [ובנוגע לקרבנות הי' אפ\"ל בדוחק, כי לדעת הרמב\"ם (הל' ביהב\"ח פ\"ו הט\"ו. וראה שם פ\"ב ה\"ד) „מקריבין הקרבנות כולן אע\"פ שאין שם בית בנוי\". אבל בנוגע לביהמ\"ק וכל השייך לזה אין לתרץ כן (ע\"פ ב\"ר ספס\"ד. ראה מנ\"ח מצוה צה), כי הרמב\"ם כתב בהל' מלכים כאן (בריש הפרק ובסופו) דמשיח בונה מקדש (וראה הקדמתו לפיה\"מ בנוגע למס' מדות. הל' ביהב\"ח פ\"א ה\"ד). וידועה השקו\"ט בזה. ואכ\"מ]. ואולי י\"ל: הרמב\"ם בתחלת ספר היד (ב„מנין המצות על סדר הלכות הרמב\"ם\") כתב „ספר ארבעה עשר: אכלול בו מצות שהם מסורין לסנהדרין כו' ודין המלך ומלחמותיו\", ומכיון שהל' מלכים הן „דין המלך כו'\" — מצות היחיד, לכן כתבו בסוף ספרו (אף שכמה הלכות שייכות לכ\"א מישראל (ראה הל' מלכים פ\"ה ה\"ז ואילך))."],["40","40","להעיר מסהמ\"צ להרמב\"ם מ\"ע קעג (בתרגום ר' שלמה אבן איוב (הובא בהוצאת הר\"ח העליר)): שצונו למנות עלינו מלך מישראל שיעמיד אמונתנו. (אבל ראה תרגומו (העליר) ובסהמ\"צ לפנינו והוצאת הר\"י קאפח). ובהל' מלכים ספ\"ד „ותהי' מגמתו ומחשבתו להרים דת האמת כו'\"."]]],[1300181286,"איז אויך פאַרשטאַנדיק בפשטות, אַז די שלימות הקיום פון אַלע מצות והלכות התורה איז בשעת ס'איז דאָ אַ מלך על כל ישראל, וואָס על ידו ווערט דורכ־געפירט די מצוה פון מלחמות השם 41 (להכרית זרעו של עמלק) און די מצוה „לבנות בית הבחירה\", וואָס נאָר דעמאָלט איז שייך דער קיום פון אַלע הלכות ומצות התורה.\nבפועל האָט זיך דאָס אויפגעטאָן ע\"י דוד המלך, וואָס ער איז געווען מלך 42 על כל ישראל (ישראל ויהודה). ער האָט כובש געווען א\"י, גמר ושלימות פון מלחמות (וה' הניח לו מסביב מכל אויביו<sup data-n=\"43\">43</sup>; ועל ידו האָט זיך אָנגע־פאַנגען (די הכנות 44 עכ\"פ פון) בנין ביהמ\"ק בירושלים (ויאמר דוד זה הוא בית ה' גו'<sup data-n=\"45\">45</sup>. ובמילא האָט געקענט זיין דער קיום התורה והמצוה בשלימות.\nט. די הלכות פון משיח'ן האָט דער רמב\"ם אַריינגעשטעלט (בסיום ספרו היד ו)בסוף הל' מלכים ומלחמותיהם *45, וואָרום דאָס איז גדרו וענינו של משיח ע\"פ הלכה:\nדער רמב\"ם איז מפרש אין פרק יא פון הלכות מלכים ניט בלויז די זאַך פון ביאת המשיח און דעם חיוב להאמין בו, נאָר אויך וואָס עס איז ענינו גדרו ופעולתו און אופן התגלותו, ובמילא — אין וואָס עס באַשטייט דער (חיוב) להאמין בו.\nאון דאָס מיינט דער רמב\"ם בתחלת הפרק: „המלך המשיח עתיד לעמוד ול־החזיר מלכות דוד 46 ליושנה לממשלה 47 הראשונה ובונה המקדש ומקבץ נדחי ישראל וחוזרין כל המשפטים בימיו כשהיו מקודם מקריבין קרבנות ועושין שמיטין ויובלות ככל מצותה 48 האמורה בתורה\":\nדאָס איז ניט (נאָר) אַ סיפור דברים וואָס משיח וועט טאָן, און וואָס ס'וועט זיין בימיו, נאָר דאָס איז אַ הלכה: דער גדר פון משיח'ן איז וואָס ער איז מחזיר „מלכות דוד ליושנה לממשלה הראשו־נה\" (ניט ער גייט אויפטאָן אַ נייַעם ענין), וואָס בפועל קומט דאָס אַרויס אין דעם וואָס „ובונה המקדש ומקבץ נדחי ישראל\" (ובמילא קומט מען צו דער מטרה און מכוון פון ביאת המשיח) „וחוזרין כל המשפטים בימיו כשהיו מקודם מקריבין קרבנות ועושין שמיטין ויובלות ככל מצותה האמורה בתורה\". וואָס דאָס איז פאַרבונדן מיט קבוץ נדחי ישראל ווען כל ישראל יושבים על אדמתם 49.",[["41","41","ראה רמב\"ם הל' מלכים פ\"א ה\"ח. ספ\"ד שם."],["42","42","ראה רמב\"ם שם פ\"א ה\"ז: כיון שנמשח דוד זכה בכתר מלכות והרי המלכות כו'. שם ה\"ט."],["43","43","ש\"ב ז, א. הובא ברמב\"ם ריש הל' מלכים ה\"ב."],["44","44","דה\"א כח־כט."],["45","45","שם כב, א. הביאו הרמב\"ם ריש הל' ביהב\"ח ה\"ג. וראה סוטה ט, סע\"א. וראה סמ\"ג מ\"ע קסג: זמן מצוה זו של בנין ביהב\"ח לא הגיעה עד ימי דוד. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161301\" data-slug=\"likkutei-sichot\" data-id=\"1300161301\">לקו\"ש חט\"ז ע' 301</a> ואילך. *45) להעיר דבהכותרת לפרקים יא ויב דהל' מלכים בדפוס וינציאה רפד. שי — „הלכות מלכים ומלחמות ומלך המשיח\"."],["46","46","כ\"ה בדפוסים שלפנינו. ובכת\"י ודפוסים הנ\"ל (בהערה 3) „בית דוד\"."],["47","47","בכת\"י הנ\"ל ודפוס רומי וקושטא הנ\"ל „הממשלה\". ושם ברמב\"ם הנ\"ל (הערה 3) מכת\"י: בממשלה, ממשלה."],["48","48","צ\"ע „מצותה\" — ל' יחיד. וברוב כת\"י ברמב\"ם הנ\"ל (הערה 3) „מצותן (מצותם) האמורות (האמורה)\"."],["49","49","ראה קרית ספר לרמב\"ם שם [ושם הביא הכתוב הנאמר ביובל, אבל מוכח מכאן דהרמב\"ם ס\"ל דגם שמיטין „ככל מצותה האמורה בתורה\" תלוי ב„מקבץ נדחי ישראל\". וראה רמב\"ם הל' שמיטה ויובל ספי\"ב. וכידועה השקו\"ט בזה. ואכ\"מ]. והנה לפ\"ז „מקריבין קרבנות ועושין שמיטין"]]],[1300181287,"ד. ה. די אַלע ענינים וואָס האָבן גע־פעלט אין קיום תומ\"צ מצד דעם וואָס עס האָט געפעלט אין שלימות כל ישראל וביהמ\"ק — וואָס דאָס איז כללות ענין הגלות — ווערט נשלם דורך משיח'ן. און אין דעם באַשטייט וואָס משיח איז מחזיר „מלכות דוד ליושנה כו' וחוזרין כל המשפטים\" — ער ברענגט צוריק די שלימות הלכות ומצות התורה.\n[וי\"ל אַז ס'איז אויך אַ נפק\"מ להלכה בפועל, לגבי דער אמונה בו (און אין וואָס עס דאַרף זיין דער מחכה לביאתו): וויבאַלד אַז דאָס איז דער גדר פון משיח'ן, דאַרף די אמונה זיין ניט בלויז אַז ער וועט קומען בכדי צו אויסלייזן די אידן פון גלות, נאָר „מאמין בו\" אַז ער איז מחזיר „מלכות דוד ליושנה . . וחוזרין כל המשפטים\"] 50.\nיו\"ד. אויף דעם ברענגט דער רמב\"ם די ראי', פון וואַנעט ווייס מען אַז משיח וועט קומען און בריינגען לשלימות התורה „להחזיר מלכות דוד ליושנה כו' וחוזרין כל המשפטים\" — „שהרי התורה העידה עליו\". וואָס אין די ראיות זיינען דאָ צוויי פרטים: שנאמר ושב ה\"א . . וקבצך גו' — פון דעם ווייס מען אַז עס וועט זיין קבוץ נדחי ישראל, וואָס דאָס איז דער מצב וואָס גיט די מעגלעכקייט אַז עס זאָל זיין „מלכות דוד . . כל המשפטים\" 51, דער קיום פון הלכות ומצות התורה וואָס איז בטל געוואָרן דורך גלות ישראל.\n„אף בפרשת בלעם נאמר ושם נבא בשני המשיחים במשיח הראשון שהוא דוד שהושיע את ישראל מיד צריהם ובמשיח האחרון שעומד מבניו שמושיע את ישראל (באחרונה)\": פון דעם ווייס מען אַז דאָס וואָס וועט זיין ע\"י משיח, און ענינו של משיח, איז „להחזיר מלכות דוד ליושנה לממשלה הראשונה\" — ער איז דער „משיח האחרון\" פון דעם הרא־",[["","","ויובלות\" הם תוצאה מב' הענינים שכ' לפנ\"ז: „ובונה המקדש (ובמילא „מקריבין קרבנות\") ומקבץ נדחי ישראל\" (ובמילא „עושין שמיטין ויובלות כו'\"). ואולי מש\"כ „חוזרים כל המשפטים בימיו כשהיו מקודם\" הוא מענין הא' שכתב „להחזיר מלכות דוד ליושנה לממשלה הראשונה\". אבל צ\"ע השייכות, שהרי לכאורה הכוונה ב„כל המשפטים\" היינו התלויים בסנהדרין* — ד' מיתות ועוד (ראה סנהדרין נא, ב. ובפרש\"י שם ד\"ה הלכתא) שחוזרין בביאת המשיח (ישעי' א, כו). אבל ראה רדב\"ז הל' סנהדרין פי\"ד הי\"ב „שהוא (משיח) יסמוך ב\"ד הגדול\"**. ולהעיר מרמב\"ם שם פ\"ב ה\"ה „מלכי בית דוד כו' יושבין ודנים הם את העם\". ולהעיר מקרית ספר הל' מלכים שם „ומחזיר כל המשפטים כמו שהיו קודם\". וראה לשון הרמב\"ם ספ\"ד שם: שאין ממליכין מלך תחילה אלא לעשות משפט כו' שנאמר ושפטנו מלכנו כו'. ואכ\"מ. *) להעיר שבא' מכת\"י (אוקספורד 591) שהובא ברמב\"ם הנ\"ל (הערה 3) „מקודם שהיו מקריבין\". ולפ\"ז הרי זה פירוש ל„וחוזרין כל המשפטים בימיו כשהיו מקודם (שהוא בזה ש)מקריבין קרבנות ועושין שמטין כו'\", ולא ענין בפ\"ע. ואולי כ\"ה הפירוש גם לפי הגירסא שבדפוסים ורוב הכת\"י „מקריבין קרבנות\" (בלי וא\"ו). ובב' כת\"י (ברמב\"ם הנ\"ל שם) „ומקריבין\" (בוא\"ו). וכ\"ה בקרית ספר שם. **) וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191105\" data-slug=\"likkutei-sichot\" data-id=\"1300191105\">לקו\"ש חי\"ט ע' 105</a> הערה 74, וש\"נ."],["50","50","ועפ\"ז יומתק מש\"כ הרמב\"ם בפיה\"מ פ' חלק בסוף עיקר הי\"ב „ומכלל יסוד זה (דביאת המשיח) שאין מלך לישראל אלא מבית דוד ומזרע שלמה בלבד וכל החולק על המשפחה הזאת כפר בשם הש\"י ובדברי נביאיו\", ובראש אמנה (לר\"י אברבנאל) פ\"א (שהעתיק הי\"ג עיקרים מ„העתקת הר' שמואל תיבון . . ראוי שנסמוך עלי' כו'\" כלשונו שם רפ\"א) הלשון „וכל החולק על מלכות זאת המשפחה\"."],["51","51","ראה שו\"ת חיים שאל ח\"א סי' צז: פירוש שיהי' מלך על כל ישראל ויהודה כמו שאמר הכתוב ומלך אחד יהי' לכולם . . וכל זה כלל הרמב\"ם באומרו מלכות בית דוד ליושנה."]]],[1300181288,"שונה — „משיח הראשון שהוא דוד\" 52.\nאון „ושם הוא אומר\" אַז די אַלע פרטים וואָס זיינען געווען „במשיח הראשון — דוד\" וועלן זיין אויך באַ „משיח האחרון\" זה מלך המשיח. אָנ־הויבנדיק פון תחלת התגלותו וממשלתו ביז צו דער שלימות „ומחץ פאתי מואב\" וואָס דוגמתו במשיח „וקרקר כל בני שת\", און „והי' אדום ירשה זה דוד\", „והי' ירשה שעיר אויביו זה המלך המשיח\",\nמשיח וועט ברענגען צו שלימות התורה, וואָרום דורך דעם וואָס מ'ווערט פטור פון שעבוד מלכיות ואדרבה, משיח איז אויף זיי שולט, וועט קענען זיין „לעסוק בתורה ובמצות כהוגן\" 53, „יהיו פנויין בתורה וחכמתה ולא יהי' להם נוגש ומבטל\" 54 (ווי דער רמב\"ם 55 איז מאריך בזה) 56.\nיא. עפ\"ז איז מובן וואָס דער רמב\"ם איז מקדים „וכל מי שאינו מאמין בו או מי שאינו מחכה לביאתו לא בשאר נביאים בלבד הוא כופר אלא בתורה ובמשה רבינו. שהרי התורה העידה עליו כו'\" (און אויף דעם ברענגט ער דעם פסוק „ושב ה\"א גו'\" און דערנאָך „אף בפרשת בלעם\"):\nדלכאורה וואָס איז נוגע כ\"כ אין רמב\"ם בשייכות צו הל' משיח אַז „לא בשאר נביאים בלבד הוא כופר אלא בתורה ובמשה רבינו\" 57 (דער ענין האָט לכאורה אַ שייכות אין הל' תשובה 58 וואו ער רעדט די גדרים פון כופר וכו'<sup data-n=\"59\">59</sup>?\nנאָר דערמיט איז דער רמב\"ם מדגיש, אַז דער ענין פון מלך המשיח, וואָס ער וועט ברענגען די שלימות אין הלכות ומצות התורה („להחזיר מלכות דוד ליושנה כו' וחוזרין כל המשפטים\") איז ניט נאָר אַ זאַך וואָס איז נתגלה גע־וואָרן ע\"י הנביאים, נאָר דאָס איז אַן",[["52","52","ולהעיר מסנהדרין (צח, סע\"ב): עתיד הקב\"ה להעמיד להם דוד אחר כו' כגון קיסר ופלגיי* קיסר. וראה זח\"א פב, ב. ז\"ח נג, א. וראה צפע\"נ עה\"ת ויחי מט, ט."],["53","53","רמב\"ם הל' תשובה פ\"ט ה\"ב."],["54","54","הל' מלכים פי\"ב ה\"ד."],["55","55","הל' תשובה והל' מלכים שם."],["56","56","שעפ\"ז מובן בפשטות מה שמגדרי ומצות המלך הוא שנלחם מלחמות ה' (כברמב\"ם שם פ\"א ה\"ח. ספ\"ד. ולהעיר שההלכות נקראו „הל' מלכים ומלחמותיהם\"*), וגם זה ש„אין המלך נלחם תחלה אלא מלחמת מצוה . . זו מלחמת שבעה עממים ומלחמת עמלק ועזרת ישראל מיד צר שבא עליהם\" (שם רפ\"ה), שענינים אלו דוקא מונעים את ישראל מקיום התומ\"צ. משא\"כ מלחמת הרשות. *) כ\"ה בגמ' וע\"י. ובערוך (ערך קסר): ופלגו. *) ראה לעיל הערה 38. ולהעיר שגם להדפוסים וכת\"י שבכ\"מ בהכותרת „ומלחמות\" (לעיל הערה *38), הרי בהקדמתו בסופה לפני שמפרט פרטי ההלכות בכל הדפוסים וכת\"י „ודין המלך ומלחמותיו\" (כנ\"ל הערה 39), או ומלחמותיה', ומלחמתו — ראה רמב\"ם הנ\"ל הערה *38."],["57","57","בפשטות י\"ל שהרמב\"ם בא להדגיש תוקף האמונה וגדרה, וג\"ז הוא הלכה, שהאמונה בביאת המשיח צ\"ל בודאות והתאמתות כזה (לא כהתאמתות שמצד „שאר הנביאים בלבד אלא\" התאמתות שמצד) תורה ומשה רבינו (שהרי התורה העידה עליו), ועפמ\"ש בהל' יסודי התורה פ\"ח. ועפ\"ז מובן גם מה שהוסיף „ובמשה רבינו\", כי נבואת משה נתאמתה „במעמד הר סיני (ע\"י) שעינינו ראו כו' ואזנינו שמעו\", והתאמתות בנבואת משה רבינו מביאה „נאמנות שהיא עומדת לעולם\" בתורה — ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191197\" data-slug=\"likkutei-sichot\" data-id=\"1300191197\">לקו\"ש חי\"ט ע' 184</a> ואילך. ועפ\"ז יומתק גם מש\"כ בשלילה „לא בשאר נביאים בלבד הוא כופר\", ולא כהלשון בקרית ספר לרמב\"ם שם „כופר בתורה ובמשה רבינו ובשאר הנביאים\", כי גם זה הוא הלכה — בגדר אמונה בביאת המשיח. ולהעיר מלשונו בסוף ה\"ב שחוזר ומוסיף „אבל בדברי הנביאים אין הדבר צריך ראי' שכל הספרים מלאים בדבר זה\"."],["58","58","ובפיה\"מ פ' חלק."],["59","59","פ\"ג ה\"ח."]]],[1300181289,"ענין פון תורה ומשה רבינו גופא, תורה גופא זאָגט און איז מבטיח אַז עס וועט קומען משיח און דאַן וועט זיין שלימות התורה 60.\nאון דעריבער פירט ער אויס „ואלו הדברים המפורשים בתורה הם כוללים כל הדברים שנאמרו על ידי כל הנבי־אים\", אַז אַלע ענינים שנאמרו על ידי כל הנביאים וועגן משיח'ן איז אַן ענין אין תורה גופא אין שלימות קיום התורה והמצות.\nיב. און דאָס איז אויך דער טעם וואָס די ראי' פון ערי מקלט האָט דער רמב\"ם געשטעלט אַלס אַ הלכה בפ\"ע, וואָרום פון דעם ברענגט דער רמב\"ם ניט נאָר אַ ראי' אַז ס'איז מפורש בתורה אַז ס'וועט זיין דורך מלך המשיח דער זמן פון שלימות אין קיום התומ\"צ, נאָר אַז מ'גע־פינט „בערי מקלט\" אַז ס'וועט צוקומען אין דער מצוה גופא, „ויספת לך עוד שלש ערים גו'\" „ולא צוה הקב\"ה לתוהו\".\nד. ה. אַז תורה גופא זאָגט אַז ס'דאַרף ערשט קומען אַ זמן ווען עס וועט זיין די מצות התורה כדבעי.\nיג. ע\"פ כל הנ\"ל איז מובן וואָס דער רמב\"ם זאָגט (אין הלכה ג) — „ואל יעלה על דעתך שהמלך המשיח צריך לעשות אותות ומופתים ומחדש דברים בעולם או מחי' מתים וכיוצא בדברים אלו, אין הדבר כך\" (וואָס דערמיט איז ער שולל צוויי ענינים: ניט דאָס איז פון עניני משיח „לעשות אותות ומופתים ומחדש דברים בעולם\" 61, און ניט דאָס\nאיז די בחינה אויף אמיתתו<sup data-n=\"62\">62</sup> און איז מסיים „ועיקר הדברים ככה הן שהתורה הזאת חוקי' ומשפטי' לעולם ולעולמי עולמים\":\nוויבאַלד שהנ\"ל גדרו וענינו של משיח — שלימות פון קיום הלכות ומצות התורה — איז אויב ס'איז עולה על הדעת „שהמלך המשיח צריך לעשות אותות ומופתים ומחדש דברים בעולם\" צו פועלן אַ שינוי אין וועלט, איז דאָס בסתירה צו דעם וואָס „התורה הזאת חוקי' ומשפטי' לעולם\" 63\nאון וויבאַלד אַז גדרו וענינו פון משיח'ן איז ניט אותות ומופתים וחידוש",[["60","60","ראה לקמן הערה 63."],["61","61","כדמשמע לכאורה מפשטות לשונו. אבל ראה הערה הבאה."],["62","62","כדמשמע לכאורה מהראי' מבן כוזיבא. וראה מאמר תחיית המתים רפ\"ז. בארוכה ביאור הלכה זו ברמב\"ם והשגת הראב\"ד בזה — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271205\" data-slug=\"likkutei-sichot\" data-id=\"1300271205\">לקו\"ש חכ\"ז ע' 191</a> ואילך."],["63","63","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191195\" data-slug=\"likkutei-sichot\" data-id=\"1300191195\">ע\"פ</a> כהנ\"ל יש לבאר מה שהרמב\"ם מנה ביאת המשיח לא' מהעיקרים (ראה ראש אמנה פ\"ג הספק החמישי. שו\"ת חת\"ס שם), שהוא לא רק „לפי שביאת המשיח באה מפורשת בתורה בנביאים ובכתובים כו' לכן הכופר בביאתו הרי הוא כאלו כופר בתורה ובנביאים ובכתובים כו'\" (ראש אמנה פי\"ד „והטענה השלישית\". וראה שו\"ת חת\"ס שם), כ\"א לפי שזה נוגע לשלימות גדר התורה, שא' מגדרי' הוא שיהי' זמן שהתורה וקיומה יהיו בשלימות. בסגנון אחר: נצחיות ושלימות התורה, זה ש„התורה הזאת חוקי' ומשפטי' לעולם ולעולמי עולמים\" (להיותה רצונו העצמי של הקב\"ה — ראה בארוכה לקו\"ש חי\"ט ע' 182־3 ובהערות שם) הוא לא רק בענין ציווי הבורא, כ\"א גם בלימודה וקיומה בפועל, וזה יהי' בביאת מלך המשיח. ועפ\"ז אולי י\"ל שזהו גם הטעם, שלא נמנה אמונה בביאת המשיח במנין המצות (ראה ראש אמנה שם פ\"ה הספק הג'). וע\"ד (ויתירה מזו) זה שציווים כוללים אינם נמנים במנין המצות (סהמ\"צ שורש ד). ולהעיר מלשון הרמב\"ם הל' מלכים שם „וכל מי שאינו מאמין בו כו'\", ולא כתב שצריך להאמין בו, כמ\"ש בפיה\"מ שם (וראה ראש אמנה ספי\"ט)."]]],[1300181290,"דברים בעולם, איז מובן אויך אַז ניט דאָס איז די בחינה אויף אמיתתו.\nפונקט ווי אַ נביא, וואָס די בחינה אויף אמיתתו „האות שלו, שיאמר דברים העתידים להיות בעולם ויאמנו דבריו שנאמר וכי תאמר בלבבך איכה נדע הדבר וגו'\" (כנ\"ל סוס\"ו), ד. ה. די בחינה אויף אמיתתו איז דערמיט וואָס עס איז ענינו — „נביא\", ער זאָגט דברי עתי־דות 64;\nעד\"ז איז מובן בנוגע משיח'ן, כאָטש אַז ער וועט אויך זיין אַ נביא גדול, און גרעסער מכל הנביאים (קרוב למשה רבינו), איז אָבער גדרו וענינו — „מלך המשיח\" כנ\"ל, ובמילא איז מובן (הלכה ד) אַז די בחינה און דער סימן אויף אמיתתו איז אויב ענינו בעצמו איז תורה וקיומה — „ואם 65 יעמוד מלך מבית דוד הוגה בתורה ועוסק במצות . . כפי תורה שבכתב ושבעל פה\" און ער פועלט די שלימות פון קיום המצות באַ אידן — „ויכוף כל ישראל לילך בה ולחזוק בדקה וילחום מלחמות ה' כו'\" (וואָס ילחום מלחמות ה' איז אויך אַ פרט אין דעם ברענגען צו שלימות קיום התורה כנ\"ל, אַראָפּנעמען דעם „נוגש ומבטל\" מצד די אומות).\nדאָס ברענגט אָבער נאָר צו וויסן אַז „הרי זה בחזקת שהוא משיח\", בשעת ער דערפירט אָבער צו דער שלימות פון קיום התומ\"צ בפועל, „אם עשה והצליח ונצח כל האומות שסביבין ובנה מקדש במקומו וקבץ נדחי ישראל\" דעמאָלט דוקא „הרי זה משיח בודאי\". וואָרום דעמאָלט „חוזרין כל המשפטים . . ככל מצותה האמורה בתורה\" — די שלימות אין הלכות וקיום המצות בפועל 66.\nיד. ויש להוסיף בזה, אַז די ראיות וואָס דער רמב\"ם ברענגט פריער זיינען ניט נאָר אויף כללות הדברים בתחילת הפרק, אַז „המלך המשיח עתיד לעמוד ולהחזיר מלכות דוד ליושנה לממשלה הראשונה . . ככל מצותה האמורה בתורה\", נאָר אויך אויף די פרטים פון הלכה ד 67;\nאון דעריבער ברענגט דער רמב\"ם אויך אין דער ראי' פון פרשת בלעם,",[["64","64","ראה רמב\"ם הל' יסוה\"ת פ\"י ה\"ג: הא למדת שאין הנביא עומד לנו כו'. וראה שם ספ\"ז. פ\"ט ה\"ב."],["65","65","ועפ\"ז מובן ומודגש ביותר ההמשך לההלכה שלפנ\"ז, שלכן מתחיל הרמב\"ם „ואם\" — בוא\"ו. וראה קרית ספר שם „אין מלך המשיח צריך לעשות אותות ומופתים אלא כשיעמוד מלך כו'\"."],["66","66","עפ\"ז מובן בפשטות מה שלא הביא הרמב\"ם (גם) בתחילת הפרק שמשיח ילחום מלחמות ה' — כי שם מבאר הגדר והמכוון שלו (להחזיר מלכות דוד ליושנה כו') — לאחר שכבר הביא לשלימות התורה, כשהוא „משיח בודאי\", משא\"כ קודם הנצחון במלחמות ה'. עפ\"ז אולי יש להוסיף (בפנימיות הענינים עכ\"פ), שזה שהביא הרמב\"ם שני המשיחים במשיח הראשון שהוא דוד כו' ובמשיח האחרון כו' — כי דוגמתן נמצא במשיח עצמו, ב' תקופות ודרגות לאחרי ביאת המשיח: לפני שיבנה ביהמ\"ק — שאז הוא עדיין „בחזקת משיח\", בדוגמת דוד שלא בנה המקדש, וענינו ילחם מלחמות (ראה דה\"א כב, ח) והכין הכל לבנין ביהמ\"ק מיד ה' עלי השכיל (שם כח, יט); כשהוא משיח ודאי ש„בנה מקדש במקומו\". וראה בארוכה מכתב כ\"ק אדמו\"ר מהורש\"ב נ\"ע (אגרות קודש שלו ח\"א ע' שיב) בביאור לשון רז\"ל „בן דוד בא\" או „דוד בא\" (ע\"פ הב\"ח או\"ח סקי\"ח) דיש ב' מדריגות במשיח: ביאתו לפני בנין ביהמ\"ק וירושלים (שאז הוא בחזקת משיח) ואחר שיבנה משיח את ביהמ\"ק וירושלים דאז „כיון שנבנית ירושלים — בא דוד\" (מגילה יז, ב) — (משיח בודאי). ולהעיר משינוי הגירסא ברמב\"ם (כנ\"ל סעיף ט והערה 46) „להחזיר מלכות דוד\" או „בית דוד\". ואכ\"מ."],["67","67","ועד\"ז בנוגע להשלילה (והפרט) שבהלכה ג' שמוכח הוא מהראי' שהביא בהלכה ב' שהיא הקדמה להלכה ג' — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271109\" data-slug=\"likkutei-sichot\" data-id=\"1300271109\">לקו\"ש חכ\"ז ע' 109</a> ואילך."]]],[1300181291,"וואָס נבא בשני המשיחים . . דוד ומשיח, די פיר פרטים און ענינים (אין התגלות) פון משיח'ן ווי עס שטייט מפורש — „ושם נבא\" — אַז דאָס איז דער המשך „להחזיר מלכות דוד ליושנה\".\nבכללות טיילט זיך דאָס אין דריי חלוקות: א) דוד ומשיח עצמם, ב) זייער פעולה און מלכות אויף אידן, ג) זייער פעולה און מלוכה אויף אומות העולם (אויף דער וועלט בכלל). און אין דעם דריטן ענין גופא זיינען דאָ צוויי זמנים וענינים, כדלקמן.\nטו. ענינם בעצמם — „יעמוד מלך מבית דוד הוגה בתורה ועוסק במצות כדוד אביו כפי תורה שבכתב ושבעל פה\".\nאון דאָס איז מפורש בתורה „אראנו (זען אים) ולא עתה זה דוד אשורנו (זען אים) ולא קרוב זה מלך המשיח\" — די נבואה אויף דוד ומשיח עצמם.\nב) „ויכוף כל ישראל לילך בה ולחזק בדקה\" — זייער פעולה און מלכות אויף אידן, וואָס דאָס איז מפורש אין המשך הכתוב „דרך כוכב מיעקב זה דוד וקם שבט מישראל זה המלך המשיח\" — וואָס דאָס ווייזט אויף דער שייכות צו אידן „כוכב מיעקב . . שבט מישראל\".\n[און אין דעם זאָגט מען אויך די שלימות (און יתרון) פון מלך המשיח, משיח אחרון לגבי משיח הראשון:\nאויף דוד'ן ווערט געזאָגט דער לשון (א) „כוכב\" וואָס ווייזט אויף אַזאַ וואָס איז מרומם ומנושא פון אַנדערע בנ\"א 68 [ווי ס'איז מובן פון רמב\"ם 69 בנוגע כוכבים כפשוטם, „כל הכוכבים והגל־גלים כולן בעלי נפש ודעה והשכל הם כו' ודעת הכוכבים כו' וגדולה מדעת בנ\"א\"]. (ב) „מיעקב\" — וואָס ווייזט אויף אידן נישט ווי זיי זיינען בתכלית המעלה.\nאָבער בנוגע צו משיח'ן זאָגט ער (א) „וקם שבט\", וואָס פירושו כפשוטו איז „מלך רודה ומושל\" 70, וואָס דאָס איז בגלוי באַ משיח'ן, „ויכוף כל ישראל לילך בה ולחזק בדקה\" (ב) „מישראל\" — שם המעלה פון אידן] 71.\nג) וילחם מלחמות ה' . . אם עשה והצליח ונצח כל האומות שסביבין\" — שטייט אין פסוק „ומחץ פאתי מואב זה דוד וכן הוא אומר ויך את מואב וימדדם בחבל וקרקר כל בני שת זה המלך המשיח שנאמר בו ומשלו מים עד ים\".\n[וואָס אויך אין דעם איז מודגש די מעלה פון מלך המשיח: באַ דוד איז נאָר (א) „מחץ\", (ב) „פאתי מואב\". און באַ משיח'ן: (א) „וקרקר\", (ב) „כל בני שת\", די שליטה 72 אויף אַלע אומות 73.\nאָדער ווי דער לשון אין נביאים: באַ דוד'ן (א) „ויך\" (ב) „את מואב\"; און באַ משיח'ן (א) „ומשלו\" (ב) „מים עד ים\"].",[["68","68","ראה רד\"ק עה\"פ. וראה רלב\"ג ורמב\"ן לפירושם שקאי על משיח. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131088\" data-slug=\"likkutei-sichot\" data-id=\"1300131088\">לקו\"ש חי\"ג ע' 88</a> ואילך."],["69","69","הל' יסוה\"ת פ\"ג ה\"ט."],["70","70","פרש\"י עה\"ת."],["71","71","והמעלה דמשיח מודגשת גם בענין הא', המדבר בדוד ומשיח עצמם: בדוד אומר „ולא עתה\", אבל אראנו בזמן קרוב; ובמשיח — „ולא קרוב\", לפי שזהו ענין ומדריגה נעלית שבאה רק לאחרי אריכות זמן שנתרבו מעשינו ועבודתנו בכדי להגיע לבחי' זו."],["72","72","כבת\"א שם. וכן הוא לכאורה לפי' הרמב\"ם שהרי הביא „ומשלו מים גו'\". ובראב\"ע: הורס. וראה שם ד\"ה בני שת. ועד\"ז ברלב\"ג ורד\"ק. וראה תיב\"ע ות\"י. לקו\"ש שם. ואכ\"מ."],["73","73","ראה במקומות שבהערה הקודמת."]]],[1300181292,"ד) „ויתקן את העולם כולו לעבוד את ה' ביחד שנאמר כי אז אהפוך אל עמים שפה ברורה לקרוא כולם בשם ה' ולעבדו שכם אחד\" — שטייט אין פסוק „והי' אדום ירשה זה דוד שנאמר ותהי אדום לדוד לעבדים וגו'. והי' ירשה שעיר אויביו זה המלך המשיח שנאמר ועלו מושיעים בהר ציון וגו'\" 74.\n[וואָס אויך דאָ איז מובן די מעלה פון משיח'ן: בנוגע לדוד זאָגט מען „והי' אדום ירשה\", וואָס דאָס דריקט זיך אויס אין דעם וואָס „ותהי אדום לדוד לעב־דים\", און בנוגע משיח'ן — „והי' ירשה שעיר אויביו\", ניט נאָר די אנשי העיר, און ווי ער זאָגט אין פסוק „ועלו מושיעים בהר ציון לשפוט את הר עשו\" וואָס סיומו איז „והיתה *74 לה' המלוכה\"]\nטז. דער אויפטו אין דעם פערטן ענין לגבי דעם דריטן ענין „ילחם מלחמות ה'\" און נצחון האומות — „ומשלו מים עד ים\", איז מובן פון די לשונות גופא „ומשלו . . ירשה\", „וילחם . . ויתקן את העולם\", ובדוגמת דער חידוש פון ירושה אויף כיבוש (און ווי מען געפינט בנוגע א\"י די ביידע ענינים אַז זיי האָבן דאָס גענומען ע\"י כיבוש און אויך געהאַט בירושה) 75:\nדער ענין פון מלחמה און נצחון — כיבוש מלחמה, איז באופן פון „קרקר\" „ומשלו\" — שליטה, היפך דער מציאות ורצון פון דעם וואָס מען איז כובש:\nמשא\"כ דער ענין הירושה „והי' ירשה שעיר\", איז אדרבה, מען נעמט איבער אַ נאָענטע אייגענע זאַך, ניט אַז מען איז כובש ושולט אויף אַ צווייטן.\nועד\"ז איז מובן דער חידוש פון „ויתקן את העולם כולו לעבוד את ה' ביחד\", אויף „וילחם מלחמות ה' . . ונצח כל האומות שסביבין\", אַז זיי גופא אַנער־קענען דעם אמת פון מלכותו פון מלך המשיח [און ווי ס'איז מרומז ומפורש אין סיום ההלכה (וואָס איז נשמט געוואָרן ע\"י הצענזער) „וכשיעמוד המלך המשיח באמת ויצליח וירום ו(י)נשא מיד הם כולן חוזרין ויודעים ששקר נחלו אבותיהם ושנביאיהם ואבותיהם הטעום\"]. עס ווערט ביי זיי „לקרוא כולם בשם ה' ולעבדו שכם אחד\" 76.",[["74","74","וי\"ל דשייך גם ל„ובנה מקדש במקומו\" שהרי „נחלה זו ירושלים\" (מגילה י, א. וראה זבחים קיב, ב. קיט, א) שענינה ירושה וקביעות שאין אחרי' היתר (הפסק). וראה רמב\"ם הל' ביהב\"ח פ\"א ה\"ג. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161478\" data-slug=\"likkutei-sichot\" data-id=\"1300161478\">לקו\"ש חט\"ז ע' 465</a> ואילך. ומה שלא נרמז בפסוק בפ\"ע — כי זה נכלל (ביחד עם „וקבץ נדחי ישראל\") בממשלתו על ישראל — „וקם שבט מישראל\". ואולי י\"ל (ע\"ד הרמז עכ\"פ) שלכן כתב הרמב\"ם בפרשת בלעם, להסביר ולהדגיש מה שעיקר נבואתו הי' ע\"ד מפלת האומות ושליטת דוד ומלך המשיח עליהם, שהוא ע\"ד מיני' ובי' אבא ניזיל בי' נרגא, שהנביא של אוה\"ע (שהוא בדוגמת משה* — ספרי ברכה לד, יוד. ועוד) מנבא על מפלתם של אוה\"ע ושליטת ישראל עליהם. וע\"ד מרז\"ל בנוגע לעובדי' (סנה' לט, ב (ד„ועלו מושיעים בהר ציון וגו'\" (שהביא הרמב\"ם בסוף ההלכה כאן) הוא סיום נבואת עובדי'). ושם גם בענין דוד — „ויך את מואב\", שהביא הרמב\"ם כאן). *) בדרגת נבואת בלעם — ראה מו\"נ ח\"ב פמ\"ה, שהי' במדריגת רוה\"ק (ולא נבואה) כדוד ושלמה. וראה פי' קרשקש ואברבנאל שם. ובצפע\"נ עה\"ת פרשתנו (כב, לה) דאח\"כ עלה בגדר נביא כו' ואח\"כ רצה שיהי' כמשה רבינו. ומשמע קצת שם, שזה שייך לנבואה זו האחרונה. עיי\"ש. *74) ראה לעיל הערה *12."],["75","75","להעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151106\" data-slug=\"likkutei-sichot\" data-id=\"1300151106\">לקו\"ש חט\"ו ע' 106</a>."],["76","76","ושייכות ענין זה למלך המשיח מובן ממ\"ש שם (פ\"ח ה\"י) „צוה משה רבינו מפי הגבורה לכוף"]]],[1300181293,"און דורך דער אמונה שלימה בביאת המשיח, ווי ס'איז עפ\"י תורה און „מחכה לביאתו\", אחכה לו בכל יום שיבוא (וואָס י\"ל אַז אין דעם איז אויך נכלל דער לימוד אין הלכות משיח), וועט דאָס גופא 77 מקרב און ממהר זיין ביאתו אין אַן אופן פון אחישנה ובקרוב ממש.\n(משיחות י\"ב תמוז, מוצש\"ק פ' בלק ופ' פנחס תשל\"ח)",[["","","את כל באי העולם לקבל מצות שנצטוו בני נח\". וראה שם ספ\"ד „ולמלאות העולם צדק\". ואולי י\"ל שהם („לכוף\", ו„למלאות כו'\") ב' ענינים, כהחילוק בין ענין הג' וענין הד' שבפנים. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231174\" data-slug=\"likkutei-sichot\" data-id=\"1300231174\">לקו\"ש חכ\"ג ע' 174</a> ואילך."],["77","77","ראה שיחת אחש\"פ תרצ\"ט."]]],[1300181294,"<h3>בלק ג</h3>\nא. בשייכות צום סיפור אינעם סיום פון אונזער סדרה 1 — „והנה איש מבני ישראל בא ויקרב אל אחיו את המדינית לעיני משה גו'\" — דערציילן חז\"ל 2, אַז זמרי בן סלוא האָט די „מדינית\" (כזבי בת צור) געבראַכט פאַר משה רבינו און גע'טענה'ט: „זו אסורה או מותרת, ואם תאמר אסורה, בת יתרו מי התירה לך. נתעלמה ממנו (פון משה) הלכה\", ביז אַז פינחס „ראה מעשה ונזכר הלכה כו' הבועל את כותית 3 קנאין פוגעין בו\".\nפאַרוואָס איז טאַקע „בת יתרו\" געווען מותרת צו משה רבינו ? — איז רש\"י 4 מסביר: „משה קודם מתן תורה נשא וכשניתנה תורה כולן בני נח היו ונכנסו לכלל מצות והיא עמהם כו'\". ד. ה. משה נשא צפורה ווייל דעמאָלט (פאַר מתן תורה) זיינען אַלע (אויך די בנ\"י) געווען אין גדר פון בני נח; און דערנאָך (ביי מ\"ת) האָט זיך אויך צפורה מגייר 5 געווען צוזאַמען מיט אַלע אידן, און דערפאַר איז זי אויך דערנאָך מותרת צו משה'ן.\nאיז ניט מובן: זמרי איז דאָך געווען „נשיא בית אב לשמעוני\" 6, היינט וואָס איז מלכתחילה געווען זיין טענה „ואם תאמר אסורה, בת יתרו מי התירה לך\" — צי דען האָט ער ניט געוואוסט דעם חילוק הכי פשוט צווישן נשואין פון פאַר מ\"ת און נאָך מ\"ת ?!\nולאידך גיסא: אויב אפילו מ'זאָל געפינען עפעס אַ הסברה (לכה\"פ אַלס אַ קס\"ד) פאַרוואָס דער חילוק הנ\"ל איז ניט קיין טעם מספיק צו מתיר מאַכן „בת יתרו\" צו משה — איז נאָך אַלס שווער, פאַרוואָס מ'געפינט ניט אין גמרא אַז משה (אָדער אימיצער אַנדערש) זאָל ענטפערן אויף דער טענה פון זמרי",[["1","1","כה, ו."],["2","2","סנהדרין פב, א. תנחומא פרשתנו כ־כא. במדב\"ר פ\"כ, כד־כה. תיב\"ע ופרש\"י עה\"פ."],["3","3","בפרשתנו מדובר ע\"ד מדינית, במשנה (סנה' שם) הל' ארמית — ואולי יש כאן שינוים ע\"י מבקר המלכות. וראה רמב\"ם הל' איס\"ב רפי\"ב ב' גירסות. ובפרש\"י סנה' פא, ב: ארמית בת עובד כוכבים."],["4","4","סנהדרין פב, א ד\"ה בת יתרו. ביד רמ\"ה סנהדרין שם: „ניתנה תורה ונתחדשה הלכה ולא אסרה תורה אלא מכאן ואילך אבל מי שהי' נשוי ועומד קודם מ\"ת לא נאסרה עליו\". אבל ברבותינו בעה\"ת (בהעלותך יא, כז): כשנתנה תורה כו' פרשו כולם כו'. וראה גליוני הש\"ס (להר\"י ענגל) סנהדרין שם שקו\"ט בדבריו. תו\"ש לשמות ב, כא אות קע. וראה הערה הבאה."],["5","5","ביד רמ\"ה שם משמע דס\"ל דמותרת גם בלי גיור ד„ניתנה תורה ונתחדשה הלכה\". וראה ג\"כ: ילקוט ראובני ר\"פ פינחס: „ויאמר לו ניתנה תורה ונתחדשה הלכה ועוד יאמר אני גיירתי\". יעב\"ץ סנהדרין שם: „ולא שייכא גירות כלל אלא שנתנה תורה\". גם מלשון רש\"י „נכנסו לכלל מצות והיא עמהם וגרים רבים של ערב רב\" משמע קצת שא\"צ ענין הגירות כבערב רב (וראה צפע\"נ דלקמן הערה 20). ועפ\"ז אין מקום לקושיא דלקמן בפנים סעיף ב'. אבל נוסף ע\"ז שגם בנוגע לבני ישראל מפורש שנתגיירו (עיין יבמות מו, א ואילך. כריתות ט, רע\"א) — הרי מכיון שהיא „בת יתרו\" (ולא מבני אברהם יצחק כו'), ועוד ועיקר — לא הייתה במצרים ששם היתה תחלת הגירות (יבמות וכריתות שם) בודאי הי' צ\"ל אצלה גירות. ועד\"ז בנוגע לבנ\"י — שמילתם הייתה אך בתור מצוה שנצטווה אברהם, משא\"כ במצרים שי\"ל שהי' גם התחלת הגירות — עיין יבמות וכריתות שם. ובגליוני הש\"ס שם: ודבריו (דהרמ\"ה) צע\"ג דהא פשיטא דנתגיירה כו'."],["6","6","פינחס כה, יד. ובסנהדרין שם (ועד\"ז בפרש\"י עה\"ת כה, ו (ודלא כפרש\"י בפנחס)): נשיא שבט הוא. ולהעיר מדרז\"ל (סנה' שם, ב) שזהו שלומיאל בן צורישדי."]]],[1300181295,"כלפי משה רבינו 7 (פינחס האָט בלויז געזאָגט די הלכה „הבועל ארמית כו'\", וואָס איז נוגע צו מעשה זמרי) ?\nעס זיינען דאָ מפרשים 8 וואָס זאָגן, אַז דאָס גופא (דער חילוק הנ\"ל צווישן פאַר און נאָך מ\"ת) איז „נתעלמה\" פון משה. אָבער נוסף אויף דעם, וואָס (א) רש\"י 9 זאָגט בפירוש: „ונתעלמה ממנו הלכה, שנאמר לו בסיני הבועל כותית וכו'\", אַז בלויז די הלכה (וואָס פאַר אַן עונש עס קומט) איז „נתעלמה ממנו\"; (ב) ס'איז אַ דוחק גדול צו זאָגן אַז עס זאָל נתעלם ווערן פון משה אַזאַ פשוט'ער חילוק כנ\"ל 10 — איז אויך ניט מובן: ווי האָט זמרי געפרעגט אַזאַ שאלה ? האָט ער זיך דען געקענט פאַרלאָזן אַז פון משה'ן וועט נתעלם ווערן דער חילוק צווישן פאַר און נאָך מ\"ת ?\nב. אויך דאַרף מען פאַרשטיין:\nדער 11 דין איז, אַז אַ גיורת איז אסורה לכהן; און דאָס איז אַן איסור מן התורה. הגם די גמרא 12 לערנט עס אָפּ פון אַ פסוק אין יחזקאל 13 — איז דאָס נאָר וואָס „אתא יחזקאל ואסמכה אקראי\" 14, אָבער דאָס איז אַן איסור מן התורה ממש „אשה 15 זונה גו' לא יקחו\" 16 — „לפי שבאה מן העכו\"ם השטופים בזימה\" 14.\nאין דער גמרא 17 איז דאָ אַ פלוגתא וועגן משה רבינו: לויט איין דיעה איז „משה רבינו כהן גדול\" 18 (ווייל „לא פסקה כהונה אלא מזרעו של משה\"<sup data-n=\"17\">17</sup>, אַ צווייטע דיעה האַלט, אַז „לא נתכהן משה אלא שבעת ימי המלואים בלבד\" 19 — איז קשה: ווי אַזוי איז „בת יתרו\" 20 געווען מותרת צו אים — זי איז דאָך געווען אַ גיורת 21 ?",[["7","7","ראה גם ילקוט ראובני שם."],["8","8","ראה עיון יעקב לע\"י סנהדרין שם, א."],["9","9","סנהדרין שם. יד רמ\"ה שם. וראה ילקוט ראובני ויעב\"ץ הנ\"ל."],["10","10","ואם כדי שיבוא פינחס ויטול את הראוי לו (תנחומא, במדב\"ר ופרש\"י שבהערה 2) — העלמת ההלכה דקנאין פוגעין מספיקה."],["11","11","בהבא לקמן ראה אנציקלופדי' תלמודית ע' גיורת, וש\"נ."],["12","12","קידושין עח, סע\"א."],["13","13","מד, כב."],["14","14","תוד\"ה אין יבמות סא, א."],["15","15","אמור כא, ז."],["16","16","רמב\"ם הל' איסורי ביאה פי\"ח ה\"ג (ראה מ\"מ שם). תוספות שם. ועוד (נסמנו באנציקלופדי' שם). וגם להראב\"ד (הל' איסו\"ב שם) ד„אינה משום זונה אלא משום דכתיב כו'\" (הקרא דיחזקאל), הוא איסור מן התורה — כמ\"ש להדיא (שם פט\"ז ה\"ב). וראה חידושי הרשב\"א יבמות ס, ב."],["17","17","זבחים קב, א. והובאו בכ\"מ במדרז\"ל."],["18","18","רב — שם קא, ב."],["19","19","וגם למ\"ד „אני אמרתי אתה כהן כו' עכשיו כו' ואתה לוי\" — „פסיקא לי' דכהן הי' מדעבד עבודה בשבעת ימה\"מ . . ונפסקה לו כהונה אלא שניטלה ממנו בחרון אף\" (חדא\"ג שם)."],["20","20","אבל אם לא היתה „בת יתרו\" — אף שבמ\"ת נתגיירו כל ישראל (כדלעיל בתחילת השיחה והערה 5) — עכצ\"ל שגירות זו אינה אסורה לכהן ואהרן ואלעזר ואיתמר בניו יוכיחו והטעם מובן כי בבני אברהם כו' לא שייך הטעם „שבאה מן העכו\"ם השטופים בזימה\". גם י\"ל עפמ\"ש בצפע\"נ לסנהדרין שם ד„לאחר מ\"ת נעשו יהודים למפרע\", עיי\"ש. וע\"פ המבואר בצפע\"נ שם „דמדין כיון דהם ג\"כ מזרע אברהם לאחר המילה, ואמם נתגיירה אז אם יתגיירו הוה ישראל למפרע, וזה צפורה כו'\" — מתורצת הקושיא שבפנים. וראה לקמן הערה 28. ולהוסיף: עפמשנ\"ת ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081176\" data-slug=\"likkutei-sichot\" data-id=\"1300081176\">לקו\"ש ח\"ח (ע' 165</a> הערה 29) שלשיטת רש\"י בפירושו עה\"ת הי' יתרו „אבי אמו\" (ממש) דפינחס — היינו דגם אשת אלעזר הכהן היתה „בת יתרו\" — השקו\"ט שבפנים השיחה היא גם בנוגע לאלעזר הכהן."],["21","21","בפרש\"י יבמות (סא, סע\"א) דגיורת פסולה כי „ביאת עכו\"ם כו' פסלה\", ועד\"ז מפרש שם (ע\"ב) ד\"ה אלא גיורת („דנבעלה בנכריותה כו'\"). והובא בב\"ש לשו\"ע אה\"ע ס\"ו סק\"כ. — אבל דעת הפוסקים דאסורה גם כשלא נבעלה"]]],[1300181296,"לויטן מ\"ד אַז „לא נתכהן משה אלא שבעת ימי המלואים בלבד\", וואָלט מען נאָך געקענט ענטפערן 22 (עכ\"פ בדוחק), אַז משה איז אויך דאַן ניט געווען קיין כהן גמור; און דאָס וואָס ער האָט געמעגט מקריב זיין דעמאָלט די קרבנות, איז עס דערפאַר ווייל — ווי תוספות 23 איז מסביר — אין די שבעת ימי המלואים האָט דער משכן געהאַט אַ דין במה [און דערפאַר „שימש משה שבעת ימי המלואים בחלוק לבן\" 24 — ניט מיט די בגדי כהונה — ווייל „אין בגדי כהונה בבמה\"] — און דערפאַר איז אויך „בת יתרו\" (אַ גיורת) ניט געווען אסור צו אים.\nאָבער — לבד זאת, וואָס פון לשון הגמרא „לא נתכהן משה כו'\" איז משמע, אַז בשבעת ימי המלואים איז ער געווען אַ כהן גמור 25 — בלייבט דאָך שווער לויטן מ\"ד אַז משה „כל 26 ימיו כהן הי'\" 27.\nג. לכאורה וואָלט מען געקענט זאָגן, אַז די צוויי שאלות הנ\"ל (סעיף א' וב') ווערן פאַרענטפערט אחת בחברתה:\nמיט דער טענה „בת יתרו מי התירה לך\" האָט זמרי טאַקע געמיינט (ניט דעם איסור חיתון מיט אַן „ארמית\", נאָר) דעם איסור גיורת לכהן 27*; און די שייכות צווישן דעם איסור מיט דעם וואָס אַ „מדינית\" איז אסורה („אם תאמר (זו) אסורה בת יתרו כו'\") איז אין דעם, וואָס דער טעם האיסור פון גיורת לכהן איז (כנ\"ל) „לפי שבאה מן העכו\"ם (ארמים) השטופים בזימה\". ד. ה. אויב די „מדינית\" איז אסורה ווייל זי איז אַן „ארמית\" — פאַרוואָס־זשע איז „בת יתרו\", „שבאה מן העכו\"ם (ארמים) וכו'\" מותרת צו משה (אַ כהן) ?\nאָבער לפ\"ז בלייבט שווער (כנ\"ל סעיף א') לאידך גיסא: (א) וואָס איז טאַקע די תשובה אויף דער טענה ? און (ב) פאַרוואָס האָט מען דעם ענטפער ניט געזאָגט צו זמרי'ן 28 ?\nד. לכאורה וואָלט מען געקענט פאַרענטפערן 29 מיט דעם וואָס חז\"ל 30",[["","","(ראה ב\"ש שם. אנציקלופדי' שם, וש\"נ). וראה מנ\"ח (מצוה רסו) שתמה על דעת רש\"י, עיי\"ש. ובחכמת שלמה (לשו\"ע אה\"ע שם) מאריך דגם לרש\"י אסורה גם אם לא נבעלה, עיי\"ש."],["22","22","גם יש לתרץ (למ\"ד זה) — כי הציווי(ים) דפ' אמור („אשה זונה גו' לא יקחו\") נאמר(ו) לאחרי ז' ימי המילואים. ובגיטין (ס, סע\"א): „ח' פרשיות נאמרו ביום שהוקם בו המשכן כו' פרשת כהנים („אמור אל הכהנים כו'\" — פרש\"י שם) כו'\". ולהעיר מתו\"כ לשמיני (י, ד) „מיכן אמרו אין מטמאין למתים כו'\"."],["23","23","ע\"ז לד, א ד\"ה במה."],["24","24","ע\"ז שם. וש\"נ."],["25","25","להעיר ממשנ\"ת (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071188\" data-slug=\"likkutei-sichot\" data-id=\"1300071188\">לקו\"ש ח\"ז ע' 175</a> שוה\"ג הב' להערה 28), שי\"ל שכהונת משה היתה רק התואר דכהונה, ולא הענין ד„לקדשו לכהנו לי\" — שירות דכהונה (מכיון ששימש בחלוק לבן), עיי\"ש. — אבל ג\"ז די לאסור עליו גיורת משום „אשה זונה גו'\", שהרי גרושה כו' אסורה גם לכהן בע\"מ שאין בו שירות דכהונה."],["26","26","לשון רש\"י זבחים קב, א ד\"ה ויש אומרים."],["27","27","לכאורה אפשר לתרץ ע\"ד תי' הש\"ס (זבחים שם) דמשה זר הוא לענין נגעים כי „שאני מראות נגעים דאהרן ובניו כתובין בפרשה\", והרי גם בר\"פ אמור (אצל הציווי „אשה זונה גו'\") נאמר „אמור אל הכהנים בני אהרן\". אבל — יש לחלק. כי דיוק הש\"ס „אהרן ובניו כתובין בפרשה\" הוא משום שהכתוב (תזריע יג, ב) מקדים „אהרן הכהן\" ורק אח\"כ כתיב „או אל אחד מבניו הכהנים\". משא\"כ בנדו\"ד שנאמר „הכהנים (ואח\"כ) בני אהרן\", י\"ל שהכוונה לענין הכהונה ולא שצ\"ל „בני אהרן\" דוקא. 27*) ראה גם ראש דוד (להחיד\"א) פ' פינחס."],["28","28","ראה לעיל הערה 20 מה שי\"ל ע\"פ המבואר בצפע\"נ שגם מדין ,אם נתגיירו הוה ישראל למפרע'. ועפ\"ז י\"ל שזמרי לא ס\"ל כן (לענין מדינית) ולכן טען „בת יתרו מי התירה לך\" מצד איסור גיורת לכהן. ומשה לא השיב, כמבואר לקמן בפנים (סעיף ו') דלא נאמן בשעת מעשה, עיי\"ש."],["29","29","ראה גם ערוך לנר סנהדרין שם."],["30","30","שבת פז, א. יבמות סב, רע\"א."]]],[1300181297,"זאָגן: „ג' דברים עשה משה מדעתו והסכים הקב\"ה עמו\", וואָס איינער פון זיי איז דאָס וואָס „פירש מן האשה\". ובמילא איז שוין ניטאָ קיין טענה „בת יתרו מי התירה לך\" (מצד דעם איסור גיורת לכהן), ווייל משה האָט זיך פורש געווען מאשתו.\nאון כאָטש פרישה אַליין איז לכאורה ניט גענוג אַראָפּצונעמען דעם איסור גיורת לכהן — זאָגט דאָך אָבער רש\"י בפירושו על התורה אויפן פסוק (אין ס\"פ בהעלותך<sup data-n=\"31\">31</sup> „ותדבר מרים גו' על אודות האשה גו' כי אשה כשית לקח\" — „על אודות האשה, על אודות גירושי'; כי אשה כשית לקח, ועתה גירשה\", ד. ה. רש\"י לערנט אַז ס'איז ניט נאָר וואָס „פירש מן האשה\" (ווי רש\"י ברענגט עס דאָרט 32 אַראָפּ), פרישה בעלמא 33, נאָר ס'איז געווען — גירושין 34.\nפונדעסטוועגן האָט מען דאָס ניט געענטפערט זמרי'ן ווען ער האָט געפרעגט „בת יתרו מי התירה לך\" — ווייל, ווי מבואר אין דברי חז\"ל 35, האָט קיינער פון דעם ניט געוואוסט, ביז אַז אויך מרים האָט זיך דערפון דער־וואוסט ערשט ווען „אלדד ומידד מתנבאים במחנה\" 36 און צפורה האָט געזאָגט „אוי לנשותיהן של אלו כו'\" 37;\nוואָרום וויבאַלד משה האָט עס געטאָן „מדעתו\", האָט ער, זייענדיק אַן „עניו מאד\" 38, ניט געוואָלט מ'זאָל דערפון וויסן — און מהאי טעמא האָט ער 39 אויך ניט געוואָלט ענטפערן זמרי'ן אַז „פירש מן האשה\".\nאָבער דער ביאור איז ניט אויס־געהאַלטן 29, ווייל\n[נוסף אויף דעם, וואָס רש\"י 40 לערנט (לויטן ספרי<sup data-n=\"40\">40</sup> אַז משה האָט זיך פורש געווען מן האשה (ניט „מדעתו\", נאָר) ווייל „אמרתי לו לפרוש מן האשה . . ואתה פה עמוד עמדי\" 41, און עס איז דאָך ניט היפך העניוות צו דערציילן אַז ער האָט מקיים געווען אַ ציווי ה' 42 — איז]\nדי סיבה פון פרישת משה מן האשה זאָגט מען אַז עס איז דערפאַר וואָס ער",[["31","31","יב, א."],["32","32","ד\"ה ותדבר מרים ואהרן."],["33","33","דלא כמ\"ש הרא\"ם שם, ד„גרושי'\" היינו „הפרשתה שפירש בעלה ממנה\". וראה לעיל ע' 145 שוה\"ג להערה 41."],["34","34","ראה גם תוד\"ה דכתיב יבמות שם: „או נתן לה גט\". ובמכילתא עה\"פ (יתרו יח, ב) „אחר שלוחי'\" — „שנפטרה ממנו בגט\". וראה ריב\"א עה\"ת יתרו יט, טו."],["35","35","ספרי בהעלותך שם • (הובא בתוס' יבמות שם. שבת שם ד\"ה ואתה (בשם „מדרש\")). פרש\"י שם. תנחומא צו יג. ומלשון התנחומא (שבהערה 2) „אותה שתחתיך\" מוכח שעד אז (שנת הארבעים) לא ידעו כל ישראל שגירשה. אבל י\"ל שלדעת התנחומא לא גירשה רק „פירש\" ממנה. •) בכמה דפוסי ספרי הובא רק הטעם „שראתה את צפורה שאינה מתקשטת כו'\". אבל גם לטעם זה רק אז נתוודע שפירש כו'."],["36","36","בהעלותך יא, כז."],["37","37","בתוס' שבת שם כ' „דודאי ידעו אבל היו סבורין שפירש ע\"פ הדיבור עד שאמרה להם צפורה שמדעתו פירש כו'\". אבל ביבמות שם כתבו „שלא נתגלה להם אלא באותה שעה כדתניא בספרי כו'\"."],["38","38","בהעלותך יב, ג."],["39","39","ומכ\"ש שמרים ואהרן לא סיפרו שגירשה, שהרי נענשו על שדיברו עליו."],["40","40","בהעלותך שם, ח. ולהעיר מלשון רש\"י שם, ד: שיפה עשה משה כו'."],["41","41","ב' הדיעות — אם פירש מדעתו או ע\"פ הציווי — הובאו ג\"כ באדר\"נ פ\"ב, ג."],["42","42","ועד\"ז לתוס' שבת שם, שאהרן ומרים „היו סבורין שפירש ע\"פ הדיבור\" — דלמה יעלימו שגירש משה את צפורה ע\"פ הדבור ? אבל גם אם פירש משה מדעתו קשה: למה לא השיב לזמרי שפירש מן האשה שלא יאמרו שעבר על איסור גיורת לכהן (שא\"ז היפך העניוות) ?"]]],[1300181298,"איז געווען אַ נביא — ווי רש\"י 31 ברענגט אַראָפּ (פון ספרי<sup data-n=\"31\">31</sup> אַז צפורה האָט געזאָגט „אוי לנשותיהן של אלו אם הם נזקקים לנבואה שיהיו פורשין מנשותיהן\" 43 — בעת אַז עפ\"י הנ\"ל האָט ער איר געמוזט מגרש זיין מצד דעם איסור גיורת לכהן 44.\nה. דער ביאור אין דעם:\nעס שטייט אין משנה 45: „אירס (אַ כהן הדיוט) את האלמנה ונתמנה להיות כהן גדול יכנוס\". און די גמרא לערנט עס אָפּ פון פסוק 46 „יקח אשה\", אַז וויבאַלד דער „יקח אשה\" (די אירוסין) איז געווען בהיתר, מעג ער לכתחילה ענדיקן די לקיחה און כונס זיין די אלמנה.\nאיז עס אַ כל שכן וק\"ו בנדו\"ד, וואו ניט נאָר די אירוסין, נאָר אויך די נישואין זיינען געווען בהיתר 47, אַז אויך נאָכדעם ווי משה איז געוואָרן אַ כהן איז „בת יתרו\" געווען מותרת לו (כאָטש זי איז געווען אַ גיורת).\nלכאורה קען מען פרעגן אויף דעם: דאָס וואָס משה האָט חתונה געהאַט מיט צפורה בהיתר איז דאָך געווען פאַר מתן תורה; און היות אַז אידן האָבן דעמאָלט געהאַט אַ דין פון בני נח און ס'איז דאַן איבערהויפּט ניט געווען דער גדר ה„לקיחה\" פון נאָך מתן תורה 48, מוז מען דאָך זאָגן, אַז נאָך מתן תורה האָט ביי אידן געדאַרפט זיין מחדש קידושין ולקיחה דנשותיהן עפ\"י תורה 49 — איז דאָך הדרא קושיא לדוכתה: ווי האָט משה געמעגט מקדש זיין צפורה נאָך מתן תורה 50 ?\n— איז עס ניט קיין קשיא, ווייל [נוסף אויף דעם וואָס די נייע לקיחה איז דאָך זיכער געווען תיכף לאחר מ\"ת ובמילא — בנוגע משה איז דאָס געווען איידער ער איז געוואָרן אַ כהן (בימי המלואים, נאָך הקמת המשכן) — איז אפילו אויב מ'וועט אָננעמען, אַז לויט דער דיעה אַז משה „כל ימיו כהן הי'\" האָט זיין כהונה זיך אָנגעהויבן תיכף ביי מ\"ת 51, איז עס אויך ניט קיין קשיא, ווייל]:\nאויפן פסוק 52 „וילך איש מבית לוי ויקח את בת לוי\" דרש'נט די גמרא 53: „שעשה לה מעשה ליקוחין\", וואָס דער פשט אין דעם איז, אַז עמרם האָט איר",[["43","43","וראה שבת (ועד\"ז יבמות) שם: אני שכל שעה ושעה שכינה מדברת עמי כו'."],["44","44","ובפרט אם פירש רק מצד הציווי „ואתה פה עמוד עמדי\" — היינו, שלולי ציווי זה לא הי' פורש מן האשה."],["45","45","יבמות סא, א."],["46","46","אמור כא, יד."],["47","47","ראה תוד\"ה אטו יבמות כ, ב: נשאה קודם שנתמנה משמע דלא צריך קרא שיכול לקיימה משום דנשאה בהיתר."],["48","48","ראה רמב\"ם ריש הל' אישות: קודם מ\"ת הי' אדם פוגע אשה בשוק כו' מכניסה לתוך ביתו כו' כיון שנתנה תורה נצטוו ישראל כו' יקנה אותה תחלה כו'. וגם אלה מבנ\"י שקיימו כה\"ת עד שלא ניתנה וקידשו נשיהם (וראה פרש\"י ויחי מח, ט. ועוד) — מ\"מ, מכיון שלא נצטוו ע\"ז, אין להם תוקף כמו לאחר מ\"ת. וראה לקו\"ש ויחי תשמ\"ט ס\"ג ואילך."],["49","49","כדין גר שנתגייר ואשתו עמו שצריכים חופה וקידושין — דגול מרבבה לשו\"ע יו\"ד הל' גרים בסופו. וראה גליוני הש\"ס (דלעיל הערה 4): פשיטא דנתגיירה במ\"ת והוצרכה קידושין מחדש."],["50","50","כי להדיעות שלא גירשה רק „פירש\" ממנה, משמע שגם אח\"כ היתה אשתו [ולהעיר מלשון הספרי בהעלותך שם: שפירש משה מפרו' ורבי' כו' שאינה מתקשטת כו'] וא\"כ קידשה לאחר מ\"ת — אף שנאמר לו „ואתה פה עמוד עמדי\". ודוחק. וע\"פ המבואר לקמן בפנים מתורץ בפשטות. וגם לדעת רש\"י ש„גירשה\" — הרי זמרי לא ידע מזה (כנ\"ל בפנים), ולכן טען „בת יתרו מי התירה לך\", כדלקמן בפנים סעיף ו'."],["51","51","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071188\" data-slug=\"likkutei-sichot\" data-id=\"1300071188\">לקו\"ש ח\"ז ע' 175</a> והערה 28 שם."],["52","52","שמות ב, א."],["53","53","סוטה יב, א. ב\"ב קכ, א."]]],[1300181299,"מקדש געווען מיט ליקוחין פון נאָך מתן תורה.\n[דערמיט זיינען מפרשים 54 מסביר וואָס דער רמב\"ם 55 זאָגט „ובמצרים נצטוה עמרם במצות יתירות\" — וואָס לכאורה איז עס ניט מובן 56: וואו געפינט מען אַז „נצטוה עמרם במצות יתירות\" ? — נאָר דאָס איז די מצוה פון קידושין, וואָס איז שוין געווען אין מצרים 57].\nאון וויבאַלד אַז אויך פאַר מ\"ת זיינען די קדושי אשה געווען ביי אידן אין אַן אופן פון לקיחה פון נאָך מ\"ת, האָט ביי זיי ניט געדאַרפט זיין נייע קידושין נאָך מתן תורה — די פריערדיקע קידושין זיינען געבליבן בתקפן אויך נאָך מ\"ת 58.\nאון לפי\"ז איז מובן, אַז דער „יקח אשה\" פון משה רבינו איז געווען בהיתר, וויבאַלד עס איז געווען פאַר מ\"ת, און ער האָט צפורה'ן ניט געדאַרפט נאָכאַמאָל מקדש זיין נאָך מתן תורה.\nו. דערמיט קען מען מסביר זיין: (א) וואָס ס'איז געווען די טענה פון זמרי „בת יתרו מי התירה לך\", און (ב) פאַר־וואָס משה האָט אים גאָרניט געענט־פערט אויף זיין טענה:\nזמרי האָט ניט געהאַלטן פון דער ילפותא (פון תורה שבעל פה) פון „יקח אשה\" הנ\"ל, און לשיטתו האָט משה געמוזט מגרש זיין „בת יתרו\".\nמשה האָט ניט געקענט ענטפערן מיטן לימוד פון „יקח אשה\" 59 — ווייל 60 דער דין 61 איז, אַז אַ ת\"ח וואָס איז „מורה הלכה\" און איז אַ „נוגע בדבר\", איז ער ניט באַגלויבט בשעת מעשה צו זאָגן „כך קבלתי\" — און משה איז דאָך געווען אַ נוגע בדבר — „בת יתרו מי התירה לך\" 62.\n[ע\"ד ווי מיר זעען עס ביי מחלוקת קרח, וואָס צוזאַמען מיט זיין קריגן אויף כהונת אהרן איז ער אויך געקומען 63 מיט פאַלשע טענות און שאלות וועגן מזוזה — „בית שהוא מלא ספרים מהו",[["54","54","צפע\"נ עה\"ת שמות שם. מהר\"ץ חיות סוטה שם."],["55","55","הל' מלכים פ\"ט סה\"א."],["56","56","כקושיית הכס\"מ ורדב\"ז שם."],["57","57","ועפ\"ז לשון הרמב\"ם (נעתק לעיל הערה 48) „כיון שנתנה תורה נצטוו ישראל כו'\" — לאו דוקא."],["58","58","ובזה מתורץ מש\"נ (ואתחנן ה, כז) תיכף לאחר מ\"ת „שובו לכם לאהליכם\", דמזה שנק' „אהליכם\" גם קודם „שובו גו'\", מוכח, שלא היו צריכים קידושין מחדש לאחרי מ\"ת. וראה תו\"ש דלעיל הערה 4."],["59","59","אלא שצע\"ק לדעת רש\"י ש„גירשה\" — למה לא השיב לו כן, כנ\"ל ס\"ד והערה 42 [כי אף שלא הוצרך לגרשה מטעם זה — מ\"מ, מכיון שגירשה אין מקום מעיקרא להטענה „בת יתרו כו'\"] ?"],["60","60","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131097\" data-slug=\"likkutei-sichot\" data-id=\"1300131097\">לקו\"ש חי\"ג ע' 97</a> ובהערות שם."],["61","61","רמ\"א יו\"ד סו\"ס רמב. יבמות עז, א (וש\"נ). תוד\"ה אם שם. נמוק\"י שם."],["62","62","ומה שלא השיב אף א' מבנ\"י לזמרי הלימוד ד„יקח אשה\", וכפסק הלכה דאם שמעו ממנו קודם מעשה שומעין לו (רמ\"א שם) — אולי י\"ל שעדיין לא אמר משה לכל ישראל • הלימוד (דתושבע\"פ) מ„יקח אשה\" (מכיון שלא הי' נוגע להם), ואהרן ובניו — ה\"ה קרובים של משה ואין נאמנים. או י\"ל שנתעלמה מהם גם הלכה זו (משא\"כ משה, שנתעלמה ממנו רק ההלכה דהבועל ארמית כו', כנ\"ל בפנים השיחה ס\"א). ולהעיר מרמב\"ן דברים (א, יח): שלא יהי' לכבוד לו שיזכיר לדור הזה כי אשה כושית לקח."],["63","63","ירושלמי סנהדרין פ\"י ה\"א. תנחומא קרח ב. במדב\"ר פי\"ח, ג. פרש\"י ר\"פ קרח (רק „טלית כו'\"). •) להעיר מלשון פינחס (לענין ההלכה „הבועל ארמית כו'\") „לא כך למדתני כו'\""]]],[1300181300,"שיהא חייב במזוזה\" און תכלת — „טלית שכולה תכלת מה שתהא חייבת בציצית\" — און מ'געפינט ניט אַז משה זאָל אויף די שאלות ענטפערן מיט אַ לימוד פון תושבע\"פ 64 — ער האָט נאָר געזאָגט: „ואם בריאה יברא ה' גו'\" 65;\nאון די הסברה איז כנ\"ל: משה איז געווען אַ נוגע בדבר 66, און דערפאַר וואָלט ער סיי ווי ניט געווען באַגלויבט אויף דעם].\nז. די הוראה פון ענין הנ\"ל:\nניט אַלעמאָל זוכט מען צו ענטפערן יענעם אויף זיינע שאלות: אַמאָל איז יענער גאָר אויסן מיט זיין שאלה צו מתיר מאַכן אַ מדינית ! ווען זיין כוונה איז לשם שמים דאַרף זיין „ענה (אפילו אַ) כסיל כאולתו\" 67. ווען ער פרעגט אָבער אין דברי תורה מיט דער כוונה צו מתיר מאַכן דאָס וואָס תורה אסר'ט — דעמאָלט דאַרף זיין די הנהגה פון „אל תען כסיל כאולתו\" 68: דער וועג צו מנצח זיין אַזאַ מנגד אויף תורה איז ניט דורך שקו\"ט, נאָר מיט אַ תוקף וואָס איז למעלה מטעם ודעת.\n[און אַזוי אויך ביי יעדערן באַ זיך: ווען דער „מלך זקן וכסיל\" 69 — דער יצה\"ר — קומט מבלבל זיין, דאַרף מען זיך ניט אַריינלאָזן אין אַ שקו\"ט מיט אים, נאָר מ'דאַרף גלייך טאָן מיט תוקף — „משכהו לבית המדרש כו'\" 70].\nאון דאָס איז אויך געווען די הנהגה פון פינחס — „בקנאו את קנאתי\" 71: ער האָט זיך ניט אַריינגעלאָזט אין אַ שקו\"ט; ווייל אדרבה: דער דין 72 איז, אַז „הבא לימלך אין מורין לו\" — נאָר ער האָט מקנא געווען קנאת ה' („קנאתי\") און זיך מוסר נפש געווען צו הרג'נען זמרי 73.\nח. דער חג הגאולה פון י\"ב־י\"ג תמוז איז חל (ברוב השנים) אין דער וואָך פון פ' בלק — האָט דער ענין הנ\"ל אַ שייכות צו דעם חג הגאולה:\nדי הנהגה פון דעם רבי'ן, דעם בעל הגאולה והשמחה, איז געווען אין אַן אופן פון „בקנאו את קנאתי\": ניט קוקנדיק אויף די טענות פון געוויסע מענשן, אַז ס'איז ניטאָ קיין חיוב זיך צו מוסר נפש זיין על כל צעד ושעל וכו', איז ביים בעל הגאולה והשמחה געווען דער „בקנאו את קנאתי\": וויבאַלד עס איז דעם אויבערשטנ'ס אַ זאַך („קנאתי\"), האָט ער זיך נאָכאַנאַנד מוסר נפש געווען בפועל אויף הרבצת התורה והיהדות.\nדי מסירת נפש קען זיין בכמה אופ־נים. ומהם:\nא. בפרשתנו — ניט דורכן נשיא הדור — דער נשיא הדור איז געווען משה 74;",[["64","64","ורק אמר „חייבת דכתיב גדילים תעשה לך וגו' . . וכתבתם על מזוזות ביתך גו'\" (ירוש' שם)."],["65","65","קרח טז, ל."],["66","66","שהרי הי' אחי אהרן. ובפרט שמחלוקת קרח היתה גם על משה — ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081115\" data-slug=\"likkutei-sichot\" data-id=\"1300081115\">לקו\"ש ח\"ח ע' 104</a> ובהערות שם, וש\"נ. ועיי\"ש (ע' 106) שהעיקר ופנימיות מחלוקת קרח הי' על משה."],["67","67","משלי כו, ה. וראה שבת ל, ב."],["68","68","משלי שם, ד."],["69","69","קהלת ד, יג. קה\"ר שם. זהר ר\"פ וישב."],["70","70","סוכה נב, ריש ע\"ב. קידושין ל, ב."],["71","71","פינחס כה, יא."],["72","72","סנהדרין פב, א. רמב\"ם הל' איסו\"ב פי\"ב ה\"ה. טור אה\"ע סט\"ז. רמ\"א חו\"מ סתכ\"ה ס\"ד."],["73","73","ראה בארוכה לקו\"ש ח\"ד (ע' 1073), דמסנ\"פ דפינחס היא אמיתית ענין המסנ\"פ, שלמעלה מכל מדידה והגבלה, מבחי' יחידה. וראה לקמן ע' 319 ואילך."],["74","74","ראה פרש\"י חוקת כא, כא: שנשיא הדור כו'."]]],[1300181301,"אין אַן אופן פון גבורה 75 (וואָס דער־פאַר געפינט מען אַז פינחס — הוא אליהו 76 — האָט געזאָגט „קנא קנאתי לה' אלקי צבאות גו'\" 77 און האָט ניט געפונען אַ זכות אויף אידן<sup data-n=\"78\">78</sup>.\nב. ווי ביים בעל הגאולה והשמחה: „בקנאו את קנאתי\" דער נשיא הדור אַליין,\n[ובאמת קען מען זאָגן, אַז אויך ביי פינחס, איז די נתינת כח אויף דעם „קנאו את קנאתי\" געקומען פון משה 79 (דער נשיא הדור): דורך זיין זאָגן „קריינא דאיגרתא איהו ליהוי פרוונקא\" 80 האָט ער געגעבן פינחס דעם כח צו מקנא זיין קנאת ה'];\nאין אַן אופן פון חסדים — ווי דער־ציילט שוין פיל מאָל 81, אַז דער בעל הגאולה והשמחה האָט געבעטן זיין פאָטער, דער רבי נ\"ע, אַז זיין נשיאות זאָל זיין בחסד וברחמים, דער אויפטו, אַז אויך אַן ענין פון „קנאו את קנאתי\" ווערט דורכגעפירט אין אַן אופן פון „טוב עין הוא יבורך\" 82 — בחסד וברחמים 83.\n(משיחות י\"ג תמוז, וש\"פ מטו\"מ, תשכ\"ט)",[["75","75","ראה זח\"ג רלז, ב ואילך — שייכות דפינחס ליצחק, גבורות."],["76","76","נסמן בלקו\"ש ח\"ד ע' 1071 הערה 8. ח\"ח ע' 170 הערה 59."],["77","77","מ\"א יט, י. שם, יד."],["78","78","זח\"א צג, א. וראה הנסמן בנצוצי זהר שם."],["79","79","נוסף על פשטות הענין, ששאל קודם אצל משה „לא כך למדתני כו'\"."],["80","80","סנהדרין שם."],["81","81","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021226\" data-slug=\"likkutei-sichot\" data-id=\"1300021226\">לקו\"ש ח\"ב ע' 502</a>. וראה ספר השיחות תש\"ג ע' 12. ועוד."],["82","82","משלי כב, ט. ובנדרים (לח, א) ועוד — דקאי על משה. ובזח\"ג (קל, א) דורשו על יוסף — שמו (הראשון) של בעל הגאולה והשמחה (וראה סה\"ש תש\"ה ע' 61. ועוד)."],["83","83","להעיר ממשנ\"ת בארוכה (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081176\" data-slug=\"likkutei-sichot\" data-id=\"1300081176\">לקו\"ש ח\"ח ע' 165</a> ואילך) דקנאות דפינחס היתה מצד החסד והאהבה (שלכן „בא הכתוב ויחסו אחר אהרן\" — פרש\"י ר\"פ פינחס). וראה גם זח\"ג רלז, סע\"ב ואילך. וי\"ל שזה הי' ע\"י הנתינת כח ממשה, נשיא הדור, כנ\"ל בפנים."]]],[1300181302,"<h3>בלק ד</h3>\nא. דער דין1 איז אז די הפטורה פון אַ פרשה מוז זיין „מענין הפרשה”, און נאָך מער — „מעין” פון דעם סיום הפרשה2.\nאַזוי אויך די שייכות פון פרשת בלק מיט איר הפטורה איז לכאורה אַ קלאָרע: אין דער הפטורה3 ווערט דערציילט ווי דער אויבערשטער זאָגט צו אידן: „עמי זכר נא מה יעץ בלק מלך מואב ומה ענה אותו בלעם בן בעור מן השטים גו'” — וואָס דאָס איז דער תוכן פון פ' בלק.\nעס איז אָבער מובן — ובפרט ע\"פ הידוע4, אז מעיקרה איז די הפטורה געקומען במקום פון דער גאַנצער קריאת השוי\"ט — אז די שייכות צווישן דער הפטורה מיט דער סדרה איז ניט בלויז אין אַן איינציקן פסוק, נאָר אין איר תוכן כללי; און לויט הידוע5 אז דער תוכן פון אַן ענין איז מרומז אין זיין התחלה וראש, איז פאַרשטאַנדיק, אז ס'איז דאָ אַ שייכות צווישן התחלת ההפטורה6 — „והי' שארית יעקב בקרב עמים רבים גו' אשר לא יקוה לאיש ולא ייחל לבני אדם” — מיט (סיום) פ' בלק.\nב. די הפטורה רעדט וועגן דעם זמן פון התחלת הגאולה. ד.ה. ניט וועגן דעם זמן ווען ס'וועט שוין זיין „משיח ודאי”, לאחרי ווי ער וועט פאַרענדיקן אַלע מלחמות און „אהפוך7 אל עמים גו' לעבדו8 שכם אחד”9 — וואָרום אין דער הפטורה ווערט דערציילט ווי עס וועלן געפירט ווערן מלחמות מיט די עמים, אומות העולם — „והי' שארית יעקב בגוים גו' כארי' בבהמות יער גו' ורמס וטרף גו'”10;\nנאָך מער: ניט נאָר וועט אין דעם זמן המדובר בהפטורה נאָך זיין רע מבחוץ — פון אומות העולם, נאָר ס'איז נאָך פאַראַן רע מבפנים — ביי אידן גופא, ווי ער זאָגט11, „והכרתי כשפים מידך גו' והכרתי פסיליך גו' ונתשתי אשיריך גו'”; און דער רע איז מיט אַזאַ תוקף, אז מ'דאַרף אָנקומען צו אַ סיוע מלמעלה בכדי פון אים פטור צו ווערן, ווי דער פסוק איז מדייק: „והכרתי”, „ונתשתי”,\nווייל די הפטורה רעדט וועגן דעם זמן פון התחלת הגאולה, ווען עס וועלן זיין די לעצטע הכנות צו דער גאולה שלימה.\nאַזוי אויך די סדרה, פ' בלק, רעדט וועגן אַן ענלעכן זמן, פאַרן אַריינקומען אין ארץ ישראל צום ערשטן מאָל; אידן",[["1","1","טושו\"ע (ודאדה\"ז) או\"ח ר\"ס רפד. טור ורמ\"א שם סתכ\"ח (ס\"ח)."],["2","2","ראה ב\"י לטואו\"ח (ועד\"ז בשו\"ע אדה\"ז) סרפ\"ג (מתוד\"ה כיון — מגילה כג, א): א\"כ יהא צריך למפטיר בדסליק מיני'. וברמ\"א הנ\"ל (ועד\"ז בשו\"ע שם סרפ\"ד ס\"ז. שו\"ע אדה\"ז שם סי\"ג): וכשקורין שתי פרשיות מפטירין באחרונה."],["3","3","מיכה ו, ה."],["4","4","אבודרהם. לבוש, ב\"ח, ט\"ז, ושו\"ע אדה\"ז ר\"ס רפד."],["5","5","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051058\" data-slug=\"likkutei-sichot\" data-id=\"1300051058\">לקו\"ש ח\"ה ע' 58</a> הערה 12. ועוד."],["6","6","מיכה ה, ו."],["7","7","צפני' ג, ט."],["8","8","כ\"ה בכתוב. אבל ברמב\"ם (שבהערה הבאה): „ולעבדו”. וראה לקו\"ש ח\"ה ע' 420 בהערה. ובארוכה — בהערה שבסוף המכתב די\"ג תשרי תשל\"ו (לקו\"ש חי\"ד ע' 414)."],["9","9","ראה בכ\"ז רמב\"ם הל' מלכים ספי\"א."],["10","10","מיכה שם, ז-ח."],["11","11","שם, יא-יג."]]],[1300181303,"זיינען דעמאָלט שוין געווען „בערבות מואב מעבר לירדן ירחו”12, גרייט אַריינצוגיין אין א\"י, בדוגמא צו דער כניסה לא\"י ביי דער גאולה העתידה; ובפרט עפ\"י הידוע13 אז אלמלא החטא, וואָלט ביי דער ערשטער כניסה לא\"י געווען די גאולה שלימה.\nג. די הכנה צו דער גאולה איז, ווי ער זאָגט אין התחלת ההפטורה, „אשר לא יקוה לאיש ולא ייחל לבני אדם”: כאָטש עס איז נאָך פאַר דער גאולה שלימה, פונדעסטוועגן וועט זיין דער סדר אז מ'וועט זיך ניט דאַרפן פאַרלאָזן און ניט דאַרפן אָנקומען צו מענטשן — וואָס דאָס איז כולל אויך אידן, ווי עס שטייט14 „ארור הגבר אשר יבטח באדם”, און „אתם קרויין אדם”15 — נאָר מ'וועט זיך פאַרלאָזן בלויז אויף דעם אויבערשטן, וכמש\"נ16 „ברוך הגבר אשר יבטח בה'”.\nוויבאַלד אז דער פסוק רעדט אין דעם זמן פון התחלת הגאולה, איז מובן, אז מיט דעם וואָס ער זאָגט „לא יקוה לאיש גו'”, איז דער פסוק שולל ניט נאָר אַ הנהגה אסורה, אַ הנהגה היפך התורה — אויף וועלכער עס שטייט „ארור הגבר אשר יבטח באדם” — נאָר אפילו אַ הנהגה פון „יקוה לאיש” וואָס האָט אַן אָרט ע\"פ תורה, וועט דעמאָלט אויך ניט זיין:\nעס שטייט17 דאָך „וברכך ה\"א בכל אשר תעשה”, און דער ספרי18 טייטשט עס אָפ: „יכול יהא יושב19 ובטל ת\"ל בכל אשר תעשה”. ד.ה. אז ע\"פ תורה דאַרף מען מאַכן אַ כלי אין דרך הטבע20, און „אין סומכין על הנס”21; און וויבאַלד אז בדרך הטבע דאַרף מען אָנקומען „לאיש” — און אפילו צו ניט אידן להבדיל — איז דאָך אַן אָרט עפ\"י תורה אויף דער הנהגה פון „יקוה לאיש”.\n— ס'איז ניט קיין סתירה דערפון צום אָנזאָג „ארור הגבר אשר יבטח באדם” — ווייל ווען מ'מאַכט אַ כלי טבעי, איז מען ניט בוטח אויף די דרכי הטבע („יקוה לאיש”) מצד עצמם, נאָר מ'איז בוטח אויף דעם אויבערשטן, אז ער וועט אים העלפן דורך דעם כלי ולבוש וואָס ער האָט צוגעגרייט אין דרך הטבע22.\nאון אין דעם באַשטייט דער אויפטו פון דעם זמן הגאולה: דעמאָלט וועט זיין „כטל מאת ה' גו'” — „שאין בא לעולם ע\"י אדם ולא יבקשו בני אדם עליו כך לא יקוה ישראל לעזרת איש כ\"א לה'”23.\n[ע\"ד ווי חסידות24 טייטשט דעם פסוק25 „טוב לחסות בה' מבטוח באדם” — וואָס פונים לשון „טוב לחסות בה'",[["12","12","ס\"פ חוקת."],["13","13","נדרים כב, ב. וראה שמו\"ר רפל\"ב. ובכ\"מ."],["14","14","ירמי' יז, ה."],["15","15","יבמות סא, רע\"א."],["16","16","ירמי' שם, ז."],["17","17","ראה טו, יח."],["18","18","עה\"פ."],["19","19","כן הובא בכ\"מ. ובספרי שלפנינו: יכול בטל. וביל\"ש (עה\"פ): יכול כשעומד ובטל כו'."],["20","20","ראה בארוכה דרך חיים בהקדמה. סהמ\"צ להצ\"צ מצות תגלחת מצורע פ\"ב ואילך. קונטרס ומעין מאמר יז ואילך."],["21","21","ראה פסחים סד, ב. זח\"א קיא, ב. קיב, ב. וראה ברכות לה, ב: הרבה עשו כו' כרשב\"י ולא עלתה בידן."],["22","22","ראה במקומות שצויינו בהערה 20. ובארוכה — ד\"ה וידעת תרנ\"ז."],["23","23","פרש\"י מיכה ה, ו."],["24","24","לקו\"ת שמע\"צ צ, ד. צא, ב. יהל אור — להצ\"צ — לתהלים עה\"פ. סד\"ה ולא זכר תרפ\"ח."],["25","25","תהלים קיח, ח."]]],[1300181304,"מבטוח באדם” איז מובן, אז אויך „בטוח באדם” איז מותר און אַ דרך בהנהגה, נאָר „לחסות בה'” איז בעסער —\nאז „בטוח באדם” מיינט אין דעם אדם העליון, בחי' ממלא כל עלמין, וואָס מצד מדריגת ממכ\"ע דאַרף זיך אַ מענטש משתדל זיין אויף צו מאַכן אַ כלי און לבוש אין דרכי הטבע אין וועלכן עס זאָל שורה זיין די ברכת ה'26; און דערי־בער איז „טוב לחסות בה'”, בחי' סוכ\"ע, וואָס מצד דער מדריגה דאַרף ניט זיין די השתדלות אין דרכי הטבע, נאָר „והוא יכלכלך”27, דער אויבערשטער מאַכט אויך די כלי26].\nד. דער תכלית הכוונה איז ניט אז די הנהגת הטבע זאָל בטל ווערן, נאָר אדרבה, צו מברר זיין און אויפהויבן די הנהגת הטבע28, ביז עס זאָל זיין גלוי לעין כל אז אויך טבע איז מיוחד מיטן אויבערשטן.\nדערפון איז פאַרשטאַנדיק בעניננו, אז דער פשט פון „לא יקוה לאיש” איז ניט אז עס וועט בטל ווערן די הילף פון דעם „איש”, נאָר אז דעמאָלט וועט טבע גופא זיין בתכלית היחוד מיט אלקותו ית', ביז מ'וועט אין דעם זען (ניט עזרת איש, נאָר) בלויז עזרת ה':\nאין דעם ענין פון „אשר תעשה” קענען זיין צוויי אופנים:\nא) כאָטש ער ווייס אז טבע מצד עצמו האָט ניט קיין מציאות, ס'איז נאָר „כגרזן ביד החוצב בו”22, פונדעסטוועגן, ווי־באַלד דער אויבערשטער האָט געהייסן עס זאָל זיין — „תעשה”, מ'זאָל מאַכן אַ כלי אין דרך הטבע, פאַרנעמט טבע ביי אים אַן אָרט; טאַקע ניט מצד טבע אַליין — אָבער מצד ציווי הקב\"ה באַקומט טבע אַ חשיבות אין זיינע אויגן29.\nב) ער טוט אין טבע נאָר ווייל דער אויבערשטער האָט אַזוי אָנגעזאָגט, עס פאַרנעמט אָבער ביי אים קיין אָרט ניט, ווייל ער זעט אין דעם נאָר אַ מיטל צו אויספירן דעם רצון הבורא30.\nוואָס דאָס איז דער ביאור31 אינעם מאמר רז\"ל32 אויפן פסוק33 „והי' אמונת עתך גו'”, אז „אמונת זה סדר זרעים” — „שמאמין בחי העולמים וזורע”:\nכאָטש דאָס איז אַן ענין טבעי אז בשעת מען זייט איז מצמיח, און ס'איז קיין נפקא מינה ניט ווער ס'איז זורע — צי אַ איד צי להבדיל אַ ניט איד, אָדער אפילו דאָס קומט דורך אַ קערנדל וואָס פאַלט אַריין אין דער ערד פון זיך אַליין (שלא ע\"י פעולת אדם) — איז בטבע פון דער ערד להצמיח;\nאון נאָך מער: די טבע איז נקבע גע־וואָרן אין דער ערד אין אַן אופן, ווי עס שטייט34, „זרע וקציר גו' לא ישבו־תו” —",[["26","26","ראה בכ\"ז — תו\"ח ויחי ד\"ה בן פורת יוסף פי\"ג. יהל אור — להצ\"צ — לתהלים מ, ה. ד\"ה ולא זכר הנ\"ל."],["27","27","ל' הכתוב — תהלים נה, כג."],["28","28","ראה לקו\"ד ח\"ד תשנב, ב ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051092\" data-slug=\"likkutei-sichot\" data-id=\"1300051092\">לקו\"ש ח\"ה ע' 80</a>. ועוד."],["29","29","ע\"ד משנ\"ת בלקו\"ש ח\"ד (ע' 1044) בטענת המרגלים „כביכול אפילו בעה\"ב אינו יכול להוציא כליו” — דאף שהנהגת העולם היא „כליו” של הקב\"ה, שהוא ית' ה„בעה\"ב” על הנהגת העולם, מ\"מ, מכיון שרצונו ית' בהנהגת העולם — „אינו יכול להוציא כליו”."],["30","30","להעיר ממדר\"א רפל\"ג: „וכי יצחק זרע דגן ח\"ו אלא לקח כו' וזרע צדקה כו'”. נתבאר בארוכה ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051086\" data-slug=\"likkutei-sichot\" data-id=\"1300051086\">לקו\"ש ח\"ה ע' 74</a>."],["31","31","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011230\" data-slug=\"likkutei-sichot\" data-id=\"1300011230\">לקו\"ש ח\"א ע' 216</a>. ע' 240."],["32","32","שבת לא, סע\"א. תוד\"ה אמונת שם (בשם הירושלמי)."],["33","33","ישעי' לג, ו."],["34","34","נח ח, כב."]]],[1300181305,"פונדעסטוועגן, נאָך דעם אַלעמען, באַקומט ניט די טבע קיין חשיבות ותפיסת מקום ביי אַ אידן; און ווען ער איז זורע טוט ער דאָס ניט ווייל עפ\"י טבע וועט זריעה ברענגען אַ צמיחה, נאָר בלויז ווייל ער איז „מאמין בחי העולמים” דערפאַר „וזורע”.\nה. דער חילוק צווישן די צוויי אויבנגערעדטע הנהגות איז ניט בלויז באופן ובהרגש מדת הבטחון, נאָר דער־פון ווערט אויך „נשתלשל” אַ חילוק בהנהגה בפועל אין מחשבה דיבור ומעשה:\nבשעת דער „אשר תעשה” איז ביי אים אַ מציאות פאַר זיך, טבע פאַרנעמט ביי אים אַן אָרט, דאַן זיינען ביי אים דער „תעשה” און תומ\"צ צוויי באַזונדערע ענינים. און ווען עס קומט צו אַ סתירה צווישן תומ\"צ און דער התעסקות אין דרכי הטבע\n— ולדוגמא: אויב ער וועט מאריך זיין בתפילה — קען ער אָנווערן באַ־קאַנטשאַפט בעסקיו וכדומה; אויב ער וועט מהדר זיין אין נתינת צדקה בריבוי — וועט אים אפשר אויספעלן געלט אויף צו אַריינלייגן אין געשעפט, וכיו\"ב —\nאיז דאָס ביי אים אַן ענין פון „ולאום מלאום יאמץ”35: אפילו ווען ער איז מוותר אויף דער התעסקות אין די דרכי הטבע (וויסנדיק אז „ברכת ה' היא תעשיר”36 און דרכי הטבע זיינען בלויז אַ כלי און לבוש צו „ברכת ה'”) און טוט אין תומ\"צ — איז דאָס אַלץ אין אַן אופן פון מלחמה און התגברות אויף דער נפש הבהמית; און עס בלייבט אַלעמאָל די מעגלעכקייט פון „ולאום מלאום יאמץ” להיפך, ח\"ו — אז דער צד המנגד זאָל גובר זיין.\nבשעת אָבער דער „תעשה” פאַר־נעמט ביי אים קיין אָרט ניט, ער טוט עס נאָר בכדי צו מקיים זיין דעם רצון הבורא — איז ביי אים דאָס גופא אַן ענין פון עבודת ה': ביי אים איז דער „וכל מעשיך”37 און „בכל דרכיך”38 ניט אַ באַזונדערע זאַך פון „לשם שמים”37 און „דעהו”38, נאָר זיי זיינען דורכגעדרונ־גען מיטן „לשם שמים” און „דעהו”, ביז ס'איז כולא חד.\nאון וויבאַלד ביי אים איז ניטאָ קיין מציאות אויסער דעם רצון העליון, איז פאַרשטאַנדיק, אז איין מצוה קען ניט זיין בסתירה צו אַ צווייטער מצוה, נאָר אדרבה: „מצוה גוררת מצוה”39.\nו. דער חילוק צווישן די צוויי הנהגות הויבט זיך ניט אָן אין אַן אָפע־נעם „פועל ממש” — אז דער יצה\"ר זאָל מלכתחילה קומען איינריידן אַ אידן ער זאָל ח\"ו עובר זיין אויפן רצון העליון — נאָר פון אַ „חוט השערה”: „היום” בהתחלה איז דער יצה\"ר כלומר'שט מסכים אז די התעסקות אין דרכי הטבע טאָר ניט זיין בסתירה צו קיום התומ\"צ, ער איז נאָר מדגיש אז תורה גיט אַן אָרט און אַ חשיבות צו טבע; אָבער „למחר”, סוף־סוף, מאַכט ער די דרכי הטבע פאַר אַן עיקר.\nוכפירוש כ\"ק מו\"ח אדמו\"ר40 אין דעם מאמר חז\"ל41 „כך אומנתו של",[["35","35","ל' הכתוב — תולדות כה, כג. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310018\" data-slug=\"tanya\" data-id=\"3401310018\">תניא פי\"ג</a>: ואף גם זאת כו'."],["36","36","משלי י, כב."],["37","37","אבות פ\"ב מי\"ב."],["38","38","משלי ג, ו."],["39","39","אבות פ\"ד מ\"ב."],["40","40","ד\"ה א\"ר אושעיא תרפ\"ט פ\"ז (סה\"מ קונט' ח\"א לז, א). וראה לקו\"ש ח\"ג ע' 900."],["41","41","שבת קה, ב."]]],[1300181306,"יצה\"ר היום אומר לו עשה כך”: דער יצה\"ר הויבט ניט אָן איינצוריידן אַ אידן ער זאָל טאָן פאַרקערט פון זיין רצון אמתי42 (און עובר זיין ח\"ו אויפן רצון העליון), אדרבה, ער זאָגט אים „עשה כך”: ער איז מסכים אז דער איד זאָל מקיים זיין תומ\"צ, איז אים מסביר ווי עס האַלט אויס עפ\"י שכל פון נפש הבהמית והיצר; און דורך דעם וואָס ער מישט אַריין זיין מציאות אין קיום התומ\"צ און איז אים מרגיל אז ער דאַרף אין דעם האָבן זיין (דעם יצה\"ר'ס) הסכמה, דער־פירט ער אז „ולמחר אומר כו' עד שאומר לו עבוד ע\"ז”.\nאון דעריבער איז דער וועג צו באַ־וואָרענען זיך כדבעי פון תחבולות היצה\"ר, ניט דורך אַן עבודה עפ\"י טעם ודעת — ווייל טו\"ד גיט אַן אָרט פאַר דער מציאות פון טבע; נאָר דורך ביטול ומסנ\"פ צום רצון העליון, למעלה מטו\"ד, וואָס דעמאָלט איז ביי אים ניטאָ קיין מציאות אויסער דעם רצון העליון.\n[מעין וע\"ד דעם חילוק (הנ\"ל ס\"ג) צווישן „לחסות בה'” און „בטוח באדם”:\nמצד בחי' „בטוח באדם”, ממכ\"ע (וואָס דוגמתה בעבודת האדם איז אַן עבודה עפ\"י טו\"ד), דאַרף זיין די השתדלות אין דרכי הטבע, ווייל לגבי דער מדריגה האָבן זיי אַ תפיסת מקום;\nמשא\"כ מצד „לחסות בהוי'”, בחי' סוכ\"ע (ובעבודת האדם — ביטול שלמעלה מטו\"ד), האָבן דרכי הטבע קיין תפיסת מקום ניט, און דעריבער איז דער סדר — „והוא יכלכלך”: עס זיינען טאַקע פאַראַן „כלים”, אָבער זיי קומען מלמעלה. ע\"ד ווי גערעדט פריער, אז אויך ווען דער מענטש טוט בדרכי הטבע זיינען זיי ביי אים קיין מציאות ניט, ביז ס'איז ניט שייך זאָגן אז ס'איז דאָ „עזרת איש”, ווייל די דרכי הטבע זיינען חד מיטן אויבערשטן].\nאון דאָס איז וואָס די הכנה צו דער גאולה איז „לא יקוה לאיש גו'”: דע־מאָלט וועט מען אינגאַנצן אַראָפנעמען דעם העלם והסתר פון טבע, ביז מ'וועט זען בעיני בשר ווי טבע גופא איז אלקות; און דעריבער וועט דאַן זיין דער סדר „כטל מאת ה' גו' לא יקוה לאיש ולא ייחל לבני אדם” [ע\"ד „והוא יכלכלך”].\nז. עפ\"י כהנ\"ל וועט מען פאַרשטיין די שייכות פון דער הפטורה צו סיום פ' בלק, וואו עס ווערט דערציילט וועגן דעם חטא פון בעל פעור, און ווי די מסירת נפש43 פון פינחס האָט דעם חטא מתקן געווען (וכמש\"נ44 „ויכפר על בני ישראל”):\nעס איז מבואר אין חסידות45, אז דער שורש פון חטא בעל פעור — „שפוערין כו' ומוציאין רעי וזו היא עבודתו”46 — איז דאָס וואָס מען גיט אַ חשיבות צו תענוגים גשמיים, וואָס זיי זיינען בלויז די פסולת פון דעם תענוג שלמעלה.\nווי קומט עס אז מ'זאָל מאַכן אַן עיקר פון (תענוגים גשמיים) פסולת? נעמט זיך דאָס דערפון וואָס דרכי הטבע פאַר־נעמען ביי אים אַן אָרט כנ\"ל, און דאָס",[["42","42","ראה רמב\"ם הל' גירושין ספ\"ב."],["43","43","שסיכן עצמו להרוג נשיא שבט שמעון אף שנתקבצו כו', ועוד — ועד שהוזקק לכו\"כ נסים (ראה תיב\"ע, ספרי ותנחומא ס\"פ בלק, סנה' פב, ב)."],["44","44","פינחס כה, יג."],["45","45","לקו\"ת ואתחנן יא, ג. ד\"ה ונשב בגיא — סה\"מ אתהלך־ליאזנא בסופו. סה\"מ תקס\"ב ע' פח ואילך. וראה (בהבא לקמן ס\"ז-ח) <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041326\" data-slug=\"likkutei-sichot\" data-id=\"1300041326\">לקו\"ש ח\"ד ע' 1327</a> ואילך."],["46","46","פרש\"י פרשתנו כה, ג. וראה גם סנהדרין סד, א."]]],[1300181307,"דערפירט אז ער ווערט ר\"ל מושקע אין ענינים גשמיים.\nדערמיט איז אויך מובן דער מחז\"ל47 בנוגע הכפרה אויפן חטא בעל פעור, אז „עד עכשיו לא זז אלא עומד ומכפר עד שיחיו המתים” — ווייל די טהרה וכפרה בשלימות פון דעם חטא וועט ערשט זיין לעת\"ל, ווען ס'וועט זיין די שלימות הבירור אין טבע און מ'וועט דערקענען אז טבע איז מיוחד בתכלית מיט אלקות, ובמילא וועט ניט זיין די אפשריות פון מאַכן אַן עיקר פון ענינים גשמיים.\nאון דעריבער קומט די כפרה דורך דער מס\"נ פון פינחס, אַזאַ מס\"נ אויף וועלכער תורה אַליין זאָגט „אין מורין לו”48, און אפילו דערפון ווערט פינחס ניט נתפעל און איז זיך מוסר נפש. וואָס דאָס איז אַ מס\"נ שלמעלה מטו\"ד אפילו דקדושה. און ווי גערעדט פריער, אז דוקא דורך ביטול למעלה מטו\"ד (אפילו פון קדושה) קען מען זיך באַוואָרענען כדבעי ניט מפריד זיין צווישן טבע און אלקות, כאָטש תורה זאָגט „וברכך ה\"א בכל אשר תעשה”.\nח. דערמיט איז אויך מובן די שייכות פון ענין הנ\"ל צו דער כניסה לא\"י (וואָס גאָר קרוב צו דעם זמן הכניסה זיינען געווען די מאורעות פון פ' בלק, כנ\"ל ס\"ב):\nאין מדבר איז געווען דער מן — אַ הנהגה נסית וואו ס'איז ניט שייך געווען צו מאַכן אַ טעות אז מעשה בני אדם קען אין דעם עפעס אויפטאָן, וכמש\"נ49 „ולא העדיף המרבה והממעיט לא החסיר”, און דער מן איז געווען נאָר אויף דעם טאָג, עס האָט געמוזט זיין בטחון גמור, דבר יום ביומו50, אין השי\"ת;\nמשא\"כ נאָך דער כניסה לא\"י, ווען עס האָט זיך אָנגעהויבן51 דער סדר עבודה פון „ארץ נושבת”52 — האָט מען גע־דאַרפט פריער באַוואָרענען דעם ענין פון „בעל פעור”, אז כאָטש עס הויבט זיך אָן אַ סדר עפ\"י טבע, דאַרף אויך דעמאָלט זיין „לא יקוה לאיש גו'”: מ'זאָל וויסן אז טבע איז ניט קיין מציאות לעצמה, און אויך דאַן פאָדערט זיך דער זעלבער בטחון אין דעם אויבערשטן, ווי ס'איז געווען אין מדבר.\nט. דאָס איז אויך די הוראה אין די לעצטע טעג פון זמן הגלות, ווען מען גרייט זיך צו דער כניסה לא\"י ע\"י משיח צדקנו:\nכאָטש מ'שטייט נאָך אין דעם חושך כפול ומכופל53 פון זמן הגלות, היפך פון אתחלתא דגאולה54 — און ווי מ'זעט במוחש — פונדעסטוועגן, וויבאַלד אַלע ענינים פון לעת\"ל זיינען „תלוי במעשינו ועבודתנו כל זמן משך הגלות”55",[["47","47","ספרי פינחס שם. וראה סנהדרין פב, ב: וראוי' כפרה זו כו'. ועיג\"כ תוד\"ה מפני — סוטה יד, א."],["48","48","סנהדרין שם, א. רמב\"ם הל' איסו\"ב פי\"ב ה\"ה. טור אה\"ע סט\"ז. רמ\"א חו\"מ סתכ\"ה ס\"ד."],["49","49","בשלח טז, יח."],["50","50","יל\"ש בשלח רמז רנח. ועד\"ז יומא עו, א."],["51","51","ובפרט שכבר כבשו ארץ סיחון ועוג. אבל להעיר מפרש\"י בשלח שם, לה. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081200\" data-slug=\"likkutei-sichot\" data-id=\"1300081200\">לקו\"ש ח\"ח ע' 189</a>."],["52","52","בשלח שם."],["53","53","הלשון „כפול ומכופל” — כי זה גופא שישנם טועים, ר\"ל, ש„שמים חושך לאור” לומר על מצב של גלות שהוא אתחלתא דגאולה, ה\"ז „חושך” והסתר ב„חושך” הגלות עצמו. וע\"פ פי' הבעש\"ט (הובא בתוי\"י ר\"פ בראשית) עה\"פ (וילך לא, יח) „ואנכי הסתר אסתיר פני ביום ההוא”, כי ההסתר עצמו הוא בהסתר, שאין מרגישים אותו — ושמים „ההסתר אסתיר” לאתחלתא דגאולה!"],["54","54","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051161\" data-slug=\"likkutei-sichot\" data-id=\"1300051161\">לקו\"ש ח\"ה ע' 149</a> בהערה."],["55","55","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>."]]],[1300181308,"— ובפרט בדורנו זה ווען מ'מאַכט די לעצטע הכנות צו דער גאולה ע\"י משיח צדקנו, וכפתגם כ\"ק מו\"ח אדמו\"ר56 אז משיח איז „עומד אחר כתלנו”57, און נאָך מער: די „כותלי” הגלות ברענען שוין58 —\nדאַרף זיין אַ מעין (עכ\"פ) פון דער עבודה פון „לא יקוה לאיש גו'” אין דער עבודה פון כאו\"א, אז דרכי הטבע דאַרפן ניט האָבן קיין חשיבות, און דער בטחון דאַרף זיין נאָר אין דעם אוי־בערשטן,\nאון דורך דעם ווערט יעדערער „נגאל” פון דאגות וענינים המבלבלים — וואָרום בשעת מען טוט אין דעם „בכל אשר תעשה” בלויז צוליב אויס־פירן דעם רצון העליון, איז מען ניט טרוד אין דעם און ס'איז ניט מבלבל וכו' — אים איז נאָר נוגע אויספירן דעם רצון העליון;\nאון די גאולה פרטית59 וואָס ווערט אויפגעטאָן ביי כאו\"א, איז אויך די הכנה און כלי צו דער גאולה כללית ע\"י משיח צדקנו, ביז צו דעם „יום שכולו שבת ומנוחה לחיי העולמים”60.\n(משיחת ש\"פ בלק תשכ\"ג)",[["56","56","בה„קול קורא” שנדפס ב„הקריאה והקדושה” סיון תש\"א (אגרות קודש אדמו\"ר מהוריי\"צ נ\"ע ע' שסא ואילך)."],["57","57","ל' הכתוב — שה\"ש ב, ט."],["58","58","ראה מכתב כ\"ק מו\"ח אדמו\"ר — נדפס בהיום יום בתחילתו (ע' 12). וראה גם לקו\"ד ח\"ג ס\"ע 794. ועוד."],["59","59","ראה אגה\"ק ס\"ד."],["60","60","תמיד בסופה."]]],[1300181309,"<h3>חוקת בלק יב־יג תמוז</h3>\nא. מ׳האט שוין פיל מאל גערעדט וועגן דעם מאמר פון של״ה¹, אז אלע מועדי השנה, אפילו „מועדי דרבנן“, האבן א שייכות צו די פרשיות התורה אין וועלכע זיי זיינען חל. דערפון איז פארשטאנדיק, אז דער „חג הגאולה“² פון י״ב־י״ג תמוז — ווען דער רבי דער שווער איז אינגאנצן באפרייט געווארן פון זיין מאסר און גלות — האט א שייכות צום תוכן פון די פרשיות חוקת־בלק³.\nאון אין דעם גופא זיינען דא דריי נקודות: (א) די שייכות צו פ׳ חוקת, (ב) די שייכות צו פ׳ בלק, (ג) די שייכות צו ביידע סדרות צוזאמען, ווארום — ווי גערעדט פיל מאל⁴ — ווען צוויי סדרות זיינען מחוברות און מ׳לייענט זיי צוזא־מען אין שבת, איז זייער התחברות אין אן אופן אז זיי ווערן איין סדרה (די חלוקת הקריאה איז אויף שבעה קרואים, עס איז דא נאר איין הפטורה, ועוד); ובמילא איז פארשטאנדיק, אז אין צוגאב צום באזונדערן תוכן וואס איז דא אין יעדער סדרה בפני עצמה, איז דא א תוכן משותף פון ביידע סדרות (וואס דערפאר קענען זיי נתחבר ווערן אלס איין סדרה) — און די שייכות פון חג הגאולה י״ב־י״ג תמוז צו חוקת־בלק איז אויך צו זייער תוכן משותף (ווי ס׳איז מודגש אין קביעות שנה זו, וואס י״ב תמוז איז חל בשבת פ׳ חוקת־בלק)⁵.\nב. דער נאמען פון דער (ערשטער) סדרה איז „חוקת“. דער פשוט׳ער טייטש פון „חוקה“ איז — א ציווי וואס מען האט ניט קיין טעם אויף אים, און מ׳איז אים מקיים בלויז דערפאר ווייל „חקה חקקתי גזירה גזרתי“⁶ — דאס איז דער רצון פון דעם אויבערשטן.\nדער ענין פון „חוקה“ אין עבודת האדם איז די עבודה פון מסירת נפש⁷, וואס איז למעלה מטעם ודעת. ווארום שכל קען געפינען טעמים צו טאן אזעלכע זאכן וואס זיינען מוסיף אין מציאות ושלימות האדם, אבער ניט „להשליך חייו מנגד“, ער זאל ווערן „אויס“ מציאות⁸; דערמיט איז מען מבאר⁹ פארוואס „לא נאמר ענין המס״נ",[["1","1","חלק תושב״כ ר״פ וישב."],["2","2","בלשון כ״ק מו״ח אדמו״ר (במכתבו — נדפס בסה״מ קונטרסים ח״א רלו, א) — „מועד המועדים“. נתבאר ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041321\" data-slug=\"likkutei-sichot\" data-id=\"1300041321\">לקו״ש ח״ד ע׳ 1322</a>."],["3","3","בשנה זו חל י״ג תמוז בפ׳ פינחס. אבל נוסף לזה שהשחרור הי׳ ונודע לבעל הגאולה ביב תמוז (וביג תמוז הי׳ רק האמירה באופן רשמי — כי המשרד הי׳ סגור ביב תמוז — ראה ספר התולדות אדמו״ר מוהריי״צ ח״ג ע׳ 221) גם בשנה זו „מתברך“ הוא בכלל משבת (שלפניו —) פ׳ חו״ב. ובקביעות אחרת — חל בפ׳ בלק ומתברך משבת פ׳ חוקת."],["4","4","ראה בארוכה לקמן ע׳ 380־1 ובהערות שם."],["5","5","ולהעיר, שפרשיות חוקת־בלק מחוברות בהקביעות די״ב תמוז שחל בשבת."],["6","6","תנחומא פרשתנו (חוקת) ג. במדב״ר ריש פרשתנו. ועוד."],["7","7","כפשוטה — נוסף על ש„נפש“ פי׳ (ג״כ) „רצון“ וכמש״נ אין נפשי (ירמי׳ טו, א. הובא ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370166\" data-slug=\"torah-or\" data-id=\"3901370166\">תו״א לו, ב</a>. וראה סה״מ תש״ט ע׳ 227 בהערה)."],["8","8","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370443\" data-slug=\"torah-or\" data-id=\"3901370443\">תו״א צט, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380092\" data-slug=\"likkutei-torah\" data-id=\"4001380092\">לקו״ת ויקרא ד, ג</a>."],["9","9","סה״מ תרנ״ט ע׳ יג. סה״מ תש״ט ע׳ 121. וראה שערי אורה ד״ה וקבל היהודים פרק ח."]]]]});
